	//class functions.goldmine.model.GoldMineUtil
	var GoldMineUtil=(function(){
		function GoldMineUtil(){}
		__class(GoldMineUtil,'functions.goldmine.model.GoldMineUtil',true);
		GoldMineUtil.checkBombEnable=function(list,mediator,isBombedToday){
			var canBomb=false;
			var cannotBomb=true;
			var notArmyMember=false;
			var isBombed=isBombedToday;
			var gmv;
			/*for each*/for(var $each_gmv in list){
				gmv=list[$each_gmv];
				if(gmv.isShowBomb){
					canBomb=true;
					cannotBomb=false;
				}
			}
			if(canBomb){
				mediator.goldMinePanel.btnBombGoldMine.enabled=true;
				mediator.goldMinePanel.btnBombGoldMine.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("HELP_CHENGZHU"));
			}
			if(cannotBomb){
				mediator.goldMinePanel.btnBombGoldMine.enabled=false;
				mediator.goldMinePanel.btnBombGoldMine.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("TOUMORR_HELP"));
			}
			if(isBombed){
				mediator.goldMinePanel.btnBombGoldMine.enabled=false;
				mediator.goldMinePanel.btnBombGoldMine.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("TOUMORR_HELP"));
			}
		}

		GoldMineUtil.checkGetGoldMineEnable=function(list,mediator){
			var cannotHoe=true;
			var allNull=true;
			var canHoe=false;
			var gmv;
			/*for each*/for(var $each_gmv in list){
				gmv=list[$each_gmv];
				if (gmv.isShowNull==false){
					allNull=false;
				}
				if (gmv.isShowHoe==true){
					canHoe=true;
					cannotHoe=false;
				}
			}
			if (cannotHoe){
				mediator.goldMinePanel.btnGetGoldMine.enabled=false;
				mediator.goldMinePanel.btnGetGoldMine.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("PLEASE_NEED_UNION_MEMBER_COME"));
			}
			if (allNull){
				mediator.goldMinePanel.btnGetGoldMine.enabled=false;
				mediator.goldMinePanel.btnGetGoldMine.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("TODAYS_GOLD_HAVE_FINISHED"));
			}
			if (canHoe){
				mediator.goldMinePanel.btnGetGoldMine.enabled=true;
				mediator.goldMinePanel.btnGetGoldMine.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("CAN_GET_GOLD_NOW"));
			}
		}

		GoldMineUtil.swfLabelConvertFrameNum=function(label){
			var frame=0;
			switch (label){
				case "stop0":
					frame=1;
					break ;
				case "stop1":
					frame=47;
					break ;
				case "stop2":
					frame=97;
					break ;
				case "stop3":
					frame=148;
					break ;
				case "stop4":
					frame=197;
					break ;
				case "stop5":
					frame=212;
					break ;
				case "step1":
					frame=2;
					break ;
				case "step2":
					frame=48;
					break ;
				case "step3":
					frame=98;
					break ;
				case "step4":
					frame=149;
					break ;
				case "step5":
					frame=198;
					break ;
				case "stepnull":
					frame=300;
					break ;
				}
			return frame;
		}

		return GoldMineUtil;
	})()


