	//file:///e:/work/sgwork/h5sg2/sg4/src/utils/tiputil.as
	//class utils.TipUtil
	var TipUtil=(function(){
		function TipUtil(){}
		__class(TipUtil,'utils.TipUtil',true);
		TipUtil.getTextTipVO=function(text){
			var tipVO=new TextTipVO();
			tipVO.text=text;
			return tipVO;
		}

		TipUtil.getEffectEX=function(id){
			var effect="";
			var flagDic=ClientDataProxy.getClientDataProxy().flagInfo;
			var effectDic=ClientDataProxy.getClientDataProxy().effects;
			var effectId=flagDic[id]["effect1_id"];
			var effect_effect_Ex=LanguageRunner.getLanguageText(effectDic[effectId]["Effect_Ex"]);
			var effectValue=flagDic[id]["value1"];
			var temp=effect_effect_Ex.split("|")[2];
			if (temp=="%"){
				effectValue=effectValue / 1000;
			}
			effect=effect_effect_Ex.replace("|NUM|",effectValue);
			return effect;
		}

		TipUtil.getTipVOById=function(id,proxy){
			var itemInfo=ClientDataProxy.getClientDataProxy().itemInfo[id];
			var type=itemInfo["type"];
			var tipVo=null;
			switch(type){
				case /*utils.Contants.ITEM_TYPE_FLAG*/3:;
					var tipFlagInfo=ObjectPool.borrow(FlagTipsVO);
					tipFlagInfo.update(itemInfo);
					tipFlagInfo.discript=TipUtil.getEffectEX(id);
					var level=ClientDataProxy.getClientDataProxy().flagInfo[id][["flag_lvl"]];
					tipVo=tipFlagInfo;
					break ;
				case /*utils.Contants.ITEM_TYPE_STONE*/4:;
					var stoneInfo=ObjectPool.borrow(StoneTipVO);
					var stone=ObjectPool.borrow(Object);
					stone["stone"]=itemInfo;
					var stoneTypeDic=ClientDataProxy.getClientDataProxy().stoneType;
					stone["lvl"]=stoneTypeDic[id]["stone_lvl"];
					stoneInfo.update(stone);
					tipVo=stoneInfo;
					break ;
				default :;
					var commonInfo=ObjectPool.borrow(ItemTipVO);
					commonInfo.itemVO=proxy.getInfoVOByID(id);
					tipVo=commonInfo;
					break ;
				}
			return tipVo;
		}

		TipUtil.setEquipVO=function(equipVO,dataEffect,chuanguInfos){
			equipVO.levelChuanGu=chuanguInfos.level;
			if(equipVO.realID==null){
				equipVO.realID=chuanguInfos.equipRealId;
			}
			EquipTip.setGuXun(chuanguInfos.guXun,equipVO.guxuns,dataEffect);
		}

		return TipUtil;
	})()


