				var tudiAwardVO=ObjectPool.borrow(TudiAwardVO);
				tudiAwardVO.achievement=rewardBean.achievement;
				tudiAwardVO.name=rewardBean.name;
				tudiAwardVO.pic=rewardBean.pic;
				tudiAwardVO.rewardId=rewardBean.rewardId;
				tudiAwardVO.stuId=rewardBean.stuId;
				tudiAwardVO.stuName=rewardBean.stuName;
				tudiAwardVO.giftId=rewardBean.giftId;
				var reward="";
