		__proto.getTalentInfo=function(note){
			var msg=note.body;
			this.panel.haveTalentText.text=msg.talentNum.toString();
			var resetNeed=ClientDataProxy.getClientDataProxy().maze_ruleDic[1]["maze_talent_chongzhi"];
			var haveGold=(this.getProxy(RoleProxy)).roleVO.gold;
			if(msg.TalentInfoList.length==0){
				this.panel.resetBtn.enabled=false;
				this.panel.resetBtn.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("ARRAY_TALENT_REST_ERROR"));
			}
			else if(resetNeed > Number(haveGold)){
				this.panel.resetBtn.enabled=false;
				this.panel.resetBtn.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("BUY_GOLD_NOT_ENOUGH"));
			}
			else{
				this.panel.resetBtn.enabled=true;
				this.panel.resetBtn.toolTip=null;
			};
			var talentConfigDic=ClientDataProxy.getClientDataProxy().maze_talent_config_Dic;
			var proxy=this.getProxy(ArrayTalentProxy);
			var talelntSkillDic=proxy.talentSkillDicByFloor;
			var haveTalentDic=new Dictionary();
			for(var j=0;j < msg.TalentInfoList.length;j++){
				var info=msg.TalentInfoList[j];
				haveTalentDic[info.talentId]=info;
			};
			var itemVOArr=[];
			var obj;
			/*for each*/for(var $each_obj in talentConfigDic){
				obj=talentConfigDic[$each_obj];
				var itemVO=ObjectPool.borrow(ArrayTalentLvUpRenderVO);
				itemVO.curFloor=int(obj["maze_talent_type"])%100;
				itemVO.maxLvUpCount=obj["maze_talent_config_num"];
				var floorId=obj["maze_talent_type"];
				itemVO.remainCount=itemVO.maxLvUpCount;
				var oneFloorItem=talelntSkillDic[floorId];
				var curSkillType=0;
				var tempArr=[];
				var lvUpCount=0;
				for(var i=0;i < oneFloorItem.length;i++){
					var floorItem=oneFloorItem[i];
					floorItem.canClickLvUp=true;
					if(floorItem.type !=curSkillType){
						if(haveTalentDic[floorItem.type]==null){
							tempArr.push(floorItem);
							curSkillType=floorItem.type;
						}
						if(haveTalentDic[floorItem.type] !=null && (haveTalentDic[floorItem.type]).talentId==floorItem.type && (haveTalentDic[floorItem.type]).talentLv==floorItem.lv){
							tempArr.push(floorItem);
							curSkillType=floorItem.type;
							floorItem.isLight=true;
							lvUpCount++;
						}
						else{
							floorItem.isLight=false;
						}
					}
				}
				if(lvUpCount==itemVO.maxLvUpCount){
					for(i=0;i < tempArr.length;i++){
						var setItemCanLvUp=tempArr[i];
						if(setItemCanLvUp.isLight==false){
							setItemCanLvUp.canClickLvUp=false;
						}
					}
				}
				itemVO.itemArr=tempArr;
				itemVOArr.push(itemVO);
			}
			this.panel.lvUpList.clear();
			this.panel.lvUpList.itemNumHorizontal=1;
			this.panel.lvUpList.update(itemVOArr);
			this.panel.lvUpList.verticalLineScrollPosition=this.posY;
			var renderArr=this.panel.lvUpList.getRenders();
			var isSetSelectItem=false;
			for(i=0;i < renderArr.length;i++){
				var renderItem=renderArr[i];
				if(this.curSelectTalentItem==null && i==0){
					this.curSelectTalentItem=renderItem.itemArr[0];
					this.curSelectTalentItem.showSelectEffect();
					isSetSelectItem=true;
				}
				else if(this.curSelectTalentItem !=null && !isSetSelectItem){
					for(var m=0;m < renderItem.itemArr.length;m++){
						var item=renderItem.itemArr[m];
						if(item.talentInfo !=null && this.getTalentSkillType(item.talentInfo.talentId)==this.getTalentSkillType(this.curSelectTalentItem.talentInfo.talentId)){
							item.showSelectEffect();
							this.curSelectTalentItem=item;
							isSetSelectItem=true;
							break ;
						}
					}
				}
			}
			if(this.curSelectTalentItem !=null){
				this.clickLvUpItem(this.curSelectTalentItem.talentInfo);
			}
		}

		__proto.clickSelectItemCallBack=function(event){
			var selectItem=event.sender;
			if(selectItem==null || selectItem.talentInfo==null){
				return;
			}
			if(this.curSelectTalentItem !=null){
				this.curSelectTalentItem.showSelectEffect(false);
			}
			this.curSelectTalentItem=selectItem;
			this.clickLvUpItem(this.curSelectTalentItem.talentInfo);
			this.curSelectTalentItem.showSelectEffect(true);
		}

