		__proto.getEquipGMVO=function(type,level){
			(level===void 0)&& (level=1);
			var vo;
			/*for each*/for(var $each_vo in this.gemGMequipDic){
				vo=this.gemGMequipDic[$each_vo];
				if(vo.gmEquipType==type && vo.gmEquipLevel==level){
					var tempVO=ObjectPool.borrow(BaoShiEquipGMVO);
					tempVO.gmEquipLevel=vo.gmEquipLevel;
					tempVO.gmEquipLingQi=vo.gmEquipLingQi;
					tempVO.gmEquipType=type;
					tempVO.gmEquipName=vo.gmEquipName;
					tempVO=this.getGmEquipNextGMVO(tempVO);
					return tempVO;
				}
			}
			return null;
		}

