		__proto.getGmEquipNextGMVO=function(equipGMVO){
			var level=int(equipGMVO.gmEquipLevel)+1;
			if(equipGMVO.gmEquipLevel >=/*functions.baoShi.model.BaoShiConfig.EQUIP_GM_MAX_LEVEL*/17){
				level=/*functions.baoShi.model.BaoShiConfig.EQUIP_GM_MAX_LEVEL*/17;
			}
			var vo;
			/*for each*/for(var $each_vo in this.gemGMequipDic){
				vo=this.gemGMequipDic[$each_vo];
				if(vo.gmEquipLevel==level && vo.gmEquipType==equipGMVO.gmEquipType){
					equipGMVO.gmEquipNextLevelLingQi=vo.gmEquipLingQi;
					equipGMVO.gmEquipNextLevelEffectArr=[];
					if(vo.gmEquipEffectArr !=null){
						var str;
						/*for each*/for(var $each_str in vo.gmEquipEffectArr){
							str=vo.gmEquipEffectArr[$each_str];
							equipGMVO.gmEquipNextLevelEffectArr.push(str);
						}
					}
					return equipGMVO;
				}
			}
			return null;
		}

		__proto.updateEquipInfo=function(msg){
			var equipVO=ObjectPool.borrow(ExpandEquipVO);
			equipVO.id=int(msg.equipId);
			equipVO.realID=msg.equipRealId;
			equipVO.location=msg.slot;
			equipVO.level=msg.equipLevel;
			equipVO.levelChuanGu=msg.level;
			equipVO.bindType=msg.bindtype;
			equipVO.attributesComprehensive=msg.equipAttribute;
			equipVO.equipGongmingId=msg.equipGongmingId;
			equipVO.equipGMVO=this.getGemEquipGMVO(equipVO.equipGongmingId);
			equipVO.equipLingqi=msg.equipLingqi;
			equipVO.guxun=msg.guXun;
			equipVO.generalID=msg.generalid;
			var gemArr=msg.gem.split(",");
			if(String(gemArr[0]).split(":")[0]==1){
				equipVO.hole1Gem=String(gemArr[0]).split(":")[1];
				equipVO.gem1RealId=String(gemArr[0]).split(":")[2];
			}
			else if(String(gemArr[0]).split(":")[0]==2){
				equipVO.hole2Gem=String(gemArr[0]).split(":")[1];
				equipVO.gem2RealId=String(gemArr[0]).split(":")[2];
			}
			if(String(gemArr[1]).split(":")[0]==2){
				equipVO.hole2Gem=String(gemArr[1]).split(":")[1];
				equipVO.gem2RealId=String(gemArr[1]).split(":")[2];
			}
			else if(String(gemArr[1]).split(":")[0]==1){
				equipVO.hole1Gem=String(gemArr[1]).split(":")[1];
				equipVO.gem1RealId=String(gemArr[1]).split(":")[2];
			};
			var copyExpandEquipVO=this.getNewExpandEquipVO(equipVO);
			var tipVO=ObjectPool.borrow(EquipTipVO);
			tipVO.equipVO=this.setGemEquipGMTipVO(copyExpandEquipVO);;
			EquipTip.setGuXunTip(copyExpandEquipVO,this.dataEffect);
			var renderVO=ObjectPool.borrow(BaoShiEquipRenderVO);
			renderVO.expandEquipVO=this.setExpandEquipVOGemInfoForTips(copyExpandEquipVO);
			renderVO.tipVO=tipVO;
			renderVO.selectable=true;
			this.sendNotification(/*global.NotificationType.BAO_SHI_UPDATE_EQUIP_INFO*/"BAO_SHI_UPDATE_EQUIP_INFO",renderVO);
		}

		__proto.receiveEquipBagInfo=function(msg){
			if(msg.pageIndex==0){
				this.equipBagList=new Dictionary();
				this.equipBagArray=[];
			}
			for (var i=0;i < msg.equipList.length;i++){
				var sli=msg.equipList[i];
				var equipVO=ObjectPool.borrow(ExpandEquipVO);
				equipVO.id=int(sli.equipId);
				equipVO.realID=sli.equipRealId;
				equipVO.location=sli.slot;
				equipVO.level=sli.equipLevel;
				equipVO.levelChuanGu=sli.level;
				equipVO.bindType=sli.bindtype;
				equipVO.attributesComprehensive=sli.equipAttribute;
				equipVO.equipGongmingId=sli.equipGongmingId;
				equipVO.equipGMVO=this.getGemEquipGMVO(sli.equipGongmingId);
				equipVO.equipLingqi=sli.equipLingqi;
				equipVO.guxun=sli.guXun;
				equipVO.generalID=sli.generalid;
				var gemArr=sli.gem.split(",");
				if(String(gemArr[0]).split(":")[0]==1){
					equipVO.hole1Gem=String(gemArr[0]).split(":")[1];
					equipVO.gem1RealId=String(gemArr[0]).split(":")[2];
				}
				else if(String(gemArr[0]).split(":")[0]==2){
					equipVO.hole2Gem=String(gemArr[0]).split(":")[1];
					equipVO.gem2RealId=String(gemArr[0]).split(":")[2];
				}
				if(String(gemArr[1]).split(":")[0]==2){
					equipVO.hole2Gem=String(gemArr[1]).split(":")[1];
					equipVO.gem2RealId=String(gemArr[1]).split(":")[2];
				}
				else if(String(gemArr[1]).split(":")[0]==1){
					equipVO.hole1Gem=String(gemArr[1]).split(":")[1];
					equipVO.gem1RealId=String(gemArr[1]).split(":")[2];
				};
				var copyExpandEquipVO=this.getNewExpandEquipVO(equipVO);
				var tipVO=ObjectPool.borrow(EquipTipVO);
				tipVO.equipVO=this.setGemEquipGMTipVO(copyExpandEquipVO);
				EquipTip.setGuXunTip(copyExpandEquipVO,this.dataEffect);
				if(this.equipBagList[equipVO.realID]==null){
					this.equipBagList[equipVO.realID]=copyExpandEquipVO;
					this.equipBagArray.push(copyExpandEquipVO);
				}
			}
			if(this.equipBagArray.length==msg.total){
				this.sendNotification(/*global.NotificationType.BAO_SHI_RECEIVE_EQUPT_LIST_INFO*/"BAO_SHI_RECEIVE_EQUPT_LIST_INFO",this.equipBagArray);
			}
		}

