		__proto.doubleClickGemHandler=function(e){
			var send=e.target;
			this.isSjBtnClick=send;
			var proxy=this.getProxy(BaoShiProxy);
			if (send==null || (send !=null && !send.hasValue)){
				return;
			};
			var s_Index=send.gemVO.gemId;
			var type=send.gemVO.gemType;
			var level=send.gemVO.gemLevel;
			if (proxy.checkGemIsMaxLv(type,level)){
				var ptVO=new PromptTextVO();
				ptVO.text=LanguageRunner.getLanguageText("GEM_IS_GET_MAX_LEVEL");
				ptVO.color=/*utils.ColorUtil.RGB_RED*/0xff0000;
				this.sendNotification(/*global.NotificationType.PUSH_PROMPT_TEXT_IN_NO_DELAY*/"pushPromptTextInNoDelay",ptVO);
				return;
			}
			this.clearContainerCombineGem();
			if (send.parent==this.panel.levelUpGemContainer){
				this.showDragGem(send);
			}
			else if (send.parent==this.panel.heChengContainer){
				this.clearContainerCombineGem();
			}
		}

		__proto.combineGemDropedHandler=function(e){
			var send=e.sender;
			this.isSjBtnClick=send;
			var target=e.data;
			if ((target !=null)&& (send.parent==target.parent)){
				return;
			};
			var s_Index=send.gemVO.gemId;
			var type=send.gemVO.gemType;
			var level=send.gemVO.gemLevel;
			if (this.proxy.checkGemIsMaxLv(type,level)){
				var ptVO=new PromptTextVO();
				ptVO.text=LanguageRunner.getLanguageText("GEM_IS_GET_MAX_LEVEL");
				ptVO.color=/*utils.ColorUtil.RGB_RED*/0xff0000;
				this.sendNotification(/*global.NotificationType.PUSH_PROMPT_TEXT_IN_NO_DELAY*/"pushPromptTextInNoDelay",ptVO);
				return;
			}
			this.clearContainerCombineGem();
			if ((send.parent==this.panel.levelUpGemContainer)&& (target !=null)&&
				(target.parent==this.panel.heChengContainer)){
				this.showDragGem(send);
			}
			else if ((send.parent==this.panel.heChengContainer)&& ((target instanceof functions.baoShi.view.BaoShiDraggableGem ))&&
			((target).parent==this.panel.levelUpGemContainer)){
				this.clearContainerCombineGem();
			}
		}

