				this.levelUpAnimate.visible=false;
				this.levelUpAnimate.removeEventListener(/*core.display.AnimateBitmap.ANIMATE_COMPLETE*/"animateComplete",__bind(this,this.onAnimatePlayComplete));
				this.levelUpAnimate.reset();
