			if(this.currentEquipVO==null){
				this.setDragEnabled(false);
				return;
			}
			else{
				this.setDragEnabled(true);
			};
			var proxy=this.getProxy(BaoShiProxy);
			this.panel.lingliText.text=this.currentEquipVO.equipLingqi.toString();
			var htmlName=ColorUtil.getFontColorHtmlString(this.currentEquipVO.itemInfoVO.name,EquipUtil.getEquipQualityHTMLColorByID(this.currentEquipVO.equipInfoVO.quality));
			this.panel.equiptName1.htmlText=htmlName;
			this.panel.equiptLevel1.text=this.currentEquipVO.level.toString()+LanguageRunner.getLanguageText("LEVEL");
			this.fadeAllLightBall();
			var gmEquipGMVO=proxy.getGemEquipGMVO(this.currentEquipVO.equipGongmingId);
			var tipVO=ObjectPool.borrow(BaoShiEquipGMTipVO);
			if(gmEquipGMVO==null){
				var oneLevelEquipGMVO=proxy.getOneLevelEquipGMVO(this.currentEquipVO.location);
				if(oneLevelEquipGMVO !=null){
					tipVO.baoShiEquipGMVO=oneLevelEquipGMVO;
					tipVO.currentEquipGMLingQi=this.currentEquipVO.equipLingqi;
					this.panel.detailImg.toolTip=tipVO;
				}
				else{
					this.panel.detailImg.toolTip=null;
				}
				this.showSomeLightBall(0);
			}
			else{
				gmEquipGMVO=proxy.getGmEquipNextGMVO(gmEquipGMVO);
				tipVO.baoShiEquipGMVO=gmEquipGMVO;
				tipVO.currentEquipGMLingQi=this.currentEquipVO.equipLingqi;
				this.panel.detailImg.toolTip=tipVO;
				this.showSomeLightBall(gmEquipGMVO.gmEquipLevel);
			};
