			if(gemTypeArr.length > 0){
				this.panel.imgBX1.image=ConfigConnect.LangType+"/baoShi/"+gemTypeArr[0]+".png";
				this.panel.imgBX1.name=gemTypeArr[0];
				this.panel.imgBX2.image=ConfigConnect.LangType+"/baoShi/"+gemTypeArr[1]+".png";
				this.panel.imgBX2.name=gemTypeArr[1];
			}
			DisplayUtil.removeAllChildrenToPool(this.panel.HasBS);
			this.selectGemArr=[];
			if(gemTypeArr.length > 0){
				for(var i=0;i < this.gemList.length;i++){
					var gem=this.gemList[i];
					if(gemTypeArr[0]==gem.gemType ||gemTypeArr[1]==gem.gemType){
						var newGem=gem.copyData();
						this.selectGemArr.push(newGem);
					}
				}
			}
