			BattleTimeConfig.targetsSkillEffectTimeDelay=Number(timeXML[0].targetsSkillEffectTimeDelay.getAttribute('value'));
			BattleTimeConfig.buffSkillEffectTimeDelay=Number(timeXML[0].buffSkillEffectTimeDelay.getAttribute('value'));
