	var ClearUpBattleReportOrder=(function(_super){
		function ClearUpBattleReportOrder(){
			ClearUpBattleReportOrder.__super.call(this);
		}

		__class(ClearUpBattleReportOrder,'functions.battle.controller.ClearUpBattleReportOrder',false,_super);
		var __proto=ClearUpBattleReportOrder.prototype;
		__proto.execute=function(note){
			_super.prototype.execute.call(this,note);
			var reportVOArray=[];
			var report=note.body;
			var reportArray=report.split("$");
			var battleDropOutVO13=new BattleDropOutVO13();
			for (var i=0;i < reportArray.length;i++){
				var b=ConvertBattleReportItemVOUtil.convert(reportArray[i]);
				if (b !=null){
					if (b.index==13){
						var doVO=b;
						switch (int(doVO.type)){
							case 0:
								battleDropOutVO13.items.push(doVO);
								battleDropOutVO13.hasItem=true;
								break ;
							case 1:
								battleDropOutVO13.militaryExploiVO=doVO;
								battleDropOutVO13.hasMilitaryExploit=true;
								break ;
							case 2:
								battleDropOutVO13.prestigeVO=doVO;
								battleDropOutVO13.hasPrestige=true;
								break ;
							}
						}else {
						reportVOArray.push(b);
					}
				}
			}
			reportVOArray.push(battleDropOutVO13);
			var bp=this.getProxy(BattleProxy);
			bp.battleReport=report;
			bp.battleReportCollection=reportVOArray;
			this.sendNotification(/*global.NotificationType.FIND_BATTLE_LOAD_FILE*/"findBattleLoadFile",reportVOArray);
		}

		return ClearUpBattleReportOrder;
	})(SimpleOrder)


