		__proto.bowlderMosaicResponse=function(note){
			var msg=note.body;
			if(this.bingfuId==msg.bingFuId){
				if(msg.operation==0){
					var bowlderVO;
					/*for each*/for(var $each_bowlderVO in this.bowlders){
						bowlderVO=this.bowlders[$each_bowlderVO];
						if(bowlderVO.bowlderId==msg.jadeId){
							if(this.equipBowlders[bowlderVO.location-1]!=null){
								if((this.equipBowlders [bowlderVO.location-1]).location==bowlderVO.location){
									this.bowlders.push(this.equipBowlders[bowlderVO.location-1]);
									this.equipBowlders[bowlderVO.location-1]=bowlderVO;
									this.bowlders.splice(this.bowlders.indexOf(bowlderVO),1);
									this.updateEquipView();
									this.bowlders=this.bowlders.sort(__bind(this,this.sortOn));
									this.bowlders.reverse();
									this.onSwitchEquipmentPage(this.bowlderPanel.bowlderPage.currentPage);
									this.playEquipEffect(this.equipBowlderBags[bowlderVO.location-1]);
									return;
								}
							}
							this.bowlders.splice(this.bowlders.indexOf(bowlderVO),1);
							this.equipBowlders[bowlderVO.location-1]=bowlderVO;
							this.updateEquipView();
							this.bowlders=this.bowlders.sort(__bind(this,this.sortOn));
							this.bowlders.reverse();
							this.onSwitchEquipmentPage(this.bowlderPanel.bowlderPage.currentPage);
							this.playEquipEffect(this.equipBowlderBags[bowlderVO.location-1]);
							break ;
						}
					}
					}else {
					var equipBowlderVO;
					/*for each*/for(var $each_equipBowlderVO in this.equipBowlders){
						equipBowlderVO=this.equipBowlders[$each_equipBowlderVO];
						if(equipBowlderVO!=null && equipBowlderVO.bowlderId==msg.jadeId){
							this.bowlders.push(equipBowlderVO);
							this.equipBowlders[this.equipBowlders.indexOf(equipBowlderVO)]=null;
							this.updateEquipView();
							this.bowlders=this.bowlders.sort(__bind(this,this.sortOn));
							this.bowlders.reverse();
							this.onSwitchEquipmentPage(this.bowlderPanel.bowlderPage.currentPage);
							break ;
						}
					}
				}
			}
			this.bowlderPanel.bagLa.text=this.bowlders.length.toString()+"/"+this.spaceNum.toString();
		}

