		__proto.attributeCheck=function(newAttributeList){
			var _$this=this;
			if(this.isFirstOpen){
				this.isFirstOpen=false;
				this.isChecking=false;
				return;
			}
			var jadeAttri;
			/*for each*/for(var $each_jadeAttri in newAttributeList){
				jadeAttri=newAttributeList[$each_jadeAttri];
				if(this.checkQuality(jadeAttri.jadeLevel)&& this.checkProps(jadeAttri.effectId)&& (this.hasQuality || this.hasProps)){
					this.isChecking=true;
					PromptBoxRunner.getInstance().openAlert(LanguageRunner.getLanguageText("BOWLDER_CHECKATTRI_TIP"),"",function(){_$this.isChecking=false;});
					return;
				}
			}
			this.isChecking=false;
		}

		__proto.checkQuality=function(value){
			this.hasQuality=false;
			var ck;
			/*for each*/for(var $each_ck in this.bowlderAmountPanel.bowlderAttriPrompt.propsCk1){
				ck=this.bowlderAmountPanel.bowlderAttriPrompt.propsCk1[$each_ck];
				this.hasQuality=this.hasQuality || ck.selected;
				if(ck.selected){
					if(BowlderUtil.QUALITYTYPE[value]["attribute_quality"]>=ck.data){
						return true;
					}
				}
			}
			if(this.bowlderAmountPanel.bowlderAttriPrompt.propsCk1[0].selected){
				this.hasQuality=false;
			}
			return !this.hasQuality;
		}

		__proto.checkProps=function(value){
			this.hasProps=false;
			var ck;
			/*for each*/for(var $each_ck in this.bowlderAmountPanel.bowlderAttriPrompt.propsCk2){
				ck=this.bowlderAmountPanel.bowlderAttriPrompt.propsCk2[$each_ck];
				this.hasProps=this.hasProps || ck.selected;
				if(ck.selected && ck.data==value){
					return true;
				}
			}
			return !this.hasProps;
		}

