		__proto.onShowBingfuTip=function(event){
			if(this.bingfuItemId=="0")return;
			DisplayUtil.removeAllChildren(this.bingfuInfoTip.sp);
			var attriDict=new Dictionary();
			var arr=[];
			for(var i=0;i<this.equipBowlders.length;i++){
				var bowlderVO=this.equipBowlders [i];
				if(bowlderVO!=null){
					if(attriDict[bowlderVO.attriId1]==null){
						if(bowlderVO.attriId1!=""){
							var obj1=new Object();
							obj1["value"]=bowlderVO.attriValue1;
							attriDict[bowlderVO.attriId1]=obj1;
						}
						}else {
						attriDict[bowlderVO.attriId1]["value"]=this.getFixedNum(Number(attriDict[bowlderVO.attriId1]["value"]),Number(bowlderVO.attriValue1));
					}
					if(attriDict[bowlderVO.attriId2]==null){
						if(bowlderVO.attriId2!=""){
							var obj2=new Object();
							obj2["value"]=bowlderVO.attriValue2;
							attriDict[bowlderVO.attriId2]=obj2;
						}
						}else {
						attriDict[bowlderVO.attriId2]["value"]=this.getFixedNum(Number(attriDict[bowlderVO.attriId2]["value"]),Number(bowlderVO.attriValue2));
					}
					if(attriDict[bowlderVO.attriId3]==null){
						if(bowlderVO.attriId3!=""){
							var obj3=new Object();
							obj3["value"]=bowlderVO.attriValue3;
							attriDict[bowlderVO.attriId3]=obj3;
						}
						}else {
						attriDict[bowlderVO.attriId3]["value"]=this.getFixedNum(Number(attriDict[bowlderVO.attriId3]["value"]),Number(bowlderVO.attriValue3));
					}
					if(attriDict[bowlderVO.attriId4]==null){
						if(bowlderVO.attriId4!=""){
							var obj4=new Object();
							obj4["value"]=bowlderVO.attriValue4;
							attriDict[bowlderVO.attriId4]=obj4;
						}
						}else {
						attriDict[bowlderVO.attriId4]["value"]=this.getFixedNum(Number(attriDict[bowlderVO.attriId4]["value"]),Number(bowlderVO.attriValue4));
					}
				}
			};
			var bowlderProxy=this.getProxy(BowlderProxy);
			for(var key in attriDict){
				var la=ObjectPool.borrow(Label);
				la.htmlText=bowlderProxy.getShortAttrDes(key,("<font color='#C6B26F'>"+attriDict[key]["value"]+"</font>"));
				this.bingfuInfoTip.sp.addChild(la);
				arr.push(la);
			}
			LayoutUtil.layout(new ListIterator(arr),new RectangleLayoutBehavior(1,30,25),3,3);
			var itemProxy=this.getProxy(ItemProxy);
			var itemVO=itemProxy.getInfoVOByID(Laya.__parseInt(this.bingfuItemId));
			this.bingfuInfoTip.nameLa.htmlText=ColorUtil.getFontColorHtmlString(itemVO.name,EquipUtil.getEquipQualityHTMLColorByID(itemVO.quality))+"("+LanguageRunner.getLanguageText("DANGQIANZHUANGBEI")+")";
			this.bingfuInfoTip.imgBG.height=this.bingfuInfoTip.sp.y+this.bingfuInfoTip.sp.height+10;
			this.bingfuInfoTip.visible=true;
		}

