		__proto.bowlderAttriChangeHandler=function(event){
			var _$this=this;
			if(this.isChecking)return;
			this.feeType=(this.freeTimes>0)?0:((this.bowlderAmountPanel.chargeChangeCk.selected)?2:1);
			var lockedAttributes="";
			if(this.curBowlderVO.isAttriLock1){
				lockedAttributes=this.curBowlderVO.attriId1;
			}
			if(this.curBowlderVO.isAttriLock2){
				lockedAttributes+=":"+this.curBowlderVO.attriId2;
			}
			if(this.curBowlderVO.isAttriLock3){
				lockedAttributes+=":"+this.curBowlderVO.attriId3;
			}
			if(this.curBowlderVO.isAttriLock4){
				lockedAttributes+=":"+this.curBowlderVO.attriId4;
			}
			if(lockedAttributes.charAt(0)==":"){
				lockedAttributes=lockedAttributes.substr(1);
			};
			var bowlderProxy=this.getProxy(BowlderProxy);
			if(bowlderProxy.delayMsg){
				var msg=ObjectPool.borrow(ChangeJadeAttributeReqMessage);
				msg.jadeId=this.curBowlderVO.bowlderId;
				msg.feeType=this.feeType;
				msg.lockedAttributes=lockedAttributes;
				if(this.feeType==0){
					this.isChecking=true;
					this.isFirstOpen=false;
					Server.send(msg);
					bowlderProxy.delayMsg=false;
					return;
				};
				var roleVO=(this.getProxy(RoleProxy)).roleVO;
				var xilianExchange=this.getXilianExchange(1);
				var ptVO=ObjectPool.borrow(PromptTextVO);
				ptVO.id=1;
				ptVO.color=/*utils.ColorUtil.RGB_RED*/0xff0000;
				if(this.feeType==1){
					if(this.yubiNum<this.needyubi){
						ptVO.text=CommonMessageRunner.getCommonMessageText(100422);
						this.sendNotification(/*global.NotificationType.PUSH_PROMPT_TEXT_IN_NO_DELAY*/"pushPromptTextInNoDelay",ptVO);
						return;
						}else if(Laya.__parseInt(roleVO.silver)<this.needsilver){
						ptVO.text=CommonMessageRunner.getCommonMessageText(100011);
						this.sendNotification(/*global.NotificationType.PUSH_PROMPT_TEXT_IN_NO_DELAY*/"pushPromptTextInNoDelay",ptVO);
						return;
					}
					}else if(this.feeType==2){
					if(Laya.__parseInt(roleVO.gold)<this.needgold){
						ptVO.text=CommonMessageRunner.getCommonMessageText(100412);
						this.sendNotification(/*global.NotificationType.PUSH_PROMPT_TEXT_IN_NO_DELAY*/"pushPromptTextInNoDelay",ptVO);
						return;
						}else if(Laya.__parseInt(roleVO.silver)<this.needsilver){
						ptVO.text=CommonMessageRunner.getCommonMessageText(100011);
						this.sendNotification(/*global.NotificationType.PUSH_PROMPT_TEXT_IN_NO_DELAY*/"pushPromptTextInNoDelay",ptVO);
						return;
					}
				}
				PromptBoxRunner.getInstance().opConfirmForOnce((xilianExchange[1]==0)?StringUtil1.format(LanguageRunner.getLanguageText("BOWLDER_AMOUNT_CHANGE_TIP"),xilianExchange[0],"",1):StringUtil1.format(LanguageRunner.getLanguageText("BOWLDER_AMOUNT_CHANGE_TIP"),xilianExchange[0],StringUtil1.format(LanguageRunner.getLanguageText("ATTRI_LOCK_COST"),xilianExchange[1],xilianExchange[2]),1),
				null,/*utils.SharedObjectData.BOWLDERATTRICHANGE*/"bowlderattrichange",function(){
					Server.send(msg);
					_$this.sendNotification(/*global.NotificationType.SENIOR_PASSWORD_NEED_CONFIRM_PWD_MSG*/"SENIOR_PASSWORD_NEED_CONFIRM_PWD_MSG",msg);
					_$this.sendNotification(/*global.NotificationType.SENIOR_PASSWORD_CONFIRM_PWD_AFTER_MSG*/"SENIOR_PASSWORD_CONFIRM_PWD_AFTER_MSG",null,[ /*global.NotificationType.SENIOR_NOT_FREE_XILIAN_AFTER*/"SENIOR_NOT_FREE_XILIAN_AFTER"]);
				});
			}
		}

