		__proto.assII2Difficulty=function(str_ascII){
			var difficulty=[];
			var ascII_array=str_ascII.split("");
			for (var i=0;i <ascII_array.length;i++){
				var iclosure_temp=Laya.__parseInt(ascII_array[i]);
				var num=iclosure_temp <0 ? 0:(iclosure_temp > 1?1:iclosure_temp);
				difficulty.push(num);
			}
			return difficulty;
		}

		__proto.ascII2Mode=function(str_ascII){
			var mode=[];
			var ascII_array=str_ascII.split("");
			for (var i=0;i <ascII_array.length;i+=5){
				var addNum=0;
				for(var j=0;j < 5;j++){
					var jclosure_temp=Laya.__parseInt(ascII_array[i+j]);
					var num=jclosure_temp <0 ? 0:(jclosure_temp > 1?1:jclosure_temp);
					addNum+=num<<(5-1-j);
				}
				mode.push(addNum);
			}
			return mode;
		}

