			Server.subscribe(/*net.message.MessageType.GC_QUEUE_BUILD*/10905,__bind(this,this.onBuildQueueResponse));
			Server.subscribe(/*net.message.MessageType.GC_QUEUE_TECH*/10906,__bind(this,this.onTechQueueResponse));
