			this.subscribeNotification(/*global.NotificationType.ROLE_INFO_UPDATED*/"roleInfoUpdated",__bind(this,this.updateRoleInfo));
			this.subscribeNotification(/*global.NotificationType.ROLE_CURRENCY_UPDATED*/"roleCurrencyUpdated",__bind(this,this.updateRoleInfo));
			this.subscribeNotification(/*global.NotificationType.CONCUBINE_RECEIVE_ONE_KEY_LOVE_NEED_GOLD_INFO*/"CONCUBINE_RECEIVE_ONE_KEY_LOVE_NEED_GOLD_INFO",__bind(this,this.oneKeyLoveNeedGold));
			this.subscribeNotification(/*global.NotificationType.CONBUBINE_QIZHEN_INFO*/"CONBUBINE_QIZHEN_INFO",__bind(this,this.receiveQiZhenInfo));
