	//file:///e:/work/sgwork/h5sg2/sg4/src/functions/country/controller/returncountryinfoorder.as
	//class functions.country.controller.ReturnCountryInfoOrder extends core.patterns.command.SimpleOrder
	var ReturnCountryInfoOrder=(function(_super){
		function ReturnCountryInfoOrder(){
			ReturnCountryInfoOrder.__super.call(this);
		}

		__class(ReturnCountryInfoOrder,'functions.country.controller.ReturnCountryInfoOrder',false,_super);
		var __proto=ReturnCountryInfoOrder.prototype;
		__proto.execute=function(note){
			_super.prototype.execute.call(this,note);
			var message=note.body;
			var cp=this.getProxy(CountryProxy);
			var countryDetlInfoVO=ObjectPool.borrow(CountryDetlInfoVO);
			countryDetlInfoVO.countryType=cp.roleProxy.roleVO.countryType;
			countryDetlInfoVO.isLeader=message.isLeader;
			countryDetlInfoVO.peopleCount=message.peopleCount;
			countryDetlInfoVO.armyCount=message.armyCount;
			countryDetlInfoVO.protect=message.protect;
			countryDetlInfoVO.occupy=message.occupy;
			countryDetlInfoVO.ally=message.ally;
			countryDetlInfoVO.cityCount=message.cityCount;
			countryDetlInfoVO.farmCount=message.farmCount;
			countryDetlInfoVO.juniorCount=message.juniorCount;
			countryDetlInfoVO.middleCount=message.middleCount;
			countryDetlInfoVO.seniorCount=message.seniorCount;
			if (message.policys !=null && message.policys.length >=3){
				var policy=message.policys.split("|");
				for (var a=0;a < policy.length;a++){
					if (a==(policy.length-1)){
						countryDetlInfoVO.policys+=cp.getCountryPolicyVO(int(policy[a])).policyName;
					}
					else{
						countryDetlInfoVO.policys+=cp.getCountryPolicyVO(int(policy[a])).policyName+"、";
					}
				}
			}
			else if (message.policys.length==1){
				countryDetlInfoVO.policys=cp.getCountryPolicyVO(int(message.policys)).policyName;
			}
			countryDetlInfoVO.addSilver=message.addSilver;
			countryDetlInfoVO.leader=message.leader;
			countryDetlInfoVO.img=message.img;
			countryDetlInfoVO.message=message.message;
			countryDetlInfoVO.qinglong=message.qinglong;
			countryDetlInfoVO.baihu=message.baihu;
			countryDetlInfoVO.zhuque=message.zhuque;
			countryDetlInfoVO.xuanwu=message.xuanwu;
			countryDetlInfoVO.isRuoGuo=message.isProtect;
			countryDetlInfoVO.tongMengJiaCheng=message.addSilverAlly;
			if (message.armyInfos !=null){
				countryDetlInfoVO.armyInfos=message.armyInfos;
				for (var i=0;i < message.armyInfos.length;i++){
					countryDetlInfoVO.armyInfos[i]=message.armyInfos[i];
				}
			}
			this.sendNotification(/*global.NotificationType.UPATA_COUNTRY_INFO*/"updataCountryInfo",countryDetlInfoVO);
		}

		return ReturnCountryInfoOrder;
	})(SimpleOrder)


