		__proto.onCountryInfoRespone=function(note){
			this.countrySelect.CountryMessage.editable=false;
			this.countrySelect.ChangeMessagebtn.visible=false;
			var countryDetlInfoVO=note.body;
			if (countryDetlInfoVO==null)
				return;
			switch (countryDetlInfoVO.ally){
				case 0:
					this.countrySelect.CountryRelationImg.image=ConfigConnect.LangType+"/country/sanguo.png";
					break ;
				case 3:
					this.countrySelect.CountryRelationImg.image=ConfigConnect.LangType+"/country/weishu.png";
					break ;
				case 5:
					this.countrySelect.CountryRelationImg.image=ConfigConnect.LangType+"/country/weiwu.png";
					break ;
				case 6:
					this.countrySelect.CountryRelationImg.image=ConfigConnect.LangType+"/country/shuwu.png";
					break ;
				}
			if (countryDetlInfoVO.isLeader==1){
				this.countrySelect.CountryMessage.editable=true;
				this.countrySelect.ChangeMessagebtn.visible=true;
				this.countrySelect.ChangeMessagebtn.click=iflash.method.bind(this,this.onChangeCountryMessage);
			}
			this.countrySelect.CountryMessage.text=countryDetlInfoVO.message;
			this.countrySelect.PeopleCount.text=countryDetlInfoVO.peopleCount.toString();
			this.countrySelect.UnionCount.text=countryDetlInfoVO.armyCount.toString();
			this.countrySelect.CityCount.text=countryDetlInfoVO.cityCount.toString();
			if (countryDetlInfoVO.protect !=null){
				this.countrySelect.CountrySafe.text=countryDetlInfoVO.protect;
			}
			else{
				this.countrySelect.CountrySafe.text=LanguageRunner.getLanguageText("NULL");
			}
			if (countryDetlInfoVO.countryType==1){
				this.countrySelect.CountryImg.image=ConfigConnect.LangType+"/country/wei.jpg";
			}
			else if (countryDetlInfoVO.countryType==2){
				this.countrySelect.CountryImg.image=ConfigConnect.LangType+"/country/shu.jpg";
			}
			else if (countryDetlInfoVO.countryType==3){
				this.countrySelect.CountryImg.image=ConfigConnect.LangType+"/country/wu.jpg";
			}
			this.countrySelect.ResenceNum.text=countryDetlInfoVO.farmCount.toString();
			this.countrySelect.CountryMessage.text=countryDetlInfoVO.message;
			if (countryDetlInfoVO.policys !=null){
				this.countrySelect.CityMessage.text=countryDetlInfoVO.policys;
			}
			else{
				this.countrySelect.CityMessage.text=LanguageRunner.getLanguageText("NULL");
			}
			this.countrySelect.SeliveNum.text="+"+(Number((Number(countryDetlInfoVO.addSilver)/ (100000 / 100)).toFixed(0))).toString()+"%";
			if(countryDetlInfoVO.isRuoGuo){
				this.countrySelect.SeliveNum_other.text="+"+(Number((Number(countryDetlInfoVO.tongMengJiaCheng)/ (100000 / 100)).toFixed(0))).toString()+"%";
				this.countrySelect.SeliveNum_other.visible=true;
				this.countrySelect.serilAdd_other.visible=true;
			}
			else{
				this.countrySelect.SeliveNum_other.visible=false;
				this.countrySelect.serilAdd_other.visible=false;
			}
			if(countryDetlInfoVO.isRuoGuo){
				this.countrySelect.ruoguobaohu.text=LanguageRunner.getLanguageText("RUO_GUO_BAO_HU");
			}
			else{
				this.countrySelect.ruoguobaohu.text="";
			}
			if (countryDetlInfoVO.leader !=null){
				this.countrySelect.KingName.text=countryDetlInfoVO.leader;
				this.countrySelect.KingName.x=this.countrySelect.KingImg.x+(this.countrySelect.KingImg.width-this.countrySelect.KingName.width)/ 2-2;
			}
			if (countryDetlInfoVO.img !=null){
				if (countryDetlInfoVO.img !=""){
					this.countrySelect.KingImg.image="general/"+countryDetlInfoVO.img;
				}
			}
		}

