		__proto.dropedHandler=function(e){
			var sender=e.sender;
			var target=e.data;
			if ((sender instanceof functions.country.view.DraggableUnionGrid )){
				if ((target instanceof functions.country.view.DraggableEssenceUnion )){
					var deu;
					/*for each*/for(var $each_deu in this.eliteUnionList){
						deu=this.eliteUnionList[$each_deu];
						if (deu.armyID !="0" && deu.armyID==(sender).armyID){
							deu.update(null);
						}
					}
					(target).update((sender).value);
				}
			}
			if ((sender instanceof functions.country.view.DraggableEssenceUnion )){
				if ((target instanceof functions.country.view.DraggableEssenceUnion )){
					var tempU=(target).value;
					(target).update((sender).value);
					(sender).update(tempU);
					}else {
					(sender).update(null);
				}
			}
		}

