	var CHWClearUpBattleReportOrder=(function(_super){
		function CHWClearUpBattleReportOrder(){
			CHWClearUpBattleReportOrder.__super.call(this);
		}

		__class(CHWClearUpBattleReportOrder,'functions.countryHarassWar.controller.CHWClearUpBattleReportOrder',false,_super);
		var __proto=CHWClearUpBattleReportOrder.prototype;
		__proto.execute=function(note){
			_super.prototype.execute.call(this,note);
			var reportVOArray=[];
			var report=note.body;
			var reportArray=report.split("$");
			var battleDropOutVO13=new BattleDropOutVO13();
			var generalProxy=this.getProxy(GeneralProxy);
			var soldiersProxy=this.getProxy(SoldiersProxy);
			var chwProxy=this.getProxy(CountryHarassWarProxy);
			for (var i=0;i < reportArray.length;i++){
				var b=CHWConvertBattleReportItemVOUtil.convert(reportArray[i],soldiersProxy,generalProxy,chwProxy);
				if (b !=null){
					if (b.index==13){
						var doVO=b;
						switch (doVO.type){
							case 0:
								battleDropOutVO13.items.push(doVO);
								battleDropOutVO13.hasItem=true;
								break ;
							case 1:
								battleDropOutVO13.militaryExploiVO=doVO;
								battleDropOutVO13.hasMilitaryExploit=true;
								break ;
							case 2:
								battleDropOutVO13.prestigeVO=doVO;
								battleDropOutVO13.hasPrestige=true;
								break ;
							}
						}else {
						reportVOArray.push(b);
					}
				}
			}
			reportVOArray.push(battleDropOutVO13);
			var battleProxy=this.getProxy(CountryHarassWarProxy);
			console.log("fight city id==="+note.type);
			var fightType=note.args[0];
			var battleData;
			if(fightType==/*functions.countryHarassWar.model.CountryHarassWarProxy.LOOK_FIGHT*/2){
				battleData=battleProxy.getLookFightBattleData();
			}
			else if(fightType==/*functions.countryHarassWar.model.CountryHarassWarProxy.JOIN_FIGHT*/0){
				battleData=battleProxy.getJoinFightBattleData();
			}
			else if(fightType==/*functions.countryHarassWar.model.CountryHarassWarProxy.CHALLENGE_FIGHT*/1){
				battleData=battleProxy.getChallengeBattleData();
			}
			console.log("battleData==="+battleData);
			battleData.battleReport=report;
			battleData.battleReportCollection=reportVOArray;
			battleProxy.setBattleData(fightType,battleData);
			this.sendNotification(/*global.NotificationType.CHW_FIND_BATTLE_LOAD_FILE*/"CHW_FIND_BATTLE_LOAD_FILE",reportVOArray,note.type,battleData);
		}

		return CHWClearUpBattleReportOrder;
	})(SimpleOrder)


	//file:///e:/work/sgwork/h5sg2/sg4/src/functions/countryharasswar/controller/chwfindbattleloadfileorder.as
	//class functions.countryHarassWar.controller.CHWFindBattleLoadFileOrder extends core.patterns.command.SimpleOrder
	var CHWFindBattleLoadFileOrder=(function(_super){
		function CHWFindBattleLoadFileOrder(){
			CHWFindBattleLoadFileOrder.__super.call(this);
		}

		__class(CHWFindBattleLoadFileOrder,'functions.countryHarassWar.controller.CHWFindBattleLoadFileOrder',false,_super);
		var __proto=CHWFindBattleLoadFileOrder.prototype;
		__proto.execute=function(note){
			_super.prototype.execute.call(this,note);
			var reportVOArray=note.body;
			var generalImageArray=[];
			var imageArray=[];
			var loadingRootPath=ConfigConnect.loadRootPath+"/";
			var assetsURL;
			var bbriVO;
			/*for each*/for(var $each_bbriVO in reportVOArray){
				bbriVO=reportVOArray[$each_bbriVO];
				switch (bbriVO.index){
					case 2:
						this.pushResourceArray(imageArray,"general/"+(bbriVO).image);
						break ;
					case 3:
						imageArray.push((bbriVO).image);
						break ;
					case 4:
						this.pushResourceArray(imageArray,(bbriVO).image);
						var troopID=(bbriVO).troopsType;
						if (BattleLoactionUtil.isAttacker((bbriVO).location)){
							var troopImg=(bbriVO).troopsImg;
							assetsURL=loadingRootPath+"assets/instant/gvgBattle/troops/"+troopImg+"L/"+troopImg+"L.png";
							if(!CHWBattleResourceCache.hasCache(assetsURL,"stand")){
								this.pushResourceArray(imageArray,assetsURL);
							}
							}else {
							assetsURL=loadingRootPath+"assets/instant/gvgBattle/troops/"+troopImg+"R/"+troopImg+"R.png";
							if(!CHWBattleResourceCache.hasCache(assetsURL,"stand")){
								this.pushResourceArray(imageArray,assetsURL);
							}
						}
						break ;
					case 7:
						if (String((bbriVO).actionSkillID)=="0"){
							continue ;
						}
						if (BattleLoactionUtil.isAttacker((bbriVO).actionStart)){
							assetsURL=loadingRootPath+"assets/instant/gvgBattle/effect/"+String((bbriVO).actionSkillID)+"L/"+String((bbriVO).actionSkillID)+"L.png";
							if(!CHWBattleResourceCache.hasCache(assetsURL)){
								this.pushResourceArray(imageArray,assetsURL);
							}
							this.pushResourceArray(imageArray,loadingRootPath+"instant/gvgBattle/effect/effect"+String((bbriVO).actionSkillID)+"L"+".swf");
							}else {
							assetsURL=loadingRootPath+"assets/instant/gvgBattle/effect/"+String((bbriVO).actionSkillID)+"R/"+String((bbriVO).actionSkillID)+"R.png";
							if(!CHWBattleResourceCache.hasCache(assetsURL)){
								this.pushResourceArray(imageArray,assetsURL);
							}
							this.pushResourceArray(imageArray,loadingRootPath+"instant/gvgBattle/effect/effect"+String((bbriVO).actionSkillID)+"R"+".swf");
						}
						break ;
					case 8:;
						var b8=bbriVO;
						if (b8.changeValue > 0){
							this.pushResourceArray(imageArray,loadingRootPath+"instant/gvgBattle/numberGreen.swf");
						}
						break ;
					case 9:
						if (!BattleUtil.checkBuffIDIsInFilterList((bbriVO).bufferID)){
							this.pushResourceArray(imageArray,loadingRootPath+"instant/gvgBattle/buff/buff"+String((bbriVO).bufferID)+".swf");
							if(!CHWBattleResourceCache.hasCache(loadingRootPath+"assets/instant/gvgBattle/buff/"+String((bbriVO).bufferID)+"/"+String((bbriVO).bufferID)+".png")){
								this.pushResourceArray(imageArray,loadingRootPath+"assets/instant/gvgBattle/buff/"+String((bbriVO).bufferID)+"/"+String((bbriVO).bufferID)+".png");
							}
						}
						break ;
					case 12:;
						var b12=(bbriVO);
						break ;
					}
			}
			this.sendNotification(/*global.NotificationType.CHW_START_UP_BATTLE_LOADING*/"CHW_START_UP_BATTLE_LOADING",imageArray,note.type,note.args[0]);
		}

		__proto.pushResourceArray=function(arr,url){
			if (arr.indexOf(url)< 0){
				arr.push(url);
			}
		}

		return CHWFindBattleLoadFileOrder;
	})(SimpleOrder)


