	//file:///e:/work/sgwork/h5sg2/sg4/src/functions/countryharasswar/view/countryharasswarmediator.as
	//class functions.countryHarassWar.view.CountryHarassWarMediator extends core.patterns.mediator.Mediator
	var CountryHarassWarMediator=(function(_super){
		function CountryHarassWarMediator(viewComponent){
			this.requestLoadFightArr=null;
			this.panel=null;
			this.attackerMemberArr=null;
			this.defenderMemberArr=null;
			this.fightTeamMsg=null;
			this.lookFightTeamMsg=null;
			this.challengeFightArr=null;
			CountryHarassWarMediator.__super.call(this,viewComponent);
			this.panel=viewComponent;
			this.attackerMemberArr=[];
			this.defenderMemberArr=[];
			this.fightTeamMsg=new CHWfightTeamMsg();
			this.lookFightTeamMsg=new CHWfightTeamMsg();
			this.challengeFightArr=[];
			this.requestLoadFightArr=[];
		}

		__class(CountryHarassWarMediator,'functions.countryHarassWar.view.CountryHarassWarMediator',false,_super);
		var __proto=CountryHarassWarMediator.prototype;
		__proto.configNotifications=function(){
			_super.prototype.configNotifications.call(this);
			this.subscribeNotification(/*global.NotificationType.CHW_RECEIVE_CHALLENGE_INFO*/"CHW_RECEIVE_CHALLENGE_INFO",__bind(this,this.receiveChallengeInfo));
			this.subscribeNotification(/*global.NotificationType.CHW_GVG_FIGHT_MESSAGE*/"CHW_GVG_FIGHT_MESSAGE",__bind(this,this.fightMessage));
			this.subscribeNotification(/*global.NotificationType.CHW_ENTER_FIGHT_SCENE*/"CHW_ENTER_FIGHT_SCENE",__bind(this,this.requestEnterFightScene));
			this.subscribeNotification(/*global.NotificationType.CHW_SHOW_CHALLGENGE_FIGHT*/"CHW_SHOW_CHALLGENGE_FIGHT",__bind(this,this.showChallengeFight));
		}

		__proto.clearLastFightData=function(note){
			return;
		}

		__proto.fightMessage=function(note){
			var proxy=this.getProxy(CountryHarassWarProxy);
			var msg=note.body;
			Server.sendLocalConnection("proxy.gvgLookFightCityId==="+proxy.gvgLookFightCityId+"proxy.lookFightId="+proxy.lookFightId+"lookIndex="+proxy.lookFightIndex);
			Server.sendLocalConnection("proxy.curShowFightCityId==="+proxy.joinFightId+"proxy.joinFightId="+proxy.joinFightId+"joinFightIndex="+proxy.joinFightIndex);
			var isPlayEnd=false;
			var fightPlayerType=0;
			var s=ServerTimeUitl.getInstance().getServerTimestamp();
			var timeString=StringUtil1.formatTime2(s,"YY-MM-dd hh:mm:ss:lll");
			if(proxy.gvgLookFightCityId==proxy.joinFightCityId && proxy.lookFightId==proxy.joinFightId){
				var chwBattleContainerMediator=this.context.view.getMediator(CHWBattleContainerMediator);
				var lookBattleMediator=this.context.view.getMediator(CHWLookFightMediator);
				var challengeBattleMediator=this.context.view.getMediator(CHWChallengeMediator);
				lookBattleMediator.panel.visible=false;
				chwBattleContainerMediator.panel.visible=true;
				challengeBattleMediator.panel.visible=false;
				this.sendNotification(/*global.NotificationType.CHW_JOIN_LOOK_FIGHT_CITY_FIGHT_CLEAR_LOOK_FIGHT*/"CHW_JOIN_LOOK_FIGHT_CITY_FIGHT_CLEAR_LOOK_FIGHT");
				Server.sendLocalConnection("观战的过程中，玩家已经加入到观战城市的战斗中,清空观战数据，切入参战场景");
				proxy.joinFightIsPlay=true;
				proxy.joinFightTotalIndex=msg.totalIndex;
				proxy.joinFightId=msg.fightId;
				proxy.joinFightIndex=msg.index;
				fightPlayerType=/*functions.countryHarassWar.model.CountryHarassWarProxy.JOIN_FIGHT*/0;
				this.sendNotification(/*global.NotificationType.CLOSE_PANEL*/"closePanel",/*functions.panel.model.PanelType.GVG_RESULT_PANEL*/171);
				proxy.getCurPostionInTeam();
			}
			else{
				if(msg.cityId==proxy.gvgLookFightCityId){
					Server.sendLocalConnection("get lookFightCity fight url  time==="+timeString);
					if(proxy.gvgIsLookFight){
						this.sendNotification(/*global.NotificationType.CHW_ENTER_FIGHT_SCENE*/"CHW_ENTER_FIGHT_SCENE",true,/*functions.countryHarassWar.model.CountryHarassWarProxy.LOOK_FIGHT*/2);
					}
					proxy.lookFightIsPlay=true;
					proxy.lookFightTotalIndex=msg.totalIndex;
					proxy.lookFightId=msg.fightId;
					if(proxy.lookFightIndex !=msg.index){
						proxy.lookFightIndex=msg.index;
						fightPlayerType=/*functions.countryHarassWar.model.CountryHarassWarProxy.LOOK_FIGHT*/2;
					}
				}
				else if(msg.cityId==proxy.joinFightCityId){
					if(msg.fightId==proxy.joinFightId){
						proxy.getCurPostionInTeam();
						Server.sendLocalConnection("get joinFightCity fight url  time==="+timeString);
						proxy.joinFightIsPlay=true;
						proxy.joinFightTotalIndex=msg.totalIndex;
						proxy.joinFightId=msg.fightId;
						proxy.joinFightIndex=msg.index;
						fightPlayerType=/*functions.countryHarassWar.model.CountryHarassWarProxy.JOIN_FIGHT*/0;
						this.sendNotification(/*global.NotificationType.CLOSE_PANEL*/"closePanel",/*functions.panel.model.PanelType.GVG_RESULT_PANEL*/171);
					}
				}
			}
			Server.sendLocalConnection("fightMessage break off-------")
			this.sendNotification(/*global.NotificationType.CHW_BATTLE_BREAK_OFF*/"CHW_BATTLE_BREAK_OFF",1,isPlayEnd,fightPlayerType);
			this.requestReport(msg.fightRepUrl,msg.cityId,fightPlayerType);
		}

		__proto.showChallengeFight=function(note){
			var fightUrl=note.body;
			var msg=null;
			for(var i=0;i < this.challengeFightArr.length;i++){
				var msgInfo=this.challengeFightArr[i];
				if(msgInfo.fightRepUrl==fightUrl){
					msg=msgInfo;
					break ;
				}
			}
			if(msg==null){
				console.log("没有找到被单挑的战报");
				return;
			};
			var proxy=this.getProxy(CountryHarassWarProxy);
			var fightPlayerType=/*functions.countryHarassWar.model.CountryHarassWarProxy.CHALLENGE_FIGHT*/1;
			Server.sendLocalConnection(" showChallengeFight break off-------")
			this.sendNotification(/*global.NotificationType.CHW_BATTLE_BREAK_OFF*/"CHW_BATTLE_BREAK_OFF",1,false,fightPlayerType);
			this.requestReport(msg.fightRepUrl,msg.cityId,fightPlayerType);
			this.sendNotification(/*global.NotificationType.CHW_SHOW_DAN_TIAO_IMG*/"CHW_SHOW_DAN_TIAO_IMG",msg);
			proxy.challengeCityId=msg.cityId;
			proxy.isChallengeFight=true;
			if(Managers.sceneManager.currentScene !=Managers.sceneManager.countryHarassWarScene){
				Managers.sceneManager.switchScene(Managers.sceneManager.countryHarassWarScene);
			};
			var chwBattleContainerMediator=this.context.view.getMediator(CHWBattleContainerMediator);
			var lookBattleMediator=this.context.view.getMediator(CHWLookFightMediator);
			var challengeBattleMediator=this.context.view.getMediator(CHWChallengeMediator);
			lookBattleMediator.panel.visible=false;
			chwBattleContainerMediator.panel.visible=false;
			challengeBattleMediator.panel.visible=true;
		}

		__proto.receiveChallengeInfo=function(note){
			var proxy=this.getProxy(CountryHarassWarProxy);
			var msg=note.body;
			if(!msg.isLauncher){
				var str=StringUtil1.format(LanguageRunner.getLanguageText("GVG_LOOK_CHALLGENG_FIGHT"),msg.rewardInfo,/*functions.gvg.view.GvgNoticePanel.CHALLENGE_FIGHT*/"CHALLENGE_FIGHT",/*functions.gvg.view.GvgNoticePanel.LINK_SEPARATOR*/"|",msg.fightRepUrl);
				proxy.sendNoticeNotification(str);
				this.sendNotification(/*global.NotificationType.GVG_ADD_NEW_REPORT*/"GVG_ADD_NEW_REPORT",str);
				this.challengeFightArr.push(msg);
				if(Managers.sceneManager.currentScene==Managers.sceneManager.countryHarassWarScene){
					this.sendNotification(/*global.NotificationType.CHW_SHOW_CHALLGENG_NOTICE_PANEL*/"CHW_SHOW_CHALLGENG_NOTICE_PANEL",str);
				}
				return;
			}
			proxy.deleteMsgListByCity(proxy.joinFightCityId,false);
			proxy.clearRequestFightUrlMsg();
			proxy.fightEnd();
			proxy.joinFightCityId=0;
			proxy.joinFightId="0";
			proxy.joinFightIndex=-1;
			this.challengeFightHandler(msg);
		}

		__proto.challengeFightHandler=function(msg){
			var proxy=this.getProxy(CountryHarassWarProxy);
			Server.sendLocalConnection(" challengeFightHandler break off-------")
			var fightPlayerType=/*functions.countryHarassWar.model.CountryHarassWarProxy.CHALLENGE_FIGHT*/1;
			this.sendNotification(/*global.NotificationType.CHW_BATTLE_BREAK_OFF*/"CHW_BATTLE_BREAK_OFF",1,false,fightPlayerType);
			this.requestReport(msg.fightRepUrl,msg.cityId,fightPlayerType);
			this.sendNotification(/*global.NotificationType.CHW_SHOW_DAN_TIAO_IMG*/"CHW_SHOW_DAN_TIAO_IMG",msg);
			proxy.challengeCityId=msg.cityId;
			proxy.isChallengeFight=true;
			if(Managers.sceneManager.currentScene==Managers.sceneManager.countryHarassWarScene && proxy.isChallengeFight){
				var chwBattleContainerMediator=this.context.view.getMediator(CHWBattleContainerMediator);
				var lookBattleMediator=this.context.view.getMediator(CHWLookFightMediator);
				var challengeBattleMediator=this.context.view.getMediator(CHWChallengeMediator);
				lookBattleMediator.panel.visible=false;
				chwBattleContainerMediator.panel.visible=false;
				challengeBattleMediator.panel.visible=true;
			}
		}

		__proto.showChallengeTxt=function(str){
			var ptVO=ObjectPool.borrow(PromptTextVO);
			ptVO.id=1;
			ptVO.color=/*utils.ColorUtil.RGB_RED*/0xff0000;
			ptVO.text=str;
			this.sendNotification(/*global.NotificationType.PUSH_PROMPT_TEXT_IN_NO_DELAY*/"pushPromptTextInNoDelay",ptVO);
		}

		__proto.requestEnterFightScene=function(note){
			var proxy=this.getProxy(CountryHarassWarProxy);
			proxy.isExitFightScene=(note.body==true?false:true);
			var gvgProxy=this.getProxy(GvgProxy);
			console.log("proxy.joinFightIndex==="+proxy.joinFightIndex);
			if(note.body==true){
				if(note.type==/*functions.countryHarassWar.model.CountryHarassWarProxy.JOIN_FIGHT*/0){
					proxy.curShowFightCityId=proxy.joinFightCityId;
				}
				Managers.sceneManager.switchScene(Managers.sceneManager.countryHarassWarScene);
			};
			var chwBattleContainerMediator=this.context.view.getMediator(CHWBattleContainerMediator);
			var lookBattleMediator=this.context.view.getMediator(CHWLookFightMediator);
			var challengeBattleMediator=this.context.view.getMediator(CHWChallengeMediator);
			if(proxy.challengeFightIsPlay && note.type !=/*functions.countryHarassWar.model.CountryHarassWarProxy.LOOK_FIGHT*/2){
				lookBattleMediator.panel.visible=false;
				chwBattleContainerMediator.panel.visible=false;
				challengeBattleMediator.panel.visible=true;
				return;
			}
			if(proxy.joinFightIndex==-1){
				proxy.requestNextFight(proxy.joinFightCityId,proxy.joinFightId,proxy.joinFightIndex);
				proxy.joinFightIndex=0;
				this.sendNotification(/*global.NotificationType.CHW_SHOW_WAIT_EFFECT*/"CHW_SHOW_WAIT_EFFECT");
			}
			else if(proxy.myJoinTeamResMsg !=null){
				proxy.requestNextFight(proxy.joinFightCityId,proxy.joinFightId,proxy.joinFightIndex);
				this.sendNotification(/*global.NotificationType.CHW_SHOW_WAIT_EFFECT*/"CHW_SHOW_WAIT_EFFECT");
			}
			if(note.type==/*functions.countryHarassWar.model.CountryHarassWarProxy.JOIN_FIGHT*/0){
				lookBattleMediator.panel.visible=false;
				challengeBattleMediator.panel.visible=false;
				chwBattleContainerMediator.panel.visible=true;
			}
			else if(note.type==/*functions.countryHarassWar.model.CountryHarassWarProxy.LOOK_FIGHT*/2){
				chwBattleContainerMediator.panel.visible=false;
				challengeBattleMediator.panel.visible=false;
				lookBattleMediator.panel.visible=true;
			}
		}

		__proto.startLoadFightReport=function(reportVO){
			var _$this=this;
			var proxy=this.getProxy(CountryHarassWarProxy);
			if(reportVO.playerType==/*functions.countryHarassWar.model.CountryHarassWarProxy.JOIN_FIGHT*/0){
				this.sendNotification(/*global.NotificationType.CHW_SHOW_WAIT_EFFECT*/"CHW_SHOW_WAIT_EFFECT");
			}
			else if(reportVO.playerType==/*functions.countryHarassWar.model.CountryHarassWarProxy.LOOK_FIGHT*/2){
				this.sendNotification(/*global.NotificationType.CHW_SHOW_LOOK_WAIT_EFFECT*/"CHW_SHOW_LOOK_WAIT_EFFECT");
			}
			else if(reportVO.playerType==/*functions.countryHarassWar.model.CountryHarassWarProxy.CHALLENGE_FIGHT*/1){
				this.sendNotification(/*global.NotificationType.CHW_SHOW_CHALLENGE_WAIT_EFFECT*/"CHW_SHOW_CHALLENGE_WAIT_EFFECT");
			};
			var viewer=0;
			var eventTransferVO=new EventTransferVO(0,0,0,0,false);
			var version=this.getVersion(reportVO.fightUrl);
			if (reportVO.fightUrl.indexOf("?")> 0){
				viewer=int(String(reportVO.fightUrl.split("?")[1]).split("=")[1]);
			};
			var httpURLLoader=new HttpURLLoader();
			httpURLLoader.onError=this.onWarReportError;
			httpURLLoader.onComplete=function (e){
				var reportData=e.target.data;
				reportData.position=0;
				reportData.uncompress();
				var reportStr=reportData.toString();
				_$this.sendNotification(/*global.NotificationType.COUNTRY_HARASS_WAR_ENTER_BATTLE*/"COUNTRY_HARASS_WAR_ENTER_BATTLE",reportStr,reportVO.cityId,reportVO.playerType);
				if(_$this.requestLoadFightArr.length > 1){
					_$this.startLoadFightReport(_$this.requestLoadFightArr.shift());
				}
			};
			httpURLLoader.dataFormat=/*iflash.net.URLLoaderDataFormat.BINARY*/"binary";
			var server=ConfigConnect.crossServer;
			if(!ConfigConnect.zzsf_use_cross_on_off){
				server=ConfigConnect.localServer;
			}
			httpURLLoader.url=server+reportVO.fightUrl;
			httpURLLoader.request();
		}

		__proto.requestReport=function(reportUrl,cityId,fightType){
			var reportVO=ObjectPool.borrow(CHWRequestReportVO);
			reportVO.fightUrl=reportUrl;
			reportVO.cityId=cityId;
			reportVO.playerType=fightType;
			this.requestLoadFightArr.push(reportVO);
			if(this.requestLoadFightArr.length==1){
				this.startLoadFightReport(this.requestLoadFightArr.shift());
			}
		}

		__proto.onWarReportError=function(e){
			Server.sendLocalConnection("加载征战四方战报失败："+e.text)
			PromptBoxRunner.getInstance().openAlert(LanguageRunner.getLanguageText("REPORT_NOT_EXIST"));
		}

		__proto.getVersion=function(url){
			var temp="version";
			var version;
			if (url.indexOf(temp)>=0){
				version=url.substring(url.indexOf(temp)+temp.length+1,url.length);
			}
			if (version==null || version==""){
				version="0.0.0.1";
			}
			return version;
		}

		return CountryHarassWarMediator;
	})(Mediator)


