		__proto.initFlowerGifts=function(amount){
			this.flowerContainer=new Sprite();
			for (var i=0;i < amount;i++){
				var btnFlower=new ImageButton();
				btnFlower.setImage(/*data.Resources.FLOWER_GIFT*/"crossServerWar/common/vector_flower.png");
				btnFlower.click=this.showFlowerAnimotion;
				btnFlower.name=i.toString();
				this.flowerGifts.push(btnFlower);
				this.flowerContainer.addChild(btnFlower);
			}
			this.flowerContainer.x=1000 / 2-(30 *4+5 *3)/ 2;
			this.flowerContainer.y=500;
			this.buttonContainer.addChild(this.flowerContainer);
			this.redrawFlowerContainer();
			this.flowerAnimotion=ObjectPool.borrow(FloatAnimotion);
			this.flowerAnimotion.url=/*data.Resources.CROSS_SERVER_WAR_HUABAN*/"crossServerWar/common/huaban.png";
			this.animotionContainer.addChild(this.flowerAnimotion);
		}

		__proto.redrawFlowerContainer=function(){
			var btnTotalWdith=30 *this.flowerGifts.length+5 *(this.flowerGifts.length-1);
			var basePosition=(35 *4-5)/ 2-btnTotalWdith / 2;
			var btnAmount=this.flowerGifts.length;
			for (var i=0;i < btnAmount;i++){
				var btn=this.flowerGifts[i];
				TweenLite.to(btn,1,{x:35 *i+basePosition});
			}
		}

