		__proto.onReturnFlowerGift=function(noti){
			if (this.flowerGifts.length >=4){
				return;
			};
			var btnFlower=new ImageButton();
			btnFlower.setImage(/*data.Resources.FLOWER_GIFT*/"crossServerWar/common/vector_flower.png");
			btnFlower.click=this.showFlowerAnimotion;
			btnFlower.name=this.flowerGifts.length.toString();
			this.flowerGifts.push(btnFlower);
			this.flowerContainer.addChild(btnFlower);
			this.redrawFlowerContainer();
		}

		__proto.showFlowerAnimotion=function(e){
			if (this.flowerContainer.contains(e.target)){
				this.flowerContainer.removeChild(e.target);
			};
			var index=e.target.name;
			this.flowerGifts.splice(int(index),1);
			var len=this.flowerGifts.length;
			for (var i=0;i < len;i++){
				this.flowerGifts[i].name=i.toString();
			}
			this.redrawFlowerContainer();
			this.flowerAnimotion.play();
		}

		__proto.showFlowerAnimotionBySelf=function(message){
			this.flowerAnimotion.play();
		}

