		__proto.setStageText=function(message){
			switch (message.mainStatus){
				case 1:
				switch (message.subStatus){
					case 3:
						this.cross_server_war_name_ctf.text=LanguageRunner.getLanguageText("CROSSWAR_TONGFU_TAOTAI_RENSHEN");
						break ;
					case 5:
						break ;
					case 1:
						this.cross_server_war_name_ctf.text=LanguageRunner.getLanguageText("CROSSWAR_TONGFU_TAOTAI_RENSHEN");
						break ;
					case 6:
						break ;
					case 2:
						this.cross_server_war_name_ctf.text=LanguageRunner.getLanguageText("CROSSWAR_TONGFU_JINJI_RESHEN");
						break ;
					}
				break ;
				case 2:
				switch (message.subStatus){
					case 1:
						this.champion_battle_report_ctf.visible=false;
						this.upgrade_player_ctf.text="";
						this.cross_server_war_name_ctf.text=LanguageRunner.getLanguageText("CROSSWAR_TONGFU_TAOTAI");
						break ;
					case 2:
						this.cross_server_war_name_ctf.text=LanguageRunner.getLanguageText("CROSSWAR_TONGFU_JINJI");
						break ;
					case 3:
						this.champion_battle_report_ctf.visible=false;
						this.upgrade_player_ctf.text="";
						this.cross_server_war_name_ctf.text=LanguageRunner.getLanguageText("CROSSWAR_TONGFU_TAOTAI");
						break ;
					}
				break ;
				case 3:
				switch (message.subStatus){
					case 1:
						this.cross_server_war_name_ctf.text=LanguageRunner.getLanguageText("CROSSWAR_KUAFU_TAOTAI");
						break ;
					case 2:
						this.cross_server_war_name_ctf.text=LanguageRunner.getLanguageText("CROSSWAR_KUAFU_JINJI");
						break ;
					case 3:
						this.cross_server_war_name_ctf.text=LanguageRunner.getLanguageText("CROSSWAR_KUAFU_TAOTAI");
						break ;
					case 4:
						this.cross_server_war_name_ctf.text="";
						break ;
					}
				break ;
			}
		}

