		__proto.preListData=function(){
			var useable=this.storeVO.maxStoreLocationNum;
			var tempEquipArray=ObjectPool.borrow(Array);
			ObjectUtil.clearList(this.usedEquipArray);
			var eiVO;
			/*for each*/for(var $each_eiVO in this.storeVO.storeList){
				eiVO=this.storeVO.storeList[$each_eiVO];
				eiVO.isTemp ? tempEquipArray.push(eiVO):this.usedEquipArray.push(eiVO);
			}
			this.usedEquipArray.sortOn(["tempPastTime","id","level"],[0,Array.NUMERIC,Array.NUMERIC | Array.DESCENDING]);
			tempEquipArray.sortOn(["tempPastTime","id","level"],[0,Array.NUMERIC,Array.NUMERIC | Array.DESCENDING]);
			var totalUsable=useable+tempEquipArray.length;
			var missGridLength=(24-totalUsable % 24)% 24;
			var totalGridLength=totalUsable+missGridLength;
			ObjectUtil.clearList(this.renderVOArray)
			var blankUseableEquipVO=ObjectPool.borrow(EquipVO);
			var blankUnuseableEquipVO=ObjectPool.borrow(EquipVO);
			var equipVO;
			for (var i=0;i < totalGridLength;i++){
				var storeRenderVO=ObjectPool.borrow(StoreEquipItemRendererVO);
				if (i < useable){
					equipVO=this.usedEquipArray[i];
					if (equipVO !=null){
						storeRenderVO.equipVO=equipVO;
						storeRenderVO.onTempPastTimer=this.onTempPastTimer;
						storeRenderVO.onTempPastTimerComplete=this.onTempPastTimerComplete;
					}
					else{
						storeRenderVO.equipVO=blankUseableEquipVO;
					}
					storeRenderVO.equipVO.isLocked=false;
				}
				else{
					equipVO=tempEquipArray.shift();
					if (equipVO !=null){
						storeRenderVO.equipVO=equipVO;
						storeRenderVO.onTempPastTimer=this.onTempPastTimer;
						storeRenderVO.onTempPastTimerComplete=this.onTempPastTimerComplete;
					}
					else{
						storeRenderVO.equipVO=blankUnuseableEquipVO;
					}
					storeRenderVO.equipVO.isLocked=true;
				}
				this.renderVOArray.push(storeRenderVO);
			}
			this.equipPanel.storeListFlipPage.totalPages=Math.ceil(this.renderVOArray.length / 24);
			ObjectPool.dispose(tempEquipArray);
		}

		__proto.onSwitchStoreFlipPage=function(page){
			this.setEmptyStatus();
			if (page !=this.oldPage){
				this.oldRenderIndex=0;
			}
			this.oldPage=page;
			var flipPageArray=FlipPageUtil.flipPageArray(page,24,this.renderVOArray);
			this.equipPanel.storeEquipList.clear();
			this.equipPanel.storeEquipList.update(flipPageArray);
			if(flipPageArray.length<=0){
				var _page=--page;
				if(_page>0){
					this.oldPage=_page;
					this.updateFlipPage();
					this.onSwitchStoreFlipPage(this.oldPage);
				}
				return;
			};
			var render;
			if (this.tempGeneralListSelectedIndex >=0){
				if (this.tempGeneralListSelectedIndex <=this.equipPanel.storeEquipList.getRenders().length-1){
					render=(this.equipPanel.storeEquipList.selectRenderer(this.tempGeneralListSelectedIndex));
				}
				else{
					render=(this.equipPanel.storeEquipList.selectRenderer(0));
				}
			}
			else{
				render=(this.equipPanel.storeEquipList.selectRenderer(0));
			}
			this.updateTipsData();
		}

