		__proto.onChangeEquipStatusResponse=function(note){
			var message=note.body;
			if(this.currentEquipVO==null){
				return;
			}
			if (message.equipRealId !=this.currentEquipVO.realID){
				return;
			}
			switch (message.bindType){
				case /*functions.equip.model.EquipBindType.NO_BIND*/0:
					break ;
				case /*functions.equip.model.EquipBindType.BINDED*/1:
					break ;
				case /*functions.equip.model.EquipBindType.BIND_CD*/2:
					if (Number(message.bindTime)> 0){
						this.equipPanel.txtbindingcd.startCountDown(Number(message.bindTime));
					}
					break ;
				}
			for (var i=0;i < this.strongEquipVOList.length;i++){
				var equipTempVO=this.strongEquipVOList[i];
				if (equipTempVO.realID==message.equipRealId){
					(this.strongEquipVOList[i]).bindType=message.bindType;
					var slir;
					/*for each*/for(var $each_slir in this.equipPanel.strongEquipList.getRenders()){
						slir=this.equipPanel.strongEquipList.getRenders()[$each_slir];
						if (slir.equipVO.realID==message.equipRealId){
							slir.equipVO.bindType=message.bindType;
							(slir.value).equipVO.bindType=message.bindType;
							slir.update(slir.value);
							break ;
						}
					}
					break ;
				}
			}
			this.setBindStatusView(message.bindType);
			if(this.currentEquipVO.hole1Gem !=0 || this.currentEquipVO.hole2Gem !=0){
				this.equipPanel.btnStrongSell.enabled=false;
				this.equipPanel.btnStrongSell.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("GEM_EQUIP_PANEL_NOT_SALE"));
			}
		}

		__proto.onUpdateSingleEquipData=function(note){
			if (this.panelMediator.isOpen==false || this.panelMediator.currentTabIndex !=/*functions.equip.view.EquipPanelMediator.TAB_STRONG*/3){
				return;
			};
			var equipVO=note.body;
			if (this.currentEquipVO !=null){
				if (this.currentEquipVO.id==equipVO.id){
					this.sendNotification(/*global.NotificationType.GET_EQUIP_MAGIC_VALUE*/"getEquipMagicValue");
					this.showEquipInfo(equipVO);
				}
				for (var i=0;i < this.strongEquipVOList.length;i++){
					var equipTempVO=this.strongEquipVOList[i];
					if (equipTempVO.realID==equipVO.realID){
						this.strongEquipVOList[i]=this.strongOrJiangJiUpdateEquipVO(this.strongEquipVOList[i],equipVO);
						var slir;
						/*for each*/for(var $each_slir in this.equipPanel.strongEquipList.getRenders()){
							slir=this.equipPanel.strongEquipList.getRenders()[$each_slir];
							if (slir.equipVO.realID==equipVO.realID){
								slir.equipVO=this.strongOrJiangJiUpdateEquipVO(slir.equipVO ,equipVO);
								(slir.value).equipVO=this.strongOrJiangJiUpdateEquipVO((slir.value).equipVO ,equipVO);
								slir.update(slir.value);
								break ;
							}
						}
						break ;
					}
				}
				}else {
				this.clearEquipInfo();
			}
		}

		__proto.strongOrJiangJiUpdateEquipVO=function(oldEquip,equipVO){
			oldEquip.id=int(equipVO.id);
			oldEquip.realID=equipVO.realID;
			oldEquip.curPartNum=equipVO.curPartNum;
			oldEquip.tempPastTime=equipVO.tempPastTime;
			oldEquip.bindType=equipVO.bindType;
			oldEquip.level=equipVO.level;
			oldEquip.returnSilverPrice=equipVO.returnSilverPrice;
			oldEquip.isPartsEnough=(equipVO.curPartNum >=equipVO.equipInfoVO.overLapLimit);
			oldEquip.generalID=equipVO.generalID;
			oldEquip.location=equipVO.location;
			oldEquip.needSilver=equipVO.needSilver;
			oldEquip.bindTime=Number(equipVO.bindTime);
			oldEquip.bindType=equipVO.bindType;
			oldEquip.attributesComprehensive=equipVO.attributesComprehensive;
			return oldEquip;
		}

