	//file:///e:/work/sgwork/h5sg2/sg4/src/functions/esoterica/controller/esotericaopengotopanelorder.as
	//class functions.esoterica.controller.EsotericaOpenGotoPanelOrder extends core.patterns.command.SimpleOrder
	var EsotericaOpenGotoPanelOrder=(function(_super){
		function EsotericaOpenGotoPanelOrder(){
			EsotericaOpenGotoPanelOrder.__super.call(this);
		}

		__class(EsotericaOpenGotoPanelOrder,'functions.esoterica.controller.EsotericaOpenGotoPanelOrder',false,_super);
		var __proto=EsotericaOpenGotoPanelOrder.prototype;
		__proto.execute=function(note){
			_super.prototype.execute.call(this,note);
			var scene=int(note.body);
			var panelId=int(note.type);
			var panelTab=note.args[0];
			var resourceDataVO=note.body;
			if(scene !=0){
				switch(scene){
					case /*functions.game.model.SceneType.AREA*/3:
						this.sendNotification(/*global.NotificationType.SWITCH_TO_AREA*/"switchToArea");
						break ;
					case /*functions.game.model.SceneType.SELECT_CITY*/8:
						this.sendNotification(/*global.NotificationType.SWITCH_TO_SELECT_CITY*/"switchToSelectCity");
						break ;
					case /*functions.game.model.SceneType.FARM*/5:
						this.sendNotification(/*global.NotificationType.SWITCH_TO_FARM*/"switchToFarm");
						break ;
					case /*functions.game.model.SceneType.POWER*/1:
						this.sendNotification(/*global.NotificationType.SWITCH_TO_POWER*/"switchToPower");
						break ;
					case /*functions.game.model.SceneType.BUILD*/2:
						this.sendNotification(/*global.NotificationType.SWITCH_TO_CITY*/"switchToCity");
						break ;
					case /*functions.game.model.SceneType.WORLD*/6:
						this.sendNotification(/*global.NotificationType.SWITCH_TO_WORLD*/"switchToWorld");
						break ;
					case /*functions.game.model.SceneType.HERO_MASS*/9:{
							if(ConfigConnect.HeroMass){
								this.sendNotification(/*global.NotificationType.SWITCH_HERO_MASS_ACTIVITY*/"switch_hero_mass_activity");
							}
							break ;
						}
					case /*functions.game.model.SceneType.PROVENDER_SCENE*/10:{
							if(ConfigConnect.YunLiangSwitch){
								this.sendNotification(/*global.NotificationType.SWITCH_TO_PROVENDER*/"switchToProvender");
							}
							break ;
						}
					case /*functions.game.model.SceneType.STRONGHOLD_SCENE*/11:{
							this.sendNotification(/*global.NotificationType.STRONGHOLD_ENTER*/"stronghold_enter");
							break ;
						}
					case /*functions.game.model.SceneType.EVENT_POWER*/13:{
							this.sendNotification(/*global.NotificationType.EVENT_POWER_ENTER_SCENE*/"event_power_enter_scene");
							break ;
						}
					}
				if(panelId !=0 && !Managers.panelManager.isOpen(panelId)){
					this.sendNotification(/*global.NotificationType.OPEN_PANEL*/"openPanel",panelId);
				}
				if(panelId !=0 && panelTab >=0){
					var mediator=Managers.panelManager.getPanel(panelId);
					if(mediator !=null){
						mediator.switchTab(panelTab);
					}
				}
			}
		}

		return EsotericaOpenGotoPanelOrder;
	})(SimpleOrder)


