		__proto.setRefreshTime=function(timeUpdate){
			(timeUpdate===void 0)&& (timeUpdate=-1);
			if(timeUpdate==-1){
				timeUpdate=this.timeRefresh;
			};
			var currentTimestamp=ServerTimeUitl.getInstance().getServerTimestamp();
			var rt=timeUpdate-currentTimestamp;
			var dayNow=StringUtil1.formatTime(currentTimestamp,"dd",true);
			var dayUpdate=StringUtil1.formatTime(timeUpdate,"dd",true);
			if(dayNow !=dayUpdate){
				this.view.labelRefreshTime.text=LanguageRunner.getLanguageText("EVENT_POWER_LANGUAGE_29");
				return;
			}
			if(timeUpdate-currentTimestamp < 0){
				var msg2=ObjectPool.borrow(JzDefGetMonRefTimeMessage);
				Server.send(msg2);
				return;
			}
			this.view.labelRefreshTime.text=StringUtil1.format(LanguageRunner.getLanguageText("EVENT_POWER_LANGUAGE_7"),
			StringUtil1.formatTime(rt,"HH:mm:ss",true));
		}

		__proto.onUpdateRefreshTime=function(){
			this.setRefreshTime();
		}

