		__proto.ReceiveFlagNewSlotEquipInfo=function(msg){
			var itemVOArr=this.SetFlagSlotEquip(this._msg);
			var tempNewSlotList=[];
			var posInfo;
			/*for each*/for(var $each_posInfo in msg.stuffs){
				posInfo=msg.stuffs[$each_posInfo];
				var itemVO=new FlagSlotRenderVO();
				itemVO.isNewPosition=true;
				itemVO.openNewInfo=this._newFlagPositionOpenInfo[posInfo.stuffId];
				if(posInfo.stuffNum==-1){
					itemVO.openNewInfo.flagPositionIsOpen=false;
				}
				else if(posInfo.stuffNum==0){
					itemVO.openNewInfo.flagPositionIsOpen=true;
				}
				else if(posInfo.stuffNum > 0){
					itemVO.openNewInfo.flagPositionIsOpen=true;
					this.GetSlotFlagInfo(posInfo.stuffNum,itemVO);
				}
				tempNewSlotList.push(posInfo);
				itemVOArr.push(itemVO);
			}
			this.sendNotification(/*global.NotificationType.UPDATE_FLAGSLOT_EQUIP*/"update_flagslot_equip",itemVOArr);
			if(this.newSlotIsOpenList==null){
				this.newSlotIsOpenList=[];
			}
			else{
				for(var i=0;i < this.newSlotIsOpenList.length;i++){
					for(var j=0;j< tempNewSlotList.length;j++){
						var newSlotOldInfo=this.newSlotIsOpenList[i];
						var newSlotNewInfo=tempNewSlotList[j];
						if(newSlotOldInfo.stuffNum==-1 && newSlotNewInfo.stuffNum==0){
							this.showNoticeTxt(LanguageRunner.getLanguageText("FLAG_NEW_SLOT_OPEN_SUCCESS"));
							break ;
						}
					}
				}
				this.newSlotIsOpenList=tempNewSlotList;
			}
		}

