		__proto.switchToHeroFight=function(note){
			if(ResourcesStatus.has_practise_soldier_swf){
				this.showToHeroFight(note);
				}else{
				this.sendNotification(/*global.NotificationType.START_SMALL_LOADING*/"startSmallLoading",["qxfz.swf"],__bind(this,this.showToHeroFight),note);
			}
		}

		__proto.showToHeroFight=function(note){
			var mediator=this.context.view.getMediator(HeroFightMainMediator);
			if(!ResourcesStatus.has_hero_fight_swf){
				ResourcesStatus.has_hero_fight_swf=true;
				DisplayUtil.addChild(mediator.mainView,this.layerManager.heroFightLayer);
				mediator.init();
			}
			mediator.openView();
			this.sendNotification(/*global.NotificationType.CHAT_FRAME_HIDE*/"CHAT_FRAME_HIDE",true);
			Managers.sceneManager.switchScene(Managers.sceneManager.heroFightScene);
		}

