		__proto.sortGeneralsInVector=function(general1,general2){
			if (general1.generalLevel < general2.generalLevel){
				return 1;
			}
			else if (general1.generalLevel > general2.generalLevel){
				return-1;
			}
			else{
				if (general1.generalID < general2.generalID){
					return 1;
				}
				else{
					return-1;
				}
			}
		}

