		__proto.getInheritCostInfo=function(generalInfo){
			var spSkillLv=generalInfo.generalAwakeningInfo.awakeningLv;
			var resultDic=new Dictionary();
			if(spSkillLv==0)return resultDic;
			var totalArr=[];
			for(var lv=generalInfo.generalAwakeningInfo.tlv;lv > 0;lv--){
				var tSpId=this.getSpIdByLv(/*functions.GeaneralAwaken.model.GeneralAwakenEnum.T*/1,lv,generalInfo.generalAwakeningInfo.generalId);
				var arr=this.getSpLvUpCost(tSpId);
				totalArr=totalArr.concat(arr);
			}
			for(lv=generalInfo.generalAwakeningInfo.ylv;lv > 0;lv--){
				var ySpId=this.getSpIdByLv(/*functions.GeaneralAwaken.model.GeneralAwakenEnum.Y*/2,lv,generalInfo.generalAwakeningInfo.generalId);
				totalArr=totalArr.concat(this.getSpLvUpCost(ySpId));
			}
			for(lv=generalInfo.generalAwakeningInfo.ylv;lv > 0;lv--){
				var zSpId=this.getSpIdByLv(/*functions.GeaneralAwaken.model.GeneralAwakenEnum.Z*/3,lv,generalInfo.generalAwakeningInfo.generalId);
				totalArr=totalArr.concat(this.getSpLvUpCost(zSpId));
			};
			var itemProxy=this.context.model.getProxy(ItemProxy);
			for(var i=0;i < totalArr.length;i++){
				var info=totalArr[i].split(":");
				var itemInfo=itemProxy.getInfoVOByID(info[0]);
				if(this.itemIdArr.indexOf(itemInfo.id)< 0)continue ;
				if(resultDic[itemInfo.id] !=null){
					resultDic[itemInfo.id]+=int(info[1]);
				}
				else{
					resultDic[itemInfo.id]=int(info[1]);
				}
			}
			return resultDic;
		}

