				tipVO=new GeneralAwakenTipVO();
				tipVO.title=LanguageRunner.getLanguageText("GENERAL_AWAKEN_SKILL_LABEL")+":"+spNameArr[i];
				tipVO.content=awkenProxy.getGeneralAwakenTipsInfo(spIdArr[i]);
				spImg.toolTip=tipVO;
				spImg.name=spIdArr[i].toString();
