	//class functions.general.controller.ClearUpGeneralTrainTimeModeViewOrder extends core.patterns.command.SimpleOrder
	var ClearUpGeneralTrainTimeModeViewOrder=(function(_super){
		function ClearUpGeneralTrainTimeModeViewOrder(){
			ClearUpGeneralTrainTimeModeViewOrder.__super.call(this);
		}

		__class(ClearUpGeneralTrainTimeModeViewOrder,'functions.general.controller.ClearUpGeneralTrainTimeModeViewOrder',false,_super);
		var __proto=ClearUpGeneralTrainTimeModeViewOrder.prototype;
		__proto.execute=function(note){
			_super.prototype.execute.call(this,note);
			var mediator=note.body;
			var message=note.type;
			var gtp=this.getProxy(GeneralTrainProxy);
			var list=[];
			DisplayUtil.removeAllChildrenToPool(mediator.generalPanel.containerSelectTimeMode);
			var lttmb;
			/*for each*/for(var $each_lttmb in message.timeModes){
				lttmb=message.timeModes[$each_lttmb];
				var obj={};
				obj["timeID"]=int(lttmb.timeModeId);
				obj["time"]=String(gtp.getTrainTimeInfoVO(lttmb.timeModeId).timeDesc);
				obj["value"]=(gtp.getTrainTimeInfoVO(lttmb.timeModeId).isGold==true)? String(lttmb.count)+LanguageRunner.getLanguageText("GOLD"):String(lttmb.count)+LanguageRunner.getLanguageText("SILVER");
				list.push(obj);
			}
			mediator.radioButtonGroupTimeModeList.clear();
			var rg=mediator.radioButtonGroupTimeModeList;
			var ypadding=0;
			var tObj;
			/*for each*/for(var $each_tObj in list){
				tObj=list[$each_tObj];
				var radio=ObjectPool.borrow(Radio);
				radio.label=tObj["time"]+" "+tObj["value"];
				radio.data=int(tObj["timeID"]);
				rg.addItem(radio);
				mediator.generalPanel.containerSelectTimeMode.addChild(radio);
				radio.y=ypadding;
				ypadding+=radio.height+4;
			}
			if(mediator.timeModeSelectedIndex==-1){
				rg.selectFirstSelectable();
				}else{
				rg.getItemAt(mediator.timeModeSelectedIndex).selected=true;
			}
			mediator.generalPanel.btnStartTrain.enabled=true;
		}

		return ClearUpGeneralTrainTimeModeViewOrder;
	})(SimpleOrder)


