		__proto.sortFunc=function(a,b){
			if(a.isRecruited > b.isRecruited){
				return-1;
			}
			else if(a.isRecruited < b.isRecruited){
				return 1;
			}
			else {
				if(a.isRecommandGeneral > b.isRecommandGeneral){
					return-1;
				}
				else if(a.isRecommandGeneral < b.isRecommandGeneral){
					return 1;
				}
				else{
					if(a.generalTime < b.generalTime){
						return-1;
					}
					else if(a.generalTime > b.generalTime){
						return 1;
						}{
						return 0;
					}
				}
			}
		}

