	//file:///e:/work/sgwork/h5sg2/sg4/src/functions/general/controller/getmaxvaluedataorder.as
	//class functions.general.controller.GetMaxvalueDataOrder extends core.patterns.command.SimpleOrder
	var GetMaxvalueDataOrder=(function(_super){
		function GetMaxvalueDataOrder(){
			GetMaxvalueDataOrder.__super.call(this);
		}

		__class(GetMaxvalueDataOrder,'functions.general.controller.GetMaxvalueDataOrder',false,_super);
		var __proto=GetMaxvalueDataOrder.prototype;
		__proto.execute=function(note){
			_super.prototype.execute.call(this,note);
			var str=note.body;
			var id=int(str.substring(0,2)+"01");
			var gap=this.getProxy(GeneralArrayProxy);
			var gpatm=this.getMediator(GeneralPanelArrayTagMediator);
			for(var j=0;j < 9;j++){
				var temp=gpatm.arrayMaxVO.seatValues.length==9;
				var seatMaxVO;
				if(!temp){
					seatMaxVO=new GeneralArraySeatVO();
					seatMaxVO.isOpen=gap.getArrayInfoVOByID(str).getOpenStatus(j);
					}else {
					gpatm.arrayMaxVO.seatValues[j].isOpen=gap.getArrayInfoVOByID(str).getOpenStatus(j);
				}
				for(var i=id;i<id+20;i++){
					var openState=gap.getArrayInfoVOByID(i.toString()).getOpenStatus(j);
					if(openState==true){
						if(!temp){
							seatMaxVO.openLevel=i%100;
							}else {
							gpatm.arrayMaxVO.seatValues[j].openLevel=i%100;
						}
						openState==false;
						break ;
					}
				}
				if(!temp)gpatm.arrayMaxVO.seatValues.push(seatMaxVO);
				var npcLookTabInfoMediator=this.getMediator(PowerNewLookNpcTabInfoMediator);
				var powerNewLookNpcTabEmbattleMediator=this.getMediator(PowerNewLookNpcTabEmbattleMediator);
				var marslookTabCombatMEdiator=this.getMediator(MarsNpcPanelCombatTabMediator);
				var marsnpcTabInfoMEdiator=this.getMediator(MarsNpcPanelInfoTabMediator);
				if(!temp){
					npcLookTabInfoMediator.arrayMaxVO.seatValues.push(seatMaxVO);
					powerNewLookNpcTabEmbattleMediator.arrayMaxVO.seatValues.push(seatMaxVO);
					marslookTabCombatMEdiator.arrayMaxVO.seatValues.push(seatMaxVO);
					marsnpcTabInfoMEdiator.arrayMaxVO.seatValues.push(seatMaxVO);
				}
			}
		}

		return GetMaxvalueDataOrder;
	})(SimpleOrder)


