		__proto.setBtnChuanChengTipsAndStatus=function(){
			if (!ConfigConnect.chuanchengBtnSwitch){
				this.panel.btnChuanCheng.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("EXPECTING_FUNCTION"));
				this.panel.btnChuanCheng.enabled=false;
				return;
			};
			var dic=ClientDataProxy.getClientDataProxy().generalsChuanChengLevelLimit;
			var levelLimit=dic[1].lv_limit;
			if (this.currentGeneralInfoVO.generalLevel < int(levelLimit)){
				var tishi=LanguageRunner.getLanguageText("INHERIT_TIPS_01");
				this.panel.btnChuanCheng.toolTip=TipUtil.getTextTipVO(StringUtil1.format(tishi,levelLimit));
				this.panel.btnChuanCheng.enabled=false;
			}
			else{
				this.panel.btnChuanCheng.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("INHERIT_TIPS_02"));
				this.panel.btnChuanCheng.enabled=true;
			}
		}

		__proto.setBtnUseBookTipsAndStatus=function(){
			var roleVO=(this.getProxy(RoleProxy)).roleVO;
			if (!this.currentGeneralInfoVO){
				return;
			}
			if (!this.panel.booksList){
				return;
			}
			var rednerer;
			/*for each*/for(var $each_rednerer in this.panel.booksList.getRenders()){
				rednerer=this.panel.booksList.getRenders()[$each_rednerer];
				if (!rednerer){
					continue ;
				}
				if (!ConfigConnect.chuanchengBtnSwitch){
					rednerer.btnUseBook.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("EXPECTING_FUNCTION"));
					rednerer.btnUseBook.enabled=false;
				}
				else if (this.currentGeneralInfoVO.generalLevel >=int(rednerer.booksVO.bookLv)){
					rednerer.btnUseBook.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("INHERIT_TIPS_03"));
					rednerer.btnUseBook.enabled=false;
				}
				else if (int(rednerer.booksVO.bookLv)> roleVO.level){
					rednerer.btnUseBook.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("INHERIT_TIPS_04"));
					rednerer.btnUseBook.enabled=false;
				}
				else if (rednerer.booksVO.count < 1){
					rednerer.btnUseBook.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("INHERIT_TIPS_05"));
					rednerer.btnUseBook.enabled=false;
				}
				else{
					rednerer.btnUseBook.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("INHERIT_TIPS_06")+rednerer.booksVO.bookLv);
					rednerer.btnUseBook.enabled=true;
				}
			}
		}

