		__proto.revGvgLogin=function(msg1){
			console.log("GvgConfig.conntectCrossServerType==="+GvgConfig.conntectCrossServerType);
			if(msg1.act==2 ||msg1.act==1){
				var msg4=ObjectPool.borrow(GVGGetSystemTimeMessage);
				Server.send(msg4);
				if(GvgConfig.conntectCrossServerType==0){
					var msg=ObjectPool.borrow(GetGVGWorldBasicInfoMessage);
					Server.send(msg);
				}
				else if(GvgConfig.conntectCrossServerType==1){
					var msg2=ObjectPool.borrow(GVGGetJunfuMessage);
					Server.send(msg2);
					var msg0=ObjectPool.borrow(GVGGetJunxiangExchangeInfoMessage);
					Server.send(msg0);
				}
				else if(GvgConfig.conntectCrossServerType==2){
					var msg3=ObjectPool.borrow(GVGGetForceRankListMessage);
					Server.send(msg3);
				}
			}
			else if(msg1.act==4){
				PromptBoxRunner.getInstance().openBlueAlert(LanguageRunner.getLanguageText("GVG_LOGIN_ERROR"));
			}
			else{
				PromptBoxRunner.getInstance().openBlueAlert(LanguageRunner.getLanguageText("GVG_LOGIN_ERROR2"));
			}
		}

