		__proto.updateCityInfo=function(msg){
			var city=this._gvgCityDic[msg.cityId];
			city.cityForce=msg.force;
			city.forceShortName=this.getForceShortName(city.cityForce);
			city.cityDefends=msg.cityDefends;
			city.defNums=msg.defForceNums;
			city.attNums=msg.attForceNums;
			if(Number(msg.protectTime)> 0){
				city.protectTime=Number(msg.protectTime)-GvgConfig.getServerTimestamp();
			}
			else{
				city.protectTime=0
			}
			city.isDestroyed=msg.isDestroyed;
			if(msg.cityStatus==2 && city.cityStatus !=2 && city.cityForce==this.gvgRoleInfo.force){
				var str=StringUtil1.format(LanguageRunner.getLanguageText("GVG_NOTICE_STRING_1"),city.cityName,/*functions.gvg.view.GvgNoticePanel.CITY_LINK*/"city",/*functions.gvg.view.GvgNoticePanel.LINK_SEPARATOR*/"|",city.cityId);
				this.sendNoticeNotification(str);
			}
			city.cityStatus=msg.cityStatus;
			if(city.defNums !="" && city.attNums !=""){
				this.sendNotification(/*global.NotificationType.GVG_UPDATE_CITY_WAR_INFO*/"GVG_UPDATE_CITY_WAR_INFO",city);
			}
			this.sendNotification(/*global.NotificationType.GVG_UPDATE_CITY_INFO*/"GVG_UPDATE_CITY_INFO",city);
		}

