		__proto.revCityListInfo=function(msg){
			var city;
			/*for each*/for(var $each_city in msg.cityList){
				city=msg.cityList[$each_city];
				var cityInfo=ObjectPool.borrow(GvgCityInfo);
				cityInfo.cityId=city.cityId;
				cityInfo.cityForce=city.force;
				cityInfo.cityStatus=city.cityStatus;
				var obj=this.gvgCityInfo[city.cityId];
				cityInfo.cityImg="gvg/"+obj["city_pic"];
				var position=obj["city_position"];
				cityInfo.cityX=position.split("|")[0];
				cityInfo.cityY=position.split("|")[1];
				cityInfo.cityName=LanguageRunner.getLanguageText(obj["city_name"]);
				cityInfo.cityNeighbour=obj["city_neighbour"];
				cityInfo.cityDefValue=obj["city_def"];
				cityInfo.cityMaxDefValue=obj["city_def_max"];
				cityInfo.forceShortName=this.getForceShortName(cityInfo.cityForce);
				var deffBuffArr=obj["city_buff_defense"].split("|");
				cityInfo.cityDeffBuffArr=[];
				cityInfo.cityAttackBuffArr=[];
				for(var i=0;i < deffBuffArr.length;i++){
					if(deffBuffArr[i] !=""){
						cityInfo.cityDeffBuffArr.push(deffBuffArr[i]);
					}
				};
				var attakBuffArr=obj["city_buff_attack"].split("|");
				for(var j=0;j < attakBuffArr.length;j++){
					if(attakBuffArr[j] !=""){
						cityInfo.cityAttackBuffArr.push(attakBuffArr[j]);
					}
				}
				cityInfo.isDestroyed=city.isDestroyed;
				if(Number(city.protectTime)> 0){
					cityInfo.protectTime=Number(city.protectTime)-GvgConfig.getServerTimestamp();
				}
				else{
					cityInfo.protectTime=0;
				}
				this._gvgCityDic[city.cityId]=cityInfo;
			}
			this.sendNotification(/*global.NotificationType.GVG_CITY_LIST*/"GVG_CITY_LIST",this._gvgCityDic);
		}

