		__proto.revGvgWorldBaseInfo=function(msg){
			this.sendNotification(/*global.NotificationType.HIDE_SMALL_LOADING*/"hideSmallLoading");
			this._gvgWorldBaseInfo.actId=msg.actId;
			this._gvgWorldBaseInfo.beginTime=Number(msg.beginTime);
			this._gvgWorldBaseInfo.endTime=Number(msg.endTime);
			this._gvgWorldBaseInfo.isSelectForce=msg.isSelectForce;
			this._gvgWorldBaseInfo.period=msg.period;
			this.sendNotification(/*global.NotificationType.GVG_SHOW_GVG_TIEM*/"GVG_SHOW_GVG_TIEM",msg);
			if(msg.period==3){
				GvgConfig.conntectCrossServerType=2;
				this.sendNotification(/*global.NotificationType.HIDE_SMALL_LOADING*/"hideSmallLoading");
				this.sendNotification(/*global.NotificationType.OPEN_PANEL*/"openPanel",/*functions.panel.model.PanelType.GVG_FINAL_RANK_PANEL*/181);
				return;
			}
			else if(GvgConfig.conntectCrossServerType==0){
				this.sendNotification(/*global.NotificationType.CHATFRAME_VISIBLE*/"chatFrameVisible",false);
				this.sendNotification(/*global.NotificationType.CHAT_FRAME_HIDE*/"CHAT_FRAME_HIDE",true);
			}
			this.sendNotification(/*global.NotificationType.GVG_REV_WORLD_BASE_INFO*/"GVG_REV_WORLD_BASE_INFO",this._gvgWorldBaseInfo);
		}

