				proxy.showPromptTxt(LanguageRunner.getLanguageText("GVG_PROTECT_TIME_CITY_CAN_NOT_ATTACK"));
				this.sendNotification(/*global.NotificationType.CHW_HIDE_CITY_VIEW*/"CHW_HIDE_CITY_VIEW",this.gvgCityInfoView);
				this.gvgCityInfoView.visible=false;
				return;
