		__proto.setJoinFightId=function(note){
			var msg=note.body;
			var chwproxy=this.getProxy(CountryHarassWarProxy);
			if(chwproxy.joinFightId !="0"){
				this.sendNotification(/*global.NotificationType.CHW_BATTLE_BREAK_OFF*/"CHW_BATTLE_BREAK_OFF",1,false,/*functions.countryHarassWar.model.CountryHarassWarProxy.JOIN_FIGHT*/0);
				this.sendNotification(/*global.NotificationType.CHW_CITY_START_NEW_FIGHT*/"CHW_CITY_START_NEW_FIGHT");
				chwproxy.joinFightId=msg.fightId;
				chwproxy.joinFightCityId=msg.cityId;
				chwproxy.joinFightIndex=-1;
				chwproxy.requestNextFight(chwproxy.joinFightCityId,chwproxy.joinFightId,chwproxy.joinFightIndex);
				chwproxy.joinFightIndex=0;
			}
			chwproxy.joinFightId=msg.fightId;
			chwproxy.joinFightCityId=msg.cityId;
			if(chwproxy.joinFightIndex==-1){
				var gvgProxy=this.getProxy(GvgProxy);
				if(GvgConfig.needRequestFight && gvgProxy.gvgRoleInfo.soldierStatus==3 && !this.checkSoldierIsMove()&& !chwproxy.joinFightIsPlay){
					chwproxy.requestNextFight(chwproxy.joinFightCityId,chwproxy.joinFightId,chwproxy.joinFightIndex);
					chwproxy.joinFightIndex=0;
				}
			}
			GvgConfig.needRequestFight=false;
		}

		__proto.receiveUserId=function(note){
			if(this.isReceiveUserIdStaus==0){
				this.isReceiveUserIdStaus=1;
				var roleProxy=this.getProxy(RoleProxy);
				var msg=ObjectPool.borrow(GVGLoginMessage);
				msg.playerId=roleProxy.roleVO.id;
				msg.userid=roleProxy.roleVO.userID;
				msg.authCode=GvgConfig.AUTH_CODE;
				Server.send(msg);
			}
		}

		__proto.getGvgAuth=function(note){
			var revMsg=note.body;
			if(revMsg.result==1){
				var roleProxy=this.getProxy(RoleProxy);
				var msg=ObjectPool.borrow(GVGLoginMessage);
				msg.playerId=roleProxy.roleVO.id;
				if(roleProxy.roleVO.userID=="" || roleProxy.roleVO.userID==null){
					this.isReceiveUserIdStaus=0;
				}
				else{
					this.isReceiveUserIdStaus=1;
					msg.userid=roleProxy.roleVO.userID;
					msg.authCode=revMsg.authCode;
					Server.send(msg);
				}
			}
		}

