		__proto.revPlayerMoveInfo=function(note){
			this.stime=ServerTimeUitl.getInstance().getServerTimestamp();
			var s=ServerTimeUitl.getInstance().getServerTimestamp();
			var msg=note.body;
			if(msg.result==1){
				this.startMoveTime=iflash.utils.getTimer();
				this.moveTime=Number(msg.moveTime);
				this.gvgMap.revPlayerMoveInfo(msg);
				this.sendNotification(/*global.NotificationType.GVG_SOLDIER_MOVE*/"GVG_SOLDIER_MOVE",true);
				this.proxy.gvgRoleInfo.isMove=true;
				var chwProxy=this.getProxy(CountryHarassWarProxy);
				this.proxy.gvgRoleInfo.locateCityId=msg.toCityId;
			}
			else{
				this.gvgMap.setstartCityId(msg.fromCityId);
				this.gvgMap.removeAllRoadImg();
			}
			if(msg.result==2){
				this.showPromptTxt(LanguageRunner.getLanguageText("GVG_MOVE_NOT_NEARBY_CITY"));
			}
			else if(msg.result==3){
				this.showPromptTxt(LanguageRunner.getLanguageText("GVG_SOLDIER_NOT_ENOUGH"));
			}
			else if(msg.result==4){
				this.showPromptTxt(LanguageRunner.getLanguageText("GVG_MOVE_FORM_ERROR"));
			}
			else if(msg.result==5){
				this.showPromptTxt(LanguageRunner.getLanguageText("GVG_IS_FIGHTING"));
			}
			else if(msg.result==6){
				this.showPromptTxt(LanguageRunner.getLanguageText("GVG_JIN_XIANG_NOT_ENOUGH"));
			}
			else if(msg.result==7){
				this.showPromptTxt(LanguageRunner.getLanguageText("GVG_SECURITY_CITY_CAN_NOT_ATTACK"));
			}
			else if(msg.result==8){
				this.showPromptTxt(LanguageRunner.getLanguageText("GVG_MOVE_CD"));
			}
			else if(msg.result==9){
				this.showPromptTxt(LanguageRunner.getLanguageText("GVG_MOVE_STR"));
			}
			else if(msg.result==10){
				this.showPromptTxt(LanguageRunner.getLanguageText("GVG_MOVE_STR3"));
			}
			else if(msg.result==11){
				this.showPromptTxt(LanguageRunner.getLanguageText("GVG_MOVE_STR4"));
			}
			else if(msg.result==0){
				this.showPromptTxt(LanguageRunner.getLanguageText("GVG_MOVE_STR2"));
			}
		}

		__proto.showPromptTxt=function(str){
			this.proxy.showPromptTxt(str);
		}

		__proto.sendPlayerMoveMsg=function(startCityId,nextCityId){
			var curTime=iflash.utils.getTimer();
			var v=curTime-this.startMoveTime;
			if(curTime-this.startMoveTime < this.moveTime && this.moveTime > 0){
				this.showPromptTxt(LanguageRunner.getLanguageText("GVG_SOLDIER_NOT_ARRIVE_CITY"));
				return;
			};
			var cityInfo=this.proxy.getCityInfo(startCityId);
			if(cityInfo !=null){
				var arr=cityInfo.cityNeighbour.split("|");
				if(arr.indexOf(nextCityId.toString())!=-1){
					var nextCityInfo=this.proxy.getCityInfo(nextCityId);
					if(nextCityInfo.cityForce !=cityInfo.cityForce && this.proxy.getCurIsGvgEndTime()){
						this.proxy.showStopGvgNotice();
						this.gvgMap.removeAllRoadImg();
						return;
					};
					var startCityInfo=this.proxy.getCityInfo(startCityId);
					if(nextCityInfo.cityForce !=cityInfo.cityForce && startCityInfo.cityStatus==2){
						this.showPromptTxt(LanguageRunner.getLanguageText("GVG_CAN_NOT_FIGHT_ROAD"));
						this.gvgMap.removeAllRoadImg();
						return;
					};
					var msg=ObjectPool.borrow(GVGPlayerMoveMessage);
					msg.fromCityId=startCityId;
					msg.toCityId=nextCityId;
					Server.send(msg);
					var chwProxy=this.getProxy(CountryHarassWarProxy);
					chwProxy.playerMoveToCityID=nextCityId;
					this.moveTime=0;
				}
				else{
					this.showPromptTxt(LanguageRunner.getLanguageText("GVG_MOVE_NOT_NEARBY_CITY"));
					this.gvgMap.removeAllRoadImg();
				}
			}
		}

