		__proto.showSelectMap=function($x,$y){
			$x=-1 *$x;
			$y=-1 *$y;
			$x=$x+/*core.runner.StageRunner.stageWidth*/1000 / 2;
			$y=$y+/*core.runner.StageRunner.stageHeight*/600 / 2;
			if(($x*-1)> (/*functions.gvg.model.GvgConfig.WIDTH_TOTAL*/4000-/*core.runner.StageRunner.stageWidth*/1000)){
				$x=-1 *(/*functions.gvg.model.GvgConfig.WIDTH_TOTAL*/4000-/*core.runner.StageRunner.stageWidth*/1000);
			}
			if(($y*-1)> (/*functions.gvg.model.GvgConfig.HEIGHT_TOTAL*/2400-/*core.runner.StageRunner.stageHeight*/600)){
				$y=-1 *(/*functions.gvg.model.GvgConfig.HEIGHT_TOTAL*/2400-/*core.runner.StageRunner.stageHeight*/600);
			}
			if($x > 0){
				$x=0;
			}
			if($y > 0){
				$y=0;
			};
			var xy=new XY($x,$y);
			this.mouseMoveHandler(xy);
			TweenLite.to(this.gvgView,1,{x:$x,y:$y});
			return xy;
		}

		__proto.exitGvg=function(note){
			this.sendNotification(/*global.NotificationType.CHW_HIDE_MY_POSITION*/"CHW_HIDE_MY_POSITION");
			var chwProxy=this.getProxy(CountryHarassWarProxy);
			chwProxy.myJoinTeamResMsg=null;
			this.startMoveTime=0;
			this.moveTime=0;
			this.gvgMap.removeAllRoadImg();
			chwProxy.isExitGvg=true;
			this.gvgMap.clearAllCity();
			CHWBattleResourceCache.clearData();
			chwProxy.exitGvg();
			this.gvgView.hideCityView();
			var msg=ObjectPool.borrow(GVGExitWorldMessage);
			Server.send(msg);
			Managers.sceneManager.switchScene(Managers.sceneManager.cityScene);
			this.sendNotification(/*global.NotificationType.CHAT_FRAME_HIDE*/"CHAT_FRAME_HIDE",true);
			this.sendNotification(/*global.NotificationType.CHATFRAME_VISIBLE*/"chatFrameVisible",true);
			GvgConfig.needRequestFight=true;
			if(!ConfigConnect.zzsf_use_cross_on_off){
				GvgConfig.AUTH_CODE="";
				GvgConfig.IS_SEND_AUTH_MSG=false;
			}
		}

