		__proto.revMyJoinTeamInfo=function(note){
			var chwProxy=this.getProxy(CountryHarassWarProxy);
			var msg=note.body;
			if(msg.result==1){
				chwProxy.joinFightCityId=msg.cityId;
				chwProxy.joinFightId=msg.fightId;
				chwProxy.joinFightIndex=msg.index;
				if(msg.joinWay==1){
					if(msg.index==-1){
						chwProxy.joinFightIndex=0;
						msg.index=0;
					}
					chwProxy.myJoinTeamResMsg=msg;
				}
				else{
					if(Managers.sceneManager.currentScene !=Managers.sceneManager.countryHarassWarScene){
						this.proxy.enterFightScene();
					}
					if(msg.joinWay !=4){
						chwProxy.requestNextFight(msg.cityId,msg.fightId,msg.index);
					}
				}
			}
			else if(Managers.sceneManager.currentScene==Managers.sceneManager.countryHarassWarScene){
				Managers.sceneManager.switchScene(Managers.sceneManager.gvgScene);
			}
		}

