			this.subscribeNotification(/*global.NotificationType.GVG_CITY_LIST*/"GVG_CITY_LIST",__bind(this,this.revCityList));
			this.subscribeNotification(/*global.NotificationType.GVG_UPDATE_THUMB_MAP_SELECT*/"GVG_UPDATE_THUMB_MAP_SELECT",__bind(this,this.updateThumbMapSelect));
