				_$this.sendNotification(/*global.NotificationType.HERO_FIGHT_SHOW_MIN_CHAT_VIEW*/"HERO_FIGHT_SHOW_MIN_CHAT_VIEW");
				_$this.sendNotification(/*global.NotificationType.ENTER_BATTLE*/"enterBattle",reportStr,server+"?"+fightUrl,eventTransferVO,viewer,version);
