		__proto.ClickCityHandlerView=function(note){
			this.curSelectCityView=note.body;
			this.cityHandlerView.HideFightInfoCotainer();
			this.cityHandlerView.visible=this.curSelectCityView==null ?false:true;
			this.UpdateCityHandlerView();
			this.cityHandlerView.lookBtn.enabled=true;
			if(this.heroFightProxy.CheckIsShowTimeStatus()){
				this.cityHandlerView.moveBtn.enabled=false;
				this.cityHandlerView.moveBtn.setImage("qxfz/xingjunbutton_2.png");
				this.cityHandlerView.moveBtn.visible=true;
				this.cityHandlerView.fightBtn.visible=false;
				this.cityHandlerView.gatherBtn.enabled=false;
				this.cityHandlerView.gatherBtn.setImage("qxfz/caijibutton_2.png");
				return;
			}
			else{
				this.cityHandlerView.gatherBtn.enabled=true;
				this.cityHandlerView.gatherBtn.setImage("qxfz/caijibutton.png");
			}
			this.cityHandlerView.moveBtn.enabled=true;
			this.cityHandlerView.moveBtn.setImage("qxfz/xingjunbutton.png");
			this.cityHandlerView.moveBtn.visible=true;
			this.cityHandlerView.fightBtn.visible=false;
			var myInfo=this.heroFightProxy.GetMyInfo();
			if(this.curSelectCityView.serverCityInfo.onOff==0){
				this.cityHandlerView.moveBtn.enabled=false;
				this.cityHandlerView.moveBtn.setImage("qxfz/xingjunbutton_2.png");
			}
			else if(this.curSelectCityView.cityInfo.cityType==1){
				this.cityHandlerView.lookBtn.enabled=false;
				this.cityHandlerView.gatherBtn.enabled=false;
				this.cityHandlerView.gatherBtn.setImage("qxfz/caijibutton_2.png");
				if((this.curSelectCityView.cityInfo.isCanAttack==0&&this.curSelectCityView.serverCityInfo.camp!=myInfo.camp)|| this.curSelectCityView.cityInfo.cityNeighbors.indexOf(myInfo.cityId.toString())==-1){
					this.cityHandlerView.moveBtn.enabled=false;
					this.cityHandlerView.moveBtn.setImage("qxfz/xingjunbutton_2.png");
				}
				else{
					this.cityHandlerView.moveBtn.enabled=true;
					this.cityHandlerView.moveBtn.setImage("qxfz/xingjunbutton.png");
				}
				return;
			}
			else{
				this.cityHandlerView.lookBtn.enabled=true;
				if(this.curSelectCityView.cityInfo.cityId !=this.heroFightProxy.GetMyInfo().cityId){
					this.cityHandlerView.gatherBtn.enabled=false;
					this.cityHandlerView.gatherBtn.setImage("qxfz/caijibutton_2.png");
				}
			}
			if(this.curSelectCityView.cityInfo.cityType==5){
				this.cityHandlerView.gatherBtn.enabled=false;
				this.cityHandlerView.gatherBtn.setImage("qxfz/caijibutton_2.png");
			}
			if(this.curSelectCityView !=null){
				var msg=ObjectPool.borrow(Cs3SliadCityInfoMessage);
				msg.cityId=this.curSelectCityView.cityInfo.cityId;
				Server.send(msg);
			}
		}

		__proto.UpdateCityHandlerView=function(){
			if(this.curSelectCityView==null)return;
			var panelWidth=this.cityHandlerView.panelWidth;
			var panelHeight=this.cityHandlerView.panelHeight;
			this.cityHandlerView.x=this.curSelectCityView.x-panelWidth *0.5+65;
			this.cityHandlerView.y=this.curSelectCityView.y-panelHeight *0.5+30;
			if(this.cityHandlerView.x+panelWidth > /*core.runner.StageRunner.stageWidth*/1000){
				this.cityHandlerView.x=/*core.runner.StageRunner.stageWidth*/1000-panelWidth;
			}
			if(this.cityHandlerView.x < 0){
				this.cityHandlerView.x=0;
			}
			if(this.cityHandlerView.y+panelHeight > /*core.runner.StageRunner.stageHeight*/600){
				this.cityHandlerView.y=/*core.runner.StageRunner.stageHeight*/600-panelHeight;
			}
			if(this.cityHandlerView.y < 0){
				this.cityHandlerView.y=0;
			}
			if(this.cityHandlerView.parent==null){
				DisplayUtil.addChild(this.cityHandlerView,Managers.layerManager.heroFightLayer);
			}
		}

