		__proto.changeRewardsGoods=function(rewardsArr){
			var materialArr=ObjectPool.borrow(Array);
			var otherRewardsGoodsArr=ObjectPool.borrow(Array);
			var materialVO;
			var goods;
			for(var j=0;j< rewardsArr.length;j++){
				var arr=rewardsArr[j].split(":");
				if(arr[0]==""){
					break ;
				};
				var goodsId=int(arr[0]);
				var num=int(arr[1]);
				var obj=this.getMaterialInfo(goodsId);
				if(obj==null){
					continue ;
				}
				goods=ObjectPool.borrow(RewardsGoodsVO);
				goods.goodsId=goodsId;
				goods.goodsType=obj["type"];
				goods.goodsName=LanguageRunner.getLanguageText(obj["name"]);
				goods.goodsNum=num;
				goods.quality=obj["quality"];
				if(goods.goodsType==8){
					materialVO=ObjectPool.borrow(HeroMassDropMaterialVO);
					materialVO.heroId=0;
					materialVO.isOpen=true;
					materialVO.materialId=goodsId;
					materialVO.quality=obj["quality"];
					this.getCanJuanComposeMaterial(goodsId,materialVO);
					materialVO.materialDes=this.assembleMateralDes(LanguageRunner.getLanguageText(obj["descStr"]));
					materialVO.materialUrl=obj["iconId"];
					materialVO.materialNum=num;
					materialVO.materialName=LanguageRunner.getLanguageText(obj["name"]);
					this.addMateral(materialVO,materialArr);
				}
				else{
					otherRewardsGoodsArr.push(goods);
				}
			};
			var rewordGoodsTypeList=ObjectPool.borrow(RewardsGoodsTypeList);
			rewordGoodsTypeList.materialList=materialArr;
			rewordGoodsTypeList.otherGoodsList=otherRewardsGoodsArr;
			return rewordGoodsTypeList;
		}

		__proto.assembleMateralDes=function(des){
			var str=LanguageRunner.getLanguageText("YANXI_HECHENG_TIPS_08");
			return str;
		}

		__proto.getCanJuanComposeMaterial=function(canJunId,materialVO){
			var str="";
			var arr=ObjectPool.borrow(Array);
			var info;
			/*for each*/for(var $each_info in this.skillBookSkillMaterial){
				info=this.skillBookSkillMaterial[$each_info];
				if(info.id==canJunId){
					if(info["item_chance_1"] !=0){
						arr=this.addComposeMaterial(arr,info["item_chance_1"]);
					}
					if(info["item_chance_2"] !=0){
						arr=this.addComposeMaterial(arr,info["item_chance_2"]);
					}
					if(info["item_chance_3"] !=0){
						arr=this.addComposeMaterial(arr,info["item_chance_3"]);
					}
					if(info["item_chance_4"] !=0){
						arr=this.addComposeMaterial(arr,info["item_chance_4"]);
					}
					if(info["item_chance_5"] !=0){
						arr=this.addComposeMaterial(arr,info["item_chance_5"]);
					}
					if(info["item_chance_6"] !=0){
						arr=this.addComposeMaterial(arr,info["item_chance_6"]);
					}
					materialVO.itemChanceArr=arr;
				}
			}
		}

		__proto.addComposeMaterial=function(arr,materialId){
			var str="";
			var des;
			var materialName;
			var material=this.getMaterialInfo(materialId)
			if(material !=null){
				materialName=ColorUtil.getFontColorHtmlString(LanguageRunner.getLanguageText(material["name"]),
				EquipUtil.getEquipQualityHTMLColorByID(material["quality"]));
				des=ColorUtil.getFontColorHtmlString(LanguageRunner.getLanguageText(material["descStr"]),/*utils.ColorUtil.HTML_MAIN_ATTRIBUTE_YELLOW*/"#fbaa3f");
				str=materialName+":"+des;
			}
			arr.push(str);
			return arr;
		}

		__proto.addMateral=function($data,arr){
			var dataVO;
			/*for each*/for(var $each_dataVO in arr){
				dataVO=arr[$each_dataVO];
				if(dataVO.materialId==$data.materialId){
					dataVO.materialNum+=$data.materialNum;
					return;
				}
			}
			arr.push($data);
		}

