		__proto.onReceiveHeroListInfo=function(msg){
			ObjectUtil.clearList(this.heroListArr);
			var hero;
			var i=0;
			var heroBean;
			/*for each*/for(var $each_heroBean in msg.heroBeanList){
				heroBean=msg.heroBeanList[$each_heroBean];
				hero=ObjectPool.borrow(HeroInfoVO);
				hero.heroId=heroBean.heroId;
				hero.heroNum=heroBean.heroNum;
				hero.heroType=heroBean.heroType;
				hero.locationId=heroBean.locationId;
				var generalId=0;
				if(hero.heroType==1){
					generalId=this.getGengeralIdByBuDuiId(hero.heroId);
					hero.level=this.getGerenalLevelByTroopId(hero.heroId);
				}
				else if(hero.heroType==2){
					generalId=this.getGengeralIdByArmyId(hero.heroId);
					hero.level=this.getArmyTroopGeneralLevel(hero.heroId);
					if(this.powerArmyGroup[hero.heroId] !=null){
						var troopId=this.powerArmyGroup[hero.heroId]["troop1"];
						if(troopId !=0){
							hero.heroName=this.getArmyName(hero.heroId);
						}
					}
				};
				var heroDetail=this.getHeroDetailInfo(generalId);
				if(heroDetail!=null){
					hero.heroDescripteion=LanguageRunner.getLanguageText(heroDetail["General_des"]);
					hero.heroImgUrl=heroDetail["General_Image"];
					if(hero.heroType==1){
						hero.heroName=LanguageRunner.getLanguageText(heroDetail["General_Name"]);
					};
					var heroPos=this.getHeroPosition(hero.locationId);
					if(heroPos !=null){
						var xy=String(heroPos["hero_zuobiao"]).split("|");
						hero.heroX=xy[0];
						hero.heroY=xy[1];
					}
					i++;
				}
				this.heroListArr.push(hero);
			}
			ObjectUtil.clearList(this.materialList);
			var materialVO;
			var material;
			/*for each*/for(var $each_material in msg.materialBeanList){
				material=msg.materialBeanList[$each_material];
				if(material.materialId==0){
					continue ;
				}
				materialVO=this.changeMaterialBeanToHeroMassDropMaterialVO(material)
				this.materialList.push(materialVO);
			};
			var obje=ObjectPool.borrow(HeroAndMaterialListVO);
			obje.heroList=this.heroListArr;
			obje.materialList=this.materialList;
			this.sendNotification(/*global.NotificationType.RECEIVE_HERO_LIST_INFO*/"reveive_hero_list_info",obje);
		}

