		__proto.onOfficialInfoResponse=function(note){
			var officialInfoVO=note.body;
			if(!ConfigConnect.ContributeSwitch){
				if((this.getProxy(RoleProxy)).roleVO.vipLv>5){
					this.hkeePanel.pl_gold_left.visible=true;
					this.hkeePanel.l_gold_left.visible=true;
					this.hkeePanel.pl_gold_loss2.visible=true;
					this.hkeePanel.l_goldloss2.visible=true;
					this.hkeePanel.gold_btn2.visible=true;
					this.hkeePanel.pl_gold_loss3.visible=true;
					this.hkeePanel.l_goldloss3.visible=true;
					this.hkeePanel.gold_btn3.visible=true;
					this.hkeePanel.gold_btn2.enabled=false;
					this.hkeePanel.gold_btn3.enabled=false;
				}
			}
			if (officialInfoVO==null){
				return;
			}
			if (this.cdLeftTimer !=null){
				this.cdLeftTimer.stopCountDown();
				ObjectPool.dispose(this.cdLeftTimer);
			}
			this.cdId=officialInfoVO.cdId;
			this.hkeePanel.Txthkeeofficial.text=officialInfoVO.curOfficialVO.Officer_Name;
			this.hkeePanel.Txthkeeprestige.htmlText=String(officialInfoVO.currPrestige);
			this.hkeePanel.Txthkeebread.htmlText=String(officialInfoVO.curOfficialVO.Salary);
			if(officialInfoVO.salaryStat==SalaryState.CAN_GET){
				this.hkeePanel.btnhkeeget.enabled=true;
				this.hkeePanel.btnhkeeget.toolTip=null;
			}
			else if (officialInfoVO.salaryStat==SalaryState.ALREADY_GET){
				this.hkeePanel.btnhkeeget.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("TODAY_ALREADY_GET"));
				this.hkeePanel.btnhkeeget.enabled=false;
			}
			else if (officialInfoVO.salaryStat==SalaryState.NO_SPACE){
				this.hkeePanel.btnhkeeget.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("SILVER_NO_SPACE"));
				this.hkeePanel.btnhkeeget.enabled=false;
			}
			this.clickJunGongBtnMsg=LanguageRunner.getLanguageText("EXPLOIT_PRESTIGE",officialInfoVO.exploit,officialInfoVO.prestige);
			if (officialInfoVO.contributeStat==ExploitState.CAN_GIVE){
				this.hkeePanel.jungong_btn1.enabled=true;
				this.hkeePanel.time_container1.visible=false;
				this.hkeePanel.l_cd1.htmlText="";
			}
			else if(officialInfoVO.contributeStat==ExploitState.EXPLOIT_NOT_ENOUGH){
				this.hkeePanel.jungong_btn1.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("EXPLOIT_NOT_ENOUGH"));
				this.hkeePanel.jungong_btn1.enabled=false;
				this.hkeePanel.time_container1.visible=false;
				this.hkeePanel.l_cd1.htmlText="";
			}
			else if(officialInfoVO.contributeStat==ExploitState.IN_CD){
				var remainTime=Number(officialInfoVO.remainTime);
				this.cdLeftTimer=ObjectPool.borrow(CountDownTimer);
				this.cdLeftTimer.setCompleteFunc(__bind(this,this.onExploitTimerComplete));
				this.cdLeftTimer.setEventFunc(__bind(this,this.onExploitTimer));
				this.cdLeftTimer.startCountDown(remainTime < 1000 ? 1000 :remainTime);
				this.hkeePanel.l_cd1.htmlText=LanguageRunner.getLanguageText("BUILDING_LEVEL_UP_CD",ColorUtil.getFontColorHtmlString(StringUtil1.formatTimeToHour(remainTime < 1000 ? 1000 :remainTime),/*utils.ColorUtil.HTML_CD_RED*/"#ff6969"));
				this.hkeePanel.time_container1.visible=true;
				this.hkeePanel.jungong_btn1.enabled=false;
			}
		}

