		__proto.hideCritActivityEffect=function(evt){
			TweenLite.killTweensOf(this.rewardsEffect,false);
			var tag=evt.data;
			this.rewardsEffect.visible=false;
			if(this.rewardsEffect.parent){
				this.rewardsEffect.parent.removeChild(this.rewardsEffect);
			}
			if(tag){
				this.battlePlayEndShowEffect=false;
			}
		}

		__proto.playRewardsEffect=function(evt){
			if(this.battlePlayEndShowEffect){
				this.rewardsEffect.x=120;
				this.rewardsEffect.y=340;
				this.setPowerEffect();
			}
		}

		__proto.onReceiveCritActivity=function(note){
			var num=(note.body).value;
			if(num==1){
				return;
			}
			this.rewardsEffect.visible=false;
			this.rewardsEffect.url=ConfigConnect.LangType+"/"+"hkee/baoJi"+num+".png";
			this.rewardsEffect.alpha=0;
			if(Managers.sceneManager.currentScene==Managers.sceneManager.powerScene && !Managers.panelManager.isOpen(/*functions.panel.model.PanelType.HKEE_PANEL*/17)){
				this.battlePlayEndShowEffect=true;
			}
			else{
				this.rewardsEffect.x=585;
				this.rewardsEffect.y=210;
				this.setTaxEffect();
			}
		}

		__proto.setTaxEffect=function(){
			var _$this=this;
			TweenLite.killTweensOf(this.rewardsEffect,false);
			this.rewardsEffect.alpha=0;
			this.rewardsEffect.visible=true;
			if(!this.rewardsEffect.parent){
				LayerRunner.promptLayer.addChild(this.rewardsEffect);
			}
			TweenLite.to(this.rewardsEffect,2,{alpha:1,onComplete:function (){
					TweenLite.to(_$this.rewardsEffect,1.5,{alpha:0,delay:0.5,onComplete:function (){
							if(_$this.rewardsEffect.parent){
								DisplayUtil.removeChild(_$this.rewardsEffect,_$this.rewardsEffect.parent);
							}
					}});
			}});
		}

