		__proto.setNextZhanGong=function(zhangong){
			var shenbingPointPrice;
			if(HowardTheDuckProxy.isAbroadRewards){
				shenbingPointPrice=ClientDataProxy.getClientDataProxy().shenbingPointPriceAbroad;
			}
			else{
				shenbingPointPrice=ClientDataProxy.getClientDataProxy().shenbingPointPrice;
			}
			var obj;
			/*for each*/for(var $each_obj in shenbingPointPrice){
				obj=shenbingPointPrice[$each_obj];
				if(int(zhangong)>=int(obj["point_min"])&& int(zhangong)<=int(obj["point_Max"])){
					var targetZhanGong=int(obj["point_Max"])+1;
					this.view.txtTiShi.text=StringUtil1.format(LanguageRunner.getLanguageText("SHENBING_TEXT_058"),targetZhanGong);
					break ;
				}
			}
			if(this.view.txtTiShi.text.length <=0){
				if(int(zhangong)< int(shenbingPointPrice[1]["point_min"])){
					targetZhanGong=int(shenbingPointPrice[1]["point_min"]);
					this.view.txtTiShi.text=StringUtil1.format(LanguageRunner.getLanguageText("SHENBING_TEXT_058"),targetZhanGong);
				}
			}
		}

