		__proto.getExpToFullLevelBySoulVo=function(vo){
			if(!vo)return 0;
			var propertyId=this.getTreasureDicObj(vo.gemInfo.gemId)["glass_pearl_Attribute"];
			var clientDataProxy=this.context.model.getProxy(ClientDataProxy);
			var spiritList=[];
			var obj;
			/*for each*/for(var $each_obj in clientDataProxy.marsTreasureDic){
				obj=clientDataProxy.marsTreasureDic[$each_obj];
				if(propertyId==obj["glass_pearl_Attribute"]&&vo.quality==obj["glass_pearl_Quality"])spiritList.push(obj);
			}
			spiritList.sortOn("id",Array.NUMERIC);
			var spiritId=0,exp=0;
			var $each_obj;
			/*for each*/for($each_obj in spiritList){
				obj=spiritList[$each_obj];
				if(obj["glass_pearl_lv"] !=1){
					exp=int(obj["glass_pearl_Exp"]);
				}
			}
			return exp-vo.gemInfo.gemExp;
		}

		__proto.getTreasureNeedExp=function(propertyId,quality,startLv,endLv){
			var clientDataProxy=this.context.model.getProxy(ClientDataProxy);
			var spiritList=[];
			var obj;
			/*for each*/for(var $each_obj in clientDataProxy.marsTreasureDic){
				obj=clientDataProxy.marsTreasureDic[$each_obj];
				if(propertyId==obj["glass_pearl_Attribute"]&&quality==obj["glass_pearl_Quality"])spiritList.push(obj);
			}
			spiritList.sortOn("id",Array.NUMERIC);
			var exp=0;
			for(var i=0;i < spiritList.length;i++){
				var gemInfo=spiritList[i];
				var gemExp=int(gemInfo["glass_pearl_Exp"]);
				var gemLv=int(gemInfo["glass_pearl_lv"]);
				var remainExp=exp-gemExp;
				if(startLv <=gemLv && gemLv <=endLv){
					exp=exp+gemExp;
				}
			}
			return exp;
		}

		__proto.getTreasureIdByExp=function(propertyId,quality,exp,gemCurLv){
			var clientDataProxy=this.context.model.getProxy(ClientDataProxy);
			var spiritList=[];
			var obj;
			/*for each*/for(var $each_obj in clientDataProxy.marsTreasureDic){
				obj=clientDataProxy.marsTreasureDic[$each_obj];
				if(propertyId==obj["glass_pearl_Attribute"]&&quality==obj["glass_pearl_Quality"])spiritList.push(obj);
			}
			spiritList.sortOn("id",Array.NUMERIC);
			var spiritId=0;
			var $each_obj;
			/*for each*/for($each_obj in spiritList){
				obj=spiritList[$each_obj];
				if(exp<int(obj["glass_pearl_Exp"])){
					spiritId=obj["id"];
					break ;
				}
			}
			if(exp>=int(spiritList[spiritList.length-1]["glass_pearl_Exp"])){
				spiritId=spiritList[spiritList.length-1]["id"];
				return spiritId;
			}
			return spiritId%100<=1?spiritId:spiritId-1;
		}

