			if(vo){
				var gemRenderVO2;
				/*for each*/for(var $each_gemRenderVO2 in this.unicornBeans){
					gemRenderVO2=this.unicornBeans[$each_gemRenderVO2];
					if(batch&&this.selectExp<this.totalExp){
						gemRenderVO2.select=true;
						this.selectExp+=int(gemRenderVO2.gemInfo.gemExp);
						if(this.soulMons.indexOf(gemRenderVO2.gemInfo.gemRealId)==-1)this.soulMons.push(gemRenderVO2.gemInfo.gemRealId);
					}
				}
			}
