		__proto.sortOn=function(a,b){
			if(a.rankId > b.rankId){
				return-1;
			}
			else if(a.rankId < b.rankId){
				return 1;
			}
			else{
				if(a.quality > b.quality){
					return 1;
				}
				else if(a.quality < b.quality){
					return-1;
				}
				return 0;
			}
		}

