			var gemObj=this.marsProxy.getTreasureDicObj(this.mixItem.gemInfo.gemId)
			var propertyId=int(gemObj["glass_pearl_Attribute"]);
			var targetLv=int(gemObj["glass_pearl_lv"])
			var unicornSoulId=this.marsProxy.getTreasureIdByExp(propertyId,this.mixItem.quality,this.mixItem.gemInfo.gemExp+addExp,targetLv);
			this.setSoulPercent(unicornSoulId,this.mixItem.gemInfo.gemExp,addExp);
			this.panel.soulMonInfoContentLabel.htmlText=this.marsProxy.getTreasureEffectTipsInfo(unicornSoulId);
