		__proto.getTips=function(itemVO,num){
			(num===void 0)&& (num=1);
			var flagProxy=this.getProxy(FlagProxy1);
			switch (itemVO.itemInfoVO.itemType){
				case /*utils.Contants.ITEM_TYPE_EQUIP*/1:{
						var eVO=ObjectPool.borrow(EquipVO);
						eVO.id=itemVO.id;
						eVO.level=1;
						var equipTipVO=ObjectPool.borrow(EquipTipVO);
						equipTipVO.displayParts=false;
						equipTipVO.equipVO=eVO;
						return equipTipVO;
					}
				case /*utils.Contants.ITEM_TYPE_FLAG*/3:{
						var obj=new Object();
						obj["id"]=itemVO.id;
						obj["name"]=itemVO.itemInfoVO.name;
						obj["Effect_Ex"]=flagProxy.getEffectEX(itemVO.id);
						obj["item_price"]=itemVO.itemInfoVO.buyGoldPrice;
						obj["quality"]=itemVO.itemInfoVO.quality;
						obj["iconId"]="";
						var flagTipsVO=ObjectPool.borrow(FlagTipsVO1);
						flagTipsVO.update(obj);
						var level=ClientDataProxy.getClientDataProxy().flagInfo[itemVO.id][["flag_lvl"]];
						flagTipsVO.updateSpecial(level+"");
						return flagTipsVO;
					}
				case /*utils.Contants.ITEM_TYPE_ITEM*/2:
				case /*utils.Contants.ITEM_TYPE_YUSHI*/6:
				case /*utils.Contants.ITEM_TYPE_JINGYINGSHU*/7:
				case /*utils.Contants.ITEM_TYPE_STONE*/4:{
						return TipUtil.getTextTipVO(LanguageRunner.getLanguageText(itemVO.itemInfoVO.name));
					}
				case /*utils.Contants.ITEM_TYPE_CURRENCY*/10:{
						return TipUtil.getTextTipVO(num+" "+LanguageRunner.getLanguageText(itemVO.itemInfoVO.name));
					}
				default :{
						return TipUtil.getTextTipVO(LanguageRunner.getLanguageText(itemVO.itemInfoVO.name));
					}
				}
		}

