		__proto.receiveRewardsInfoGC=function(note){
			this.missionPanel.btnchallengeAtOnceFinsh.enabled=true;
			var vo=note.body;
			var proxy=this.context.model.getProxy(ItemProxy);
			if(vo.type==2){
				if(this.rollRewardPanel!=null&&this.rollRewardPanel.isOpen){
					this.rollRewardPanel.rewardList=vo.rewards;
					this.updateRollPanel(vo,proxy);
					this.rollRewardPanel.choosetype=vo.type;
					LayerRunner.panelLayer.setChildIndex(this.rollRewardPanel,(LayerRunner.panelLayer.numChildren-1));
					}else{
					if(this.rollRewardPanel==null){
						this.openRollPanel(vo,proxy);
						}else{
						if(this.rollRewardPanel.countCancelNum(vo)!=4){
							this.openRollPanel(vo,proxy);
						}
					}
				}
			}
		}

		__proto.openRollPanel=function(vo,proxy){
			this.rollRewardPanel=new RollRewardPanel(vo,proxy);
			this.rollRewardPanel.x=this.missionPanel.x;
			this.rollRewardPanel.y=this.missionPanel.y+50;
			this.rollRewardPanel.closeFunction=iflash.method.bind(this,this.closeRollRewardPanel);
			this.rollRewardPanel.closeRemoveFunction=iflash.method.bind(this,this.closeRemoveFunction);
			this.mask=MaskUtil.setColorRectMask(LayerRunner.panelLayer,0,0,/*core.runner.StageRunner.stageWidth*/1000,/*core.runner.StageRunner.stageHeight*/600);
			this.rollRewardPanel.open(LayerRunner.panelLayer);
			this.rollRewardPanel.choosetype=vo.type;
		}

		__proto.closeRollRewardPanel=function(){
			this.rollRewardPanel.close();
			this.rollRewardPanel=null;
		}

		__proto.closeRemoveFunction=function(){
			if(LayerRunner.panelLayer.contains(this.mask)){
				LayerRunner.panelLayer.removeChild(this.mask);
			}
		}

		__proto.updateRollPanel=function(vo,proxy){
			if(this.rollRewardPanel.sendSelect){
				var idex=int(this.rollRewardPanel.selectIndex);
				this.rollRewardPanel.showSelect(vo.rewards,idex,proxy);
				}else{
				this.rollRewardPanel.numUse.visible=true;
				for (var i=0;i<vo.rewards.length;i++){
					var tbean=vo.rewards [i];
					this.rollRewardPanel.updateButtonContainer(i,tbean.stat);
					this.rollRewardPanel.updateCardContainer(i,tbean.stat);
				}
				this.rollRewardPanel.numUse.text=vo.expend+"";
			}
		}

		__proto.showDedault=function(rewardList){
			var arr;
			/*for each*/for(var $each_arr in rewardList){
				arr=rewardList[$each_arr];
				var vo=arr [0];
				var star=vo.starLevel;
				this.showStarContainer(arr,star);
			}
		}

		__proto.showStarContainer=function(arr,star){
			var lebel=this.getSarLabel(star);
			switch(star){
				case 5:
					this.missionPanel.oneStarContainer.addChild(lebel);
					this.initStarContainer(arr,this.missionPanel.oneStarContainer);
					break ;
				case 6:
					this.missionPanel.twoStarContainer.addChild(lebel);
					this.initStarContainer(arr,this.missionPanel.twoStarContainer);
					this.missionPanel.twoStarContainer.y=this.missionPanel.oneStarContainer.y+this.missionPanel.oneStarContainer.height+10;
					break ;
				case 7:
					this.missionPanel.threeStarContainer.addChild(lebel);
					this.initStarContainer(arr,this.missionPanel.threeStarContainer);
					this.missionPanel.threeStarContainer.y=this.missionPanel.twoStarContainer.y+this.missionPanel.twoStarContainer.height+10;
					break ;
				case 8:
					this.missionPanel.fourStarContainer.addChild(lebel);
					this.initStarContainer(arr,this.missionPanel.fourStarContainer);
					this.missionPanel.fourStarContainer.y=this.missionPanel.threeStarContainer.y+this.missionPanel.threeStarContainer.height+10;
					break ;
				case 9:
					this.missionPanel.fiveStarContainer.addChild(lebel);
					this.initStarContainer(arr,this.missionPanel.fiveStarContainer);
					this.missionPanel.fiveStarContainer.y=this.missionPanel.fourStarContainer.y+this.missionPanel.fourStarContainer.height+10;
					break ;
				case 10:
					this.missionPanel.sixStarContainer.addChild(lebel);
					this.initStarContainer(arr,this.missionPanel.sixStarContainer);
					var l=ObjectPool.borrow(Label);
					l.y=this.missionPanel.sixStarContainer.height;
					this.missionPanel.sixStarContainer.addChild(l);
					this.missionPanel.sixStarContainer.y=this.missionPanel.fiveStarContainer.y+this.missionPanel.fiveStarContainer.height+10;
					break ;
				}
		}

		__proto.getSarLabel=function(star){
			var lebel=new PanelLabel();
			lebel.htmlText="<b>"+star+LanguageRunner.getLanguageText("MISSIONPANELACTIVITYSTAR")+"</b>"
			lebel.x=10;
			lebel.y=-18;
			return lebel;
		}

		__proto.initStarContainer=function(arr,container){
			if(arr==null)return;
			var len=arr.length;
			var list=[];
			for(var j=0;j<len;j++){
				var rewardVO=arr [j];
				var itemrewardLabel=new BGAttributeTextField();
				itemrewardLabel.width=128;
				itemrewardLabel.htmlText=ColorUtil.getFontColorHtmlString(this.addPixForName(rewardVO.itemInfo),EquipUtil.getEquipQualityHTMLColorByID(rewardVO.itemInfo.quality));
				container.addChild(itemrewardLabel);
				list.push(itemrewardLabel);
			}
			LayoutUtil.layout(new ListIterator(list),new RectangleLayoutBehavior(3,132,20),20,4);
		}

		__proto.addPixForName=function(item){
			var name=item.name;
			if(item.id==305105085||item.id==305106036){
				name=item.name+"("+LanguageRunner.getLanguageText("MISSIONPANELACTIVITYMEDIATOR_PIFENG")+")";
			}
			if(item.id==304105085||item.id==304106036){
				name=item.name+"("+LanguageRunner.getLanguageText("MISSIONPANELACTIVITYMEDIATOR_KUIJIA")+")";
			}
			if(item.id==301105085||item.id==301106036){
				name=item.name+"("+LanguageRunner.getLanguageText("MISSIONPANELACTIVITYMEDIATOR_WUQI")+")";
			}
			if(item.id==303105085||item.id==303106036){
				name=item.name+"("+LanguageRunner.getLanguageText("MISSIONPANELACTIVITYMEDIATOR_ZUOQI")+")";
			}
			return name;
		}

		MissionPanelActivityMediator.REWARITEM_INFO_VIEW="rewarItemInfoView";
		return MissionPanelActivityMediator;
