			this.missionPanel.txtDayName.text=this.currentMissionDayInfoVO.title;
			this.missionPanel.txtDayLevelStar.text=MissionUtil.getStarByNum(this.currentMissionDayInfoVO.levelStar);
			this.missionPanel.txtDayTarget.text=this.currentMissionDayInfoVO.target;
			this.missionPanel.txtDayDesc.text=this.currentMissionDayInfoVO.desc;
			this.missionPanel.txtDayFinshNum.text=String(this.currentMissionDayInfoVO.times)+"/"+String(this.currentMissionDayInfoVO.maxTimes);
