	//file:///e:/work/sgwork/h5sg2/sg4/src/functions/panel/controller/openpanelorder.as
	//class functions.panel.controller.OpenPanelOrder extends core.patterns.command.SimpleOrder
	var OpenPanelOrder=(function(_super){
		function OpenPanelOrder(){
			this.notification=null;
			OpenPanelOrder.__super.call(this);
		}

		__class(OpenPanelOrder,'functions.panel.controller.OpenPanelOrder',false,_super);
		var __proto=OpenPanelOrder.prototype;
		__proto.execute=function(note){
			_super.prototype.execute.call(this,note);
			var panelManager=Managers.panelManager;
			var panelID=int(note.body);
			var args=note.args;
			console.log("panelID============"+panelID);
			if(args !=null && args.length > 0){
				for(var i=0;i < args.length;i++){
					console.log("i="+i+"="+args[i]);
				}
			}
			if(Managers.panelManager.campainTeamPanelIsOpen && panelID !=/*functions.panel.model.PanelType.CAMPAINTEAM_PANEL*/59){
				this.notification=note;
				Managers.panelManager.closeCampainTeamPanelCallback=iflash.method.bind(this,this.closeCampainTeamPanelCallback);
				this.sendNotification(/*global.NotificationType.CLOSE_PANEL*/"closePanel",/*functions.panel.model.PanelType.CAMPAINTEAM_PANEL*/59);
				return;
			}
			else{
				this.notification=null;
			};
			var mediator=panelManager.getPanel(panelID);
			mediator.update(note.type);
			if (args !=null && args.length > 0){
				var switchTabMediator=mediator;
				if (switchTabMediator !=null){
					switchTabMediator.initSwitchTab=args[0];
				}
			}
			if (args !=null && args.length > 1){
				panelManager.open(panelID,args[1]);
				}else {
				panelManager.open(panelID);
			}
			Server.sendLocalConnection("Open panel's ID is : "+panelID);
			this.sendNotification(/*global.NotificationType.GUIDE_STEP_CONDITION*/"guideStepConditon",/*functions.guide.model.GuideConditionType.PanelOpen*/3,panelID,args);
		}

		__proto.closeCampainTeamPanelCallback=function(){
			if(this.notification){
				this.execute(this.notification);
				this.notification=null;
			}
		}

		return OpenPanelOrder;
	})(SimpleOrder)


	//file:///e:/work/sgwork/h5sg2/sg4/src/functions/power/controller/disposepowereventorder.as
	//class functions.power.controller.DisposePowerEventOrder extends core.patterns.command.SimpleOrder
	var DisposePowerEventOrder=(function(_super){
		function DisposePowerEventOrder(){
			this.splitStr="|";
			DisposePowerEventOrder.__super.call(this);
		}

		__class(DisposePowerEventOrder,'functions.power.controller.DisposePowerEventOrder',false,_super);
		var __proto=DisposePowerEventOrder.prototype;
		__proto.execute=function(note){
			_super.prototype.execute.call(this,note);
			var etVO=note.body;
			var eventId=etVO.eventId;
			var powerId=etVO.powerId;
			this.dispose(eventId,powerId);
		}

		__proto.dispose=function(eventId,powerId){
			var powerProxy=this.getProxy(PowerProxy);
			var eventInfoVO=powerProxy.getPowerEventData(powerId,eventId);
			if(eventInfoVO!=null){
				var typeId=eventInfoVO.typeID;
				var afterEvent=eventInfoVO.to;
				if(EventType.CLIENTTYPELIST.indexOf(typeId)>=0){
					switch(typeId){
						case /*functions.power.model.EventType.TALK*/1:;
							var talkInfoVO=new TalkInfoVO();
							talkInfoVO.showInfo=eventInfoVO.eventtext;
							var talkArray=eventInfoVO.eventlog.split(this.splitStr);
							if(talkArray.length==2){
								talkInfoVO.showPos=int(talkArray[0]);
								var elementId=int(talkArray[1]);
								talkInfoVO.elementId=elementId;
								var elementInfoVO=powerProxy.getPowerElementData(powerId,elementId);
								if(elementInfoVO!=null){
									talkInfoVO.showPic=elementInfoVO.pic2;
									talkInfoVO.showName=elementInfoVO.obname;
								}
								talkInfoVO.afterEventId=afterEvent;
								talkInfoVO.powerId=powerId;
								this.sendNotification(/*global.NotificationType.SHOW_ELEMENT_TALK*/"showElementTalk",elementId);
								this.sendNotification(/*global.NotificationType.REFRESH_TALK*/"refreshTalk",talkInfoVO);
							}
							break ;
						case /*functions.power.model.EventType.SHOW_PIC*/2:;
							var picInfoVO=new PicInfoVO();
							picInfoVO.afterEventId=afterEvent;
							picInfoVO.powerId=powerId;
							picInfoVO.showPic=eventInfoVO.eventlog;
							this.sendNotification(/*global.NotificationType.REFRESH_PIC*/"refreshPic",picInfoVO);
							break ;
						case /*functions.power.model.EventType.SHINE_ELEMENT*/12:;
							var shineElementVO=new ShineElementVO();
							shineElementVO.afterEventId=afterEvent;
							shineElementVO.elementIds=eventInfoVO.eventlog.split(";");
							this.sendNotification(/*global.NotificationType.SHINE_POWER_ELEMENT*/"shinePowerElement",shineElementVO);
							break ;
						}
					return;
				}
				if(EventType.SERVERTYPELIST.indexOf(typeId)>=0){
					powerProxy.triggerServerEvent(eventId,powerId);
				}
			}
		}

		return DisposePowerEventOrder;
	})(SimpleOrder)


