		__proto.sendOneKeyGrow=function(){
			this.sendNotification(/*functions.practiseSoldier.controller.PractiseSoldierMainOrder.NAME*/"practiseSoldierMainOrder",2,/*global.NotificationType.GROW_SOLDIER_POWER*/"grow_soldier_power");
			this.sendNotification(/*global.NotificationType.SENIOR_PASSWORD_CONFIRM_PWD_AFTER_MSG*/"SENIOR_PASSWORD_CONFIRM_PWD_AFTER_MSG",null,[ /*global.NotificationType.SENIOR_PASSWORD_SEND_ONE_KEY_GROW_AFTER*/"SENIOR_PASSWORD_SEND_ONE_KEY_GROW_AFTER"]);
		}

		__proto.sendOneKeyGrowAfter=function(note){
			var _$this=this;
			this.isGrowSoldier=true;
			if(this.practiseSoldierView.checkBoxOutoHarvest.selected){
				this.practiseSoldierView.checkBoxOutoHarvest.mouseEnabled=false;
				TweenLite.delayedCall(1.5,function(){
					if(_$this.practiseSoldierView.checkBoxOutoHarvest.selected){
						_$this.isHarvestClick=true;
						_$this.sendHarvest();
					}
					_$this.practiseSoldierView.checkBoxOutoHarvest.mouseEnabled=true;
				});
				this.isHarvestClick=false;
				}else{
				this.isHarvestClick=true;
			}
			this.playGrowMc(2);
		}

		__proto.playGrowMc=function(effectType){
			this.practiseSoldierView.stopMovePowerPanel();
			var vec=this.practiseSoldierView.soldierHeapList.itemArr;
			var item;
			/*for each*/for(var $each_item in vec){
				item=vec[$each_item];
				item.playHeap(effectType);
			}
			this.practiseSoldierView.generalEnimation.playAnimation();
		}

