		__proto.onGoldResponse=function(note){
			var vo=note.body;
			this.updateGoldNumTxt(vo.gold);
		}

		__proto.onAirPowerResponse=function(note){
			var value=note.body;
			this.updateAirPowerNum(value);
		}

		__proto.onSoldierPowerResponse=function(note){
			var value=note.body;
			this.updateSoldierPowerNum(value);
		}

		__proto.onPractiseSoldierDataResponse=function(note){
			this.practiseMsg=note.body;
			this.updateSomeMoney();
			this.updateMainSoldiers(this.practiseMsg.list);
			this.updatePractiseBtns(this.practiseMsg);
			if(this.isAllPowerToMax(this.practiseMsg.list)){
				this.isGrowSoldier=true;
			}
		}

		__proto.updateSomeMoney=function(){
			var roleProxy=this.getProxy(RoleProxy);
			this.roleVo=roleProxy.roleVO;
			this.updateGoldNumTxt(this.roleVo.gold);
			this.updateAirPowerNum(this.roleVo.airPower.toString());
			this.updateSoldierPowerNum(this.roleVo.soldierPower.toString());
		}

		__proto.updateGoldNumTxt=function(num){
			if(this.practiseSoldierView.goldNum){
				this.practiseSoldierView.goldNum.text=num;
			}
		}

		__proto.updateAirPowerNum=function(airNum){
			if(this.practiseSoldierView.airPowerNum){
				if(this.practiseSoldierView.airPowerNum.text!=airNum){
					this.haveChange(this.practiseSoldierView.airPowerNum,airNum);
				}
			}
		}

		__proto.updateSoldierPowerNum=function(soldierNum){
			if(this.practiseSoldierView.soldierPowerNum){
				if(this.practiseSoldierView.soldierPowerNum.text!=soldierNum){
					this.haveChange(this.practiseSoldierView.soldierPowerNum,soldierNum);
				};
				var tipTxt;
				if(int(soldierNum)>=this.xlsVo.exchangeValue){
					this.practiseSoldierView.exchangeBtn.enabled=true;
					tipTxt=LanguageRunner.getLanguageText("EXCHANGE_BTN_TIP");
					this.practiseSoldierView.exchangeBtn.toolTip=TipUtil.getTextTipVO(StringUtil1.format(tipTxt,this.xlsVo.exchangeValue));
					}else{
					this.practiseSoldierView.exchangeBtn.enabled=false;
					tipTxt=LanguageRunner.getLanguageText("NOT_ENOUGH_POWER_TO_EXCHANGE");
					this.practiseSoldierView.exchangeBtn.toolTip=TipUtil.getTextTipVO(StringUtil1.format(tipTxt,this.xlsVo.exchangeValue));
				}
			}
		}

		__proto.haveChange=function(dis,value){
			TweenMax.killTweensOf(dis,true);
			var old=dis.filters;
			TweenMax.to(dis,2,{glowFilter:{color:0x91e600,alpha:1,blurX:3,blurY:3,remove:true},onComplete:function (){
					dis.filters=old;
					dis.htmlText=value;
			}});
		}

		__proto.updateMainSoldiers=function(list){
			var data=[];
			for(var i=0;i<this.xlsVo.heapNum;i++){
				var item=ObjectPool.borrow(SoldierItemRenderVO);
				if(list.length>i){
					var info=list[i];
					item.powerType=info.type;
					item.powerNum=info.value;
					}else{
					item.powerType=-1;
					item.powerNum=0;
				}
				item.xlsVo=this.xlsVo;
				data.push(item);
			}
			this.practiseSoldierView.soldierHeapList.clear();
			this.practiseSoldierView.soldierHeapList.updateItems(data);
		}

		__proto.updatePractiseBtns=function(msg){
			var list=msg.list;
			if(msg.remaiGoldPick>0){
				this._updateGrowSoldierParts(msg);
				this._updateHarvestSoldierParts(msg);
				}else{
				this.cannotPickUp();
			}
			this.calculateCurrentPowr(list);
		}

		__proto.cannotPickUp=function(){
			this.practiseSoldierView.freeGrowBtn.enabled=false;
			this.practiseSoldierView.freeGrowBtn.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("PICK_UP_TO_LEVEL_UP_CANNOT_GROW"));
			this.practiseSoldierView.goldGrowBtn.enabled=false;
			this.practiseSoldierView.goldGrowBtn.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("PICK_UP_TO_LEVEL_UP_CANNOT_GROW"));
			this.practiseSoldierView.oneKeyGrowBtn.enabled=false;
			this.practiseSoldierView.oneKeyGrowBtn.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("PICK_UP_TO_LEVEL_UP_CANNOT_GROW"));
			this.practiseSoldierView.harvestBtn.enabled=false;
			this.practiseSoldierView.harvestBtn.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("PICK_UP_TO_LEVEL_UP"));
			this.practiseSoldierView.remainHarvestTimes.text=StringUtil1.format(LanguageRunner.getLanguageText("RMAIN_COLLECT_TIMES"),this.practiseMsg.remaiGoldPick);
		}

		__proto._updateHarvestSoldierParts=function(msg){
			if(this.isHarvestClick==false){
				this.practiseSoldierView.harvestBtn.enabled=false;
				this.practiseSoldierView.harvestBtn.toolTip=null;
				}else if(msg.remaiYanwu==0){
				if(int(this.roleVo.gold)>=msg.costYanwu){
					this.practiseSoldierView.harvestBtn.enabled=true;
					this.practiseSoldierView.harvestBtn.toolTip=TipUtil.getTextTipVO(StringUtil1.format(LanguageRunner.getLanguageText("COST_GOLD_TO_PICK_UP_POWER"),msg.costYanwu));
					this.practiseSoldierView.checkBoxOutoHarvest.enabled=true;
					}else{
					this.practiseSoldierView.harvestBtn.enabled=false;
					this.practiseSoldierView.harvestBtn.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("NOT_ENOUGH_GOLD_TO_HARVEST"));
					this.practiseSoldierView.checkBoxOutoHarvest.selected=false;
					this.practiseSoldierView.checkBoxOutoHarvest.enabled=false;
				}
				this.practiseSoldierView.harvestDesc.text=StringUtil1.format(LanguageRunner.getLanguageText("COST_SOME_COLD"),msg.costYanwu);
				this.practiseSoldierView.autoHarvestCost.text=StringUtil1.format(LanguageRunner.getLanguageText("COST_SOME_COLD"),msg.costYanwu);
				var checkBoxAutoHarvestTip=StringUtil1.format(LanguageRunner.getLanguageText("PICK_UP_ALL_SOLDIER_POWER"),msg.costYanwu);
				this.practiseSoldierView.checkBoxOutoHarvest.toolTip=TipUtil.getTextTipVO(checkBoxAutoHarvestTip);
				this.practiseSoldierView.remainHarvestTimes.visible=true;
				this.practiseSoldierView.remainHarvestTimes.text=StringUtil1.format(LanguageRunner.getLanguageText("RMAIN_COLLECT_TIMES"),msg.remaiGoldPick);
				}else{
				this.practiseSoldierView.harvestBtn.enabled=true;
				this.practiseSoldierView.harvestBtn.toolTip=null;
				this.practiseSoldierView.harvestDesc.text=LanguageRunner.getLanguageText("REMAIN_FREE_TIMES")+msg.remaiYanwu;
				this.practiseSoldierView.checkBoxOutoHarvest.enabled=true;
				this.practiseSoldierView.autoHarvestCost.text=LanguageRunner.getLanguageText("REMAIN_FREE_TIMES")+msg.remaiYanwu;
				this.practiseSoldierView.checkBoxOutoHarvest.toolTip=null;
				this.practiseSoldierView.remainHarvestTimes.visible=false;
			}
			this.practiseSoldierView.harvestDesc.x=this.practiseSoldierView.harvestBtn.x+(130-this.practiseSoldierView.harvestDesc.textWidth)/2;
		}

		__proto.calculateCurrentPowr=function(list){
			var airNum=0;
			var currentSoldierPower=0;
			var currentAirPower=0;
			for(var i=0;i<list.length;i++){
				var item=list[i];
				if(item.type==1){
					airNum++;
					currentAirPower+=item.value;
					}else{
					currentSoldierPower+=item.value;
				}
			};
			var soldierPowerTxt="<font color='#FFFF00'>"+currentSoldierPower+"</font>/"+(this.xlsVo.heapNum-airNum)*this.xlsVo.powerMax;
			var airPowerTxt="<font color='#FFFF00'>"+currentAirPower+"</font>/"+airNum*this.xlsVo.powerMax;
			this.practiseSoldierView.soldierPower.htmlText=LanguageRunner.getLanguageText("CALCULATE_POWER")+soldierPowerTxt;
			this.practiseSoldierView.airPower.htmlText=LanguageRunner.getLanguageText("CALCULATE_POWER")+airPowerTxt;
			var soldierpowerTxt=StringUtil1.format(LanguageRunner.getLanguageText("CURRENT_SOLDIER_HEART_TIP"),currentSoldierPower,(this.xlsVo.heapNum-airNum)*this.xlsVo.powerMax);
			this.practiseSoldierView.soldierCalContainer.toolTip=TipUtil.getTextTipVO(soldierpowerTxt);
			var airpowerTxt=StringUtil1.format(LanguageRunner.getLanguageText("CURRENT_SOLDIER_POWER_TIP"),currentAirPower,airNum*this.xlsVo.powerMax);
			this.practiseSoldierView.airCalContainer.toolTip=TipUtil.getTextTipVO(airpowerTxt);
		}

		__proto._updateGrowSoldierParts=function(msg){
			if(this.isAllPowerToMax(msg.list)){
				this.practiseSoldierView.freeGrowBtn.enabled=false;
				this.practiseSoldierView.freeGrowBtn.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("POWER_TO_MAX_CANT_FREE_GROW"));
				}else{
				this.practiseSoldierView.freeGrowBtn.enabled=true;
				var freeGrowTip=StringUtil1.format(LanguageRunner.getLanguageText("FREE_GROW_PRACTISE_TIP"),this.xlsVo.powerMax);
				this.practiseSoldierView.freeGrowBtn.toolTip=TipUtil.getTextTipVO(freeGrowTip);
			}
			if(int(this.roleVo.gold)>=msg.costGrow){
				if(this.isAllPowerToMax(msg.list)){
					this.practiseSoldierView.goldGrowBtn.enabled=false;
					this.practiseSoldierView.goldGrowBtn.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("CAN_NOT_USE_GOLD_TO_GROW"));
					}else{
					this.practiseSoldierView.goldGrowBtn.enabled=true;
					var tipTxt=StringUtil1.format(LanguageRunner.getLanguageText("COST_GOLD_TO_GROW"),this.xlsVo.powerMax);
					this.practiseSoldierView.goldGrowBtn.toolTip=TipUtil.getTextTipVO(tipTxt);
				}
				}else{
				this.practiseSoldierView.goldGrowBtn.enabled=false;
				this.practiseSoldierView.goldGrowBtn.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("NOT_ENOUGH_GOLD_TO_GROW"));
			}
			if(int(this.roleVo.gold)>=msg.oneGrow){
				if(this.isAllPowerToMax(msg.list)){
					this.practiseSoldierView.oneKeyGrowBtn.enabled=false;
					this.practiseSoldierView.oneKeyGrowBtn.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("CAN_NOT_USE_GOLD_TO_ONE_KEY_GROW"));
					}else{
					this.practiseSoldierView.oneKeyGrowBtn.enabled=true;
					var oneKeyTipText=StringUtil1.format(LanguageRunner.getLanguageText("LEVELUP_SOLDIER_POWER_TO"),this.xlsVo.powerMax,this.xlsVo.powerMax*this.xlsVo.heapNum);
					this.practiseSoldierView.oneKeyGrowBtn.toolTip=TipUtil.getTextTipVO(oneKeyTipText);
				}
				}else{
				this.practiseSoldierView.oneKeyGrowBtn.enabled=false;
				this.practiseSoldierView.oneKeyGrowBtn.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("NOT_ENOUGH_GOLD_TO_ONE_KEY_GROW"));
			}
			this.practiseSoldierView.costGrowGold.text=LanguageRunner.getLanguageText("DIAL_NEED_GOLD")+msg.costGrow;
			this.costGrowOneKeyTxt(this.practiseSoldierView.checkBoxOutoHarvest.selected);
		}

		__proto.isAllPowerToMax=function(list){
			var result=false;
			var i=0;
			for(i=0;i<list.length;i++){
				var item=list[i];
				if(item.value<this.xlsVo.powerMax){
					break ;
				}
			}
			if(i==this.xlsVo.heapNum){
				result=true;
				}else{
				result=false;
			}
			return result;
		}

