		__proto.onReceiveTargetMissionState=function(noti){
			if(this.enterFrameTimer !=null){
				this.enterFrameTimer.stop();
			};
			var msg=noti.body;
			var targetProxy=this.getProxy(TargetProxy);
			if(this.questList){
				ObjectUtil.clearList(this.questList);
			}
			else{
				this.questList=ObjectPool.borrow(Array);
			}
			var obj;
			/*for each*/for(var $each_obj in msg.questList){
				obj=msg.questList[$each_obj];
				var targetVO=targetProxy.getOneTargetInfo(obj.questId);
				if(targetVO==null){
					continue ;
				}
				targetVO.questStatus=obj.questStatus;
				this.questList.push(targetVO);
			}
			if(this.questList.length > 0){
				if(this.enterFrameTimer==null){
					this.enterFrameTimer=new EnterFrameTimer(4000);
					this.enterFrameTimer.timerHandler=iflash.method.bind(this,this.frameHandler);
				}
				this.enterFrameTimer.start();
				this.roleInfoFrame.targetItemView.visible=true;
				this.roleInfoFrame.targetTitleLinghting.visible=true;
				this.roleInfoFrame.btnRewardEntry.visible=true;
				if(!this.roleInfoFrame.btnRewardEntry.hasEventListener(/*iflash.events.MouseEvent.CLICK*/"click")){
					this.roleInfoFrame.btnRewardEntry.addEventListener(/*iflash.events.MouseEvent.CLICK*/"click",__bind(this,this.clickItemCallBack));
				}
				this.targetIndex=-1;
				this.showQuestItemInfo();
			}
			else{
				this.roleInfoFrame.targetItemView.visible=false;
				this.roleInfoFrame.targetTitleLinghting.visible=false;
				this.roleInfoFrame.btnRewardEntry.visible=false;
				this.stopTargetTitleLighting(null);
				this.roleInfoFrame.btnRewardEntry.removeEventListener(/*iflash.events.MouseEvent.CLICK*/"click",__bind(this,this.clickItemCallBack));
			}
		}

