		__proto.checkTime=function(){
			var timeCur=ServerTimeUitl.getInstance().getServerTimestamp();
			var strongholdProxy=this.getProxy(StrongholdProxy);
			var myForces="";
			if(strongholdProxy.myForces==1){
				myForces=LanguageRunner.getLanguageText("WEI");
			}
			else if(strongholdProxy.myForces==2){
				myForces=LanguageRunner.getLanguageText("SHU");
			}
			else if(strongholdProxy.myForces==3){
				myForces=LanguageRunner.getLanguageText("WU");
			}
			if (timeCur < this.timeStart){
				this.panel.txtStrongholdCountdown.text=LanguageRunner.getLanguageText("SHW_BISAIKAISHI")+""+StringUtil1.formatTime(this.timeStart-timeCur,"hh:mm:ss",true)+"  "+LanguageRunner.getLanguageText("STRONG_HOLD_FORCE")+myForces;
			}
			else if (timeCur >=this.timeStart && timeCur < this.timeEnd){
				this.panel.txtStrongholdCountdown.text=LanguageRunner.getLanguageText("SHW_BISAIJIESU")+""+StringUtil1.formatTime(this.timeEnd-timeCur,"hh:mm:ss",true)+"  "+LanguageRunner.getLanguageText("STRONG_HOLD_FORCE")+myForces;
			}
			else if (timeCur >=this.timeEnd){
				this.timer.stop();
				var msg=ObjectPool.borrow(RefreshReqMessage);
				var proxy=this.getProxy(RoleProxy);
				msg.roleId=proxy.roleVO.id;
				Server.send(msg);
			}
		}

