	//file:///e:/work/sgwork/h5sg2/sg4/src/functions/union/controller/returnarmydetailorder.as
	//class functions.union.controller.ReturnArmyDetailOrder extends core.patterns.command.SimpleOrder
	var ReturnArmyDetailOrder=(function(_super){
		function ReturnArmyDetailOrder(){
			ReturnArmyDetailOrder.__super.call(this);
		}

		__class(ReturnArmyDetailOrder,'functions.union.controller.ReturnArmyDetailOrder',false,_super);
		var __proto=ReturnArmyDetailOrder.prototype;
		__proto.execute=function(note){
			_super.prototype.execute.call(this,note);
			var message=note.body;
			var unionProxy=this.getProxy(UnionProxy);
			var armyView=ObjectPool.borrow(ArmyDetailVO);
			armyView.armyName=message.armyName;
			armyView.founder=message.founder;
			armyView.shorNameLevel=message.shorNameLevel;
			armyView.armyLevel=message.armyLevel;
			armyView.country=message.country;
			armyView.armySize=message.armySize;
			armyView.memberMaxSize=message.memberMaxSize;
			armyView.foundTime=message.foundTime;
			armyView.modifyIcon=(message.modifyIcon==1?true:false);
			var members=new Dictionary();
			var list;
			var am;
			/*for each*/for(var $each_am in message.army){
				am=message.army[$each_am];
				if(members[am.armyDuty]==null){
					list=new Array;
					var amVO=new ArmyMemberVO();
					amVO.roleName=am.roleName;
					amVO.dutyId=am.armyDuty;
					amVO.colorHtml=EquipUtil.getEquipQualityHTMLColorByID(unionProxy.getDutyQuality(am.armyDuty));
					list.push(amVO);
					members[amVO.dutyId]=list;
					}else{
					list=members[am.armyDuty];
					var amVO1=new ArmyMemberVO();
					amVO1.roleName=am.roleName;
					amVO1.dutyId=am.armyDuty;
					amVO1.colorHtml=EquipUtil.getEquipQualityHTMLColorByID(unionProxy.getDutyQuality(am.armyDuty));
					list.push(amVO1);
				}
			}
			armyView.army=members;
			armyView.selfDuty=message.selfDuty;
			armyView.sendArmyMailSite=(message.sendArmyMailSite==1?true:false);
			armyView.lvUpIcon=message.lvUpIcon;
			armyView.img=unionProxy.getUnionIcon(armyView.shorNameLevel);
			armyView.season=message.season;
			armyView.shorName=message.shorName;
			armyView.iconLv=message.iconLv;
			armyView.gold=message.gold;
			armyView.nextSize=message.nextSize;
			this.sendNotification(/*global.NotificationType.UPDATE_ARMY_DETAIL*/"updateArmyDetail",armyView,note.type);
		}

		return ReturnArmyDetailOrder;
	})(SimpleOrder)


