	//file:///e:/work/sgwork/h5sg2/sg4/src/functions/world/controller/updatecitycanattackorder.as
	//class functions.world.controller.UpdateCityCanAttackOrder extends core.patterns.command.SimpleOrder
	var UpdateCityCanAttackOrder=(function(_super){
		function UpdateCityCanAttackOrder(){
			UpdateCityCanAttackOrder.__super.call(this);
		}

		__class(UpdateCityCanAttackOrder,'functions.world.controller.UpdateCityCanAttackOrder',false,_super);
		var __proto=UpdateCityCanAttackOrder.prototype;
		__proto.execute=function(note){
			_super.prototype.execute.call(this,note);
			var roleInfoProxy=this.getProxy(RoleProxy);
			var worldProxy=this.getProxy(WorldProxy);
			var citys=note.body;
			var currentCityVO=worldProxy.currentOwnCityVO;
			var currentWorldMapVO;
			var city1;
			/*for each*/for(var $each_city1 in citys){
				city1=citys[$each_city1];
				var wmVO=city1.data;
				if (wmVO.realID==currentCityVO.id){
					currentWorldMapVO=wmVO;
					break ;
				}
			}
			if(currentWorldMapVO==null){
				return;
			}
			var city;
			/*for each*/for(var $each_city in citys){
				city=citys[$each_city];
				var worldMapVO=city.data;
				var cityConfigVO=worldProxy.getWorldCityConfig(worldMapVO.realID);
				if(cityConfigVO==null){
					continue ;
				}
				if(worldMapVO.force==0){
					continue ;
				}
				if (currentCityVO.cityRank==cityConfigVO.cityRank && currentWorldMapVO.force !=worldMapVO.force){
					ColorUtil.addColorRing(city,0xDC421E,30,3);
				}
			}
		}

		return UpdateCityCanAttackOrder;
	})(SimpleOrder)


	//file:///e:/work/sgwork/h5sg2/sg4/src/functions/world/controller/updatecitycanmoveinorder.as
	//class functions.world.controller.UpdateCityCanMoveInOrder extends core.patterns.command.SimpleOrder
	var UpdateCityCanMoveInOrder=(function(_super){
		function UpdateCityCanMoveInOrder(){
			UpdateCityCanMoveInOrder.__super.call(this);
		}

		__class(UpdateCityCanMoveInOrder,'functions.world.controller.UpdateCityCanMoveInOrder',false,_super);
		var __proto=UpdateCityCanMoveInOrder.prototype;
		__proto.execute=function(note){
			_super.prototype.execute.call(this,note);
			var roleInfoProxy=this.getProxy(RoleProxy);
			var worldProxy=this.getProxy(WorldProxy);
			var roleLevel=roleInfoProxy.roleVO.level;
			var citys=note.body;
			var currentCityVO=worldProxy.currentOwnCityVO;
			if (roleLevel >=currentCityVO.cityMaxLevel){
				var currentRank=currentCityVO.cityRank;
				var currentWorldMapVO;
				var city;
				/*for each*/for(var $each_city in citys){
					city=citys[$each_city];
					var wmVO=city.data;
					if (wmVO.realID==currentCityVO.id){
						currentWorldMapVO=wmVO;
						break ;
					}
				}
				if(currentWorldMapVO==null){
					return;
				}
				var city1;
				/*for each*/for(var $each_city1 in citys){
					city1=citys[$each_city1];
					var worldMapVO=city1.data;
					if(worldMapVO.force==0){
						continue ;
					}
					if (worldMapVO.force==currentWorldMapVO.force){
						var cityConfigVO=worldProxy.getWorldCityConfig(worldMapVO.realID);
						if(cityConfigVO==null){
							continue ;
						}
						if (cityConfigVO.cityRank==currentRank+1){
							ColorUtil.addColorRing(city1,0x6EBB1D,30,3);
						}
					}
				}
			}
		}

		return UpdateCityCanMoveInOrder;
	})(SimpleOrder)


