						wuHunProxy.updateGeneralRefineStatus(itemRender.itemVO.generalId,0);
						var effectDic=ClientDataProxy.getClientDataProxy().wuHunRefineEffectDic;
						var refineType=ClientDataProxy.getClientDataProxy().wuHunRefineTypeDic;
						itemRender.itemVO.setInitInfo();
