		__proto.changeTime=function(time,tag,showHour){
			(tag===void 0)&& (tag=false);
			(showHour===void 0)&& (showHour=false);
			var date=new Date(time);
			var dayNameNr=(date.getDay());
			var curDay=date.getDate();
			while(dayNameNr < 0){
				dayNameNr+=7;
			};
			var month=date.month+1;
			var year=date.fullYear;
			var hour=date.hours;
			var mins=date.minutes;
			ObjectPool.dispose(date);
			var str;
			if(ConfigConnect.LangType=="vi_VN"){
				str=LanguageRunner.getLanguageText('DATE')+curDay+LanguageRunner.getLanguageText('CROSSWAR_MONTH')+month+LanguageRunner.getLanguageText('YEAR')+year;
			}
			else{
				str=year+LanguageRunner.getLanguageText('YEAR')+month+LanguageRunner.getLanguageText('CROSSWAR_MONTH')+curDay+LanguageRunner.getLanguageText('DATE');
			}
			if(tag){
				str+="    "+this.dayNamesType[dayNameNr];
			}
			if(showHour){
				var h=hour.toString();
				if(hour <10){
					h="0"+h;
				};
				var m=mins.toString();
				if(mins < 10){
					m="0"+m;
				}
				str+=h+":"+m;
			}
			return str;
		}

