		__proto.getZhanPanResult=function(note){
			var msg=note.body;
			if(msg.actId==this.actId){
				if(msg.status !=-1){
					this.zhanPanGetGiftId=msg.status;
					this.startTurnTabel(this.zhanPanGetGiftId,null);
					this.panel.yaerZhiShuText.text=msg.anniversaryPoint;
					this.panel.myYaerZhiShuText.text=msg.anniversaryScore;
				}
			}
		}

		__proto.startTurnTabel=function(selectedItemId,$stopCallBack){
			for(var i=0;i < this.zhuanPanItemVOArr.length;i++){
				var item=this.zhuanPanItemVOArr[i];
				if(int(this.zhuanPanItemArr[i].name)==selectedItemId){
					this.rewardsItemData=item;
					if(this.totalItem !=0 || this.totalItem %this.zhuanPanItemVOArr.length !=0){
						this.itemIndex=this.nextStartIndex;
						this.totalItem=this.zhuanPanItemVOArr.length-this.nextStartIndex+this.zhuanPanItemVOArr.length *(this.cycles-1)+i+1;
					}
					else{
						this.itemIndex=0;
						this.totalItem=this.zhuanPanItemVOArr.length *(this.cycles-1)+i+1;
					}
					this.startIndex=0;
					this.nextStartIndex=i;
					break ;
				}
			}
			this.startTime=iflash.utils.getTimer();
			this.panel.addEventListener(/*iflash.events.Event.ENTER_FRAME*/"enterFrame",__bind(this,this.enterFrameHandler));
		}

		__proto.showZhanPanItem=function(note){
			var msg=note.body;
			this.zhuanPanItemArr=[];
			this.zhuanPanItemVOArr=[];
			var dis=85;
			DisplayUtil.removeAllChildren(this.panel.zhuanPanRwardItemContainer);
			var newVipProxy=this.getProxy(NewVipProxy);
			for(var i=0;i < msg.lotteryList.length;i++){
				var item=new ItemGrid();
				var arr=msg.lotteryList[i].lotteryItemConfig.split(":");
				var realItemArr=arr[1].split("=");
				var itemID=int(arr[0]);
				var itemRealId=0;
				var itemNum=1;
				if(realItemArr.length > 1){
					itemRealId=int(realItemArr[0]);
					itemNum=int(realItemArr[1]);
				}
				else{
					itemNum=int(arr[1]);
				};
				var itemVO=new ItemVO();
				itemVO.id=itemID;
				itemVO.pileNum=itemNum;
				if(itemRealId !=0){
					itemVO=newVipProxy.getRewardItemName(itemVO,itemRealId,itemNum);
				}
				item.update(itemVO);
				item.displayPile=false;
				item.toolTip=TipUtil.getTextTipVO(itemVO.itemInfoVO.name);
				if(itemRealId !=0){
					newVipProxy.getRewardItemTips(item,itemVO,itemRealId);
				}
				this.zhuanPanItemVOArr.push(itemVO);
				item.name=msg.lotteryList[i].lotteryBagId.toString();
				this.panel.zhuanPanRwardItemContainer.addChild(item);
				var _angle=i*(Math.PI/6)-Math.PI/12-Math.PI/2-Math.PI/6;
				var sinAngle=Math.sin(_angle);
				var cosAngle=Math.cos(_angle);
				item.x=145+dis *cosAngle-dis *sinAngle;
				item.y=145+dis *sinAngle+dis *cosAngle;
				var label=new Label();
				label.text=itemNum.toString();
				label.x=item.x;
				label.y=item.y+41;
				label.x=item.x+(52-label.textWidth)*0.5;
				this.panel.zhuanPanRwardItemNumContainer.addChild(label);
				this.zhuanPanItemArr.push(item);
			}
		}

		__proto.getZhanPanItemName=function(str){
			var newVipProxy=this.getProxy(NewVipProxy);
			var itemVO=newVipProxy.getHaveNewVipGiftRewardsArr(str)[0];
			var itemName="";
			if(itemVO.id==/*utils.ItemType.ITEM_TYPE_RANDOM_GIFT*/800026){
				itemName=itemVO.childDes;
			}
			else{
				itemName=itemVO.itemInfoVO.name;
			}
			return itemName;
		}

		__proto.getBaseInfo=function(note){
			var msg=note.body;
			var param=ClientDataProxy.getClientDataProxy().zhuanPanParamDic;
			if(int(param[1].zhuanpan_lottery_integral)> int(msg.anniversaryScore)){
				this.panel.zhuanPanBtn.enabled=false;
				this.panel.zhuanPanBtn.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("YAO_JIANG_JI_FEN_NOT_ENOUGH"));
			}
			else{
				this.panel.zhuanPanBtn.enabled=true;
				this.panel.zhuanPanBtn.toolTip=null;
			}
			this.panel.myYaerZhiShuText.text=msg.anniversaryScore;
			this.panel.myYearLabel.x=this.panel.myYearTextBg.x+(138-this.panel.myYaerZhiShuText.textWidth+20)*0.5-20;
			this.panel.myYaerZhiShuText.x=this.panel.myYearLabel.x+35;
			this.panel.yaerZhiShuText.text=msg.anniversaryPoint;
			this.panel.yearLabel.x=this.panel.yearTextBg.x+(254-this.panel.yaerZhiShuText.textWidth+20)*0.5-20;
			this.panel.yaerZhiShuText.x=this.panel.yearLabel.x+35;
			if(msg.dailyReceived==1){
				this.panel.getDayRewardBtn.enabled=true;
			}
			else{
				this.panel.getDayRewardBtn.enabled=false;
			}
			this.panel.dayZhiShuText.text=StringUtil1.formatTime(Number(msg.beginTime),"yyyy-MM-dd-hh:mm",false)+LanguageRunner.getLanguageText("YAO_JIANG_TEXT")+StringUtil1.formatTime(Number(msg.endTime),"yyyy-MM-dd-hh:mm",false);;
			var newVipProxy=this.getProxy(NewVipProxy);
			var awards=newVipProxy.getHaveNewVipGiftRewardsArr(msg.dailyConfig);
			var itemVOArr=[];
			var itemViewArr=[];
			for (var i=0;i < awards.length;i++){
				if(awards[i]==""){
					continue ;
				};
				var itemvo=awards[i];
				var itemRenderVO=new AnniversaryDayRewardItemVO();
				itemRenderVO.itemVO=itemvo;
				itemVOArr.push(itemRenderVO);
			}
			this.panel.dayRewardList.clear();
			this.panel.dayRewardList.itemNumHorizontal=4;
			this.panel.dayRewardList.update(itemVOArr);
			this.panel.dayRewardList.verticalLineScrollPosition=1;
		}

		__proto.revExchangeInfo=function(note){
			var msg=note.body;
			var itemVOArr=[];
			var newVipProxy=this.getProxy(NewVipProxy);
			for(var i=0;i < msg.exchangeList.length;i++){
				var exchangeItemVO=new AnniversaryExchangeItemVO();
				exchangeItemVO.costNum=msg.exchangeList[i].exchangeBagCost;
				exchangeItemVO.giftId=msg.exchangeList[i].exchangeBagConfig;
				var giftDic=ClientDataProxy.getClientDataProxy().gift;
				var giftInfo=giftDic[msg.exchangeList[i].exchangeBagConfig];
				exchangeItemVO.giftImg=msg.exchangeList[i].icon;
				exchangeItemVO.exchageBagId=msg.exchangeList[i].exchangeBagId;
				exchangeItemVO.num=msg.exchangeList[i].exchangeBagCost;
				exchangeItemVO.status=msg.exchangeList[i].exchangeBagRecieved;
				exchangeItemVO=this.getGiftReward(exchangeItemVO);
				itemVOArr.push(exchangeItemVO);
			}
			this.panel.yearRewardList.clear();
			this.panel.yearRewardList.itemNumHorizontal=4;
			this.panel.yearRewardList.update(itemVOArr);
			this.panel.yearRewardList.verticalLineScrollPosition=1;
			var arr=this.panel.yearRewardList.getRenders();
			var item;
			/*for each*/for(var $each_item in arr){
				item=arr[$each_item];
				item.clickBtnCallBack=iflash.method.bind(this,this.clickExchageBtn);
			}
		}

		__proto.getGiftReward=function(exchangeItemVO){
			var giftDic=ClientDataProxy.getClientDataProxy().gift;
			var giftInfo=giftDic[exchangeItemVO.giftId];
			exchangeItemVO.giftName=LanguageRunner.getLanguageText(giftInfo["bag_name"]);
			var items="";
			for(var i=1;i < 12;i++){
				var key="bag_item_type"+i.toString();
				var keyNum="bag_item_id_number"+i.toString();
				if(giftInfo[key] !=0){
					if(i > 1){
						items+="|";
					};
					var arr=giftInfo[keyNum].split("=");
					var itemId=0;
					var num=1;
					var itemType=giftInfo[key];
					if(arr.length==2){
						itemId=arr[0];
						num=arr[1];
					}
					else{
						num=giftInfo[keyNum];
					}
					items=this.getGiftRewardDetail(itemType,itemId,num,items);
				}
				else{
					exchangeItemVO.items=items;
					return exchangeItemVO;
				}
			}
			exchangeItemVO.items=items;
			return exchangeItemVO;
		}

		__proto.getGiftRewardDetail=function(itemType,itemId,num,itemsStr){
			var newVipProxy=this.getProxy(NewVipProxy);
			var itemName="";
			if(itemType==/*utils.ItemType.ITEM_TYPE_SHEN_MI_GIFT*/28){
				var giftObj=newVipProxy.getMysterygiftInfoById(itemId);
				itemName=LanguageRunner.getLanguageText(giftObj["mbag_name"]);
			}
			else if(itemType==/*utils.ItemType.ITEM_TYPE_TREASURE*/17){
				var randomGift=newVipProxy.getRewardGiftRandomInfoId(itemId);
				itemName=LanguageRunner.getLanguageText(randomGift["bonus_name"]);
			}
			else if(itemType==/*utils.ItemType.ITEM_TYPE_NEWVIP*/23){
				var vipTypeVO=newVipProxy.getNewVipInfoById(itemId);
				itemName=vipTypeVO.wpDisplay;
			}
			else if(itemType==/*utils.ItemType.ITEM_TYPE_SKIN*/13){
				var skin=ClientDataProxy.getClientDataProxy().playerChangeInfo[itemId];
				itemName=LanguageRunner.getLanguageText(skin["skin_name"]);
			}
			else if(itemType==/*utils.ItemType.ITEM_TYPE_GENERAL*/2){
				var generalInfo=ClientDataProxy.getClientDataProxy().generalInfo[itemId];
				itemName=LanguageRunner.getLanguageText(generalInfo["General_Name"]);
			}
			else if(itemType==/*utils.ItemType.ITEM_TYPE_ITEM*/1
			|| itemType==/*utils.ItemType.ITEM_TYPE_FLAG*/12
			|| itemType==/*utils.ItemType.ITEM_TYPE_JADE*/14
			|| itemType==/*utils.ItemType.ITEM_TYPE_STONE*/11
			|| itemType==/*utils.ItemType.ITEM_TYPE_CANYE*/20
			|| itemType==/*utils.ItemType.ITEM_TYPE_CANJUAN*/21
			|| itemType==/*utils.ItemType.HUFU*/30
			|| itemType==/*utils.ItemType.GEM*/31
			|| itemType==/*utils.ItemType.EQUIP_ADVANCE_MATERIAL*/36
			|| itemType==/*utils.ItemType.JINGSHI*/40
			|| itemType==/*utils.ItemType.ANIMAL*/43
			|| itemType==/*utils.ItemType.ANIMAL_ADVANCE*/47
			|| itemType==/*utils.ItemType.ANIMAL_EXP*/45
			|| itemType==/*utils.ItemType.ANIMAL_NOMAL*/46
			|| itemType==/*utils.ItemType.ANIMAL_SOUL_FRAG*/44
			|| itemType==/*utils.ItemType.ANIMAL_SPIRIT*/42
			|| itemType==/*utils.ItemType.ZHAN_QI_YUAN_SHEN*/41){
				var itemInfo=ClientDataProxy.getClientDataProxy().itemInfo[itemId];
				itemName=LanguageRunner.getLanguageText(itemInfo["name"]);
			}
			else{
				var itemIdValue=ItemType.getItemTypeDic()[itemType];
				var itemObj=ClientDataProxy.getClientDataProxy().itemInfo[itemIdValue];
				itemName=LanguageRunner.getLanguageText(itemObj["name"]);
			}
			return itemsStr+itemName+":"+num+":"+"-1";
		}

		__proto.clickExchageBtn=function(giftId){
			var msg=ObjectPool.borrow(GetAnniversaryExchangeAwardMessage);
			msg.actId=this.actId;
			msg.bagId=giftId;
			Server.send(msg);
		}

		__proto.updateAllStatusBack=function(note){
			var msg=note.body;
			var newVipProxy=this.getProxy(NewVipProxy);
			var info;
			/*for each*/for(var $each_info in msg.winnerList){
				info=msg.winnerList[$each_info];
				this.lastTime=info.time!="0"?info.time:this.lastTime;
				var arr=info.awardConfig.split(":");
				var realItemArr=arr[1].split("=");
				var itemID=int(arr[0]);
				var itemRealId=0;
				var itemNum=1;
				if(realItemArr.length > 1){
					itemRealId=int(realItemArr[0]);
					itemNum=int(realItemArr[1]);
				}
				else{
					itemNum=int(arr[1]);
				};
				var itemVO=new ItemVO();
				itemVO.id=itemID;
				if(itemRealId !=0){
					itemVO=newVipProxy.getRewardItemName(itemVO,itemRealId,itemNum);
				};
				var str=LanguageRunner.getLanguageText("YAO_JIANG_NOTICE_TEXT",info.serverName,info.roleName,itemVO.itemInfoVO.name)
				if(itemNum > 1){
					str+="*"+itemNum;
				}
				this.rewardNoticeArr.push(str);
			}
		}

		__proto.openAnniversaryPanel=function(note){
			if(ConfigConnect.anniversary_onoff){
				this.loadSWF();
			}
		}

