		__proto.onQuanfuUpdate=function(e){
			var _$this=this;
			var content="";
			if(content==""){
				for(var index=0;index<this.rewardNoticeArr.length;index++){
					content=this.rewardNoticeArr[0];
					this.rewardNoticeArr.shift();
					break ;
				}
			}
			if(content !=""){
				var txt=ObjectPool.borrow(Label);
				txt.$width=348;
				txt.multiline=true;
				txt.wordWrap=true;
				txt.htmlText=content;
				txt.mouseEnabled=false;
				if(this.panel.noticeRewardList.numChildren>=20){
					this.panel.noticeRewardList.removeChildAt(0);
				}
				for(var i=0;i<this.panel.noticeRewardList.numChildren;i++){
					if(((this.panel.noticeRewardList.getChildAt(i))instanceof view.component.text.Label )){
						var la=this.panel.noticeRewardList.getChildAt(i);
						TweenLite.to(la,.2,{y:la.y+txt.textHeight+6});
					}
				}
				iflash.utils.setTimeout(function(){_$this.panel.noticeRewardList.addChild(txt);_$this.scroller2.update()},100);
			}
		}

