			this.campaignTeamPanel.rbmode2.labelField.fontColor=((mode >> 1)& 0x01)==1 ? /*utils.ColorUtil.RGB_YELLOW_EQUIP_NAV*/0xfcff00 :/*utils.ColorUtil.RGB_LIGHT_BLUE*/0x67ACB3;
			this.campaignTeamPanel.rbmode3.labelField.fontColor=((mode >> 2)& 0x01)==1 ? /*utils.ColorUtil.RGB_YELLOW_EQUIP_NAV*/0xfcff00 :/*utils.ColorUtil.RGB_LIGHT_BLUE*/0x67ACB3;
			this.campaignTeamPanel.rbmode4.labelField.fontColor=((mode >> 3)& 0x01)==1 ? /*utils.ColorUtil.RGB_YELLOW_EQUIP_NAV*/0xfcff00 :/*utils.ColorUtil.RGB_LIGHT_BLUE*/0x67ACB3;
			this.campaignTeamPanel.rbmode5.labelField.fontColor=((mode >> 4)& 0x01)==1 ? /*utils.ColorUtil.RGB_YELLOW_EQUIP_NAV*/0xfcff00 :/*utils.ColorUtil.RGB_LIGHT_BLUE*/0x67ACB3;
