		__proto.onTabBarChange=function(event){
			switch(int(event.selectedId)){
				case this.CAIMPAIGN_LIST:
					this.campaignTeamPanel.campaignTeamTabnavigator.getTabButton(1).visible=false;
					if (this.timerGetList.running){
						this.timerGetList.stop();
					}
					if(!this.timerGetCampaignList.running && this.isOpen){
						this.func_requestCampaignList();
						this.timerGetCampaignList.start();
					}
					break ;
				case this.CAIMPAIGN_TEAM:
					this.func_freshTitleInfoMation();
					this.func_net_requestCampaignTeamList();
					this.func_net_requestCampaign_history();
					if (!this.timerGetList.running && this.isOpen){
						this.timerGetList.start();
					}
					if(this.timerGetCampaignList.running){
						this.timerGetCampaignList.stop();
					};
					var teamproxy=this.getProxy(CampainTeamProxy);
					var judgement=teamproxy.publicJudgement;
					var tips=LanguageRunner.getLanguageText("CAMPAIGN_COMTIP");
					this.campaignTeamPanel.lbteamnum.toolTip=this.campaignTeamPanel.rtsrollbar.toolTip=this.campaignTeamPanel.txtteamnum.toolTip=TipUtil.getTextTipVO(tips);
					this.campaignTeamPanel.rbmode1.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText(judgement["6"]["judgement_name"]));
					this.campaignTeamPanel.rbmode2.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText(judgement["7"]["judgement_name"]));
					this.campaignTeamPanel.rbmode4.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText(judgement["9"]["judgement_name"]));
					this.campaignTeamPanel.rbmode5.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText(judgement["10"]["judgement_name"]));
					this.campaignTeamPanel.rbmode3.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText(judgement["8"]["judgement_name"]));
					break ;
				}
		}

