			this.subscribeNotification(/*global.NotificationType.CAMPAINTEAM_UPMEMBERS*/"updateMembersCampaignTeam",__bind(this,this.membersUpdateHandler));
			this.subscribeNotification(/*global.NotificationType.CAMPAINTEAM_HISTORY*/"historyCampaignTeam",__bind(this,this.historyCampaignTeamHandler));
			this.subscribeNotification(/*global.NotificationType.CAMPAINTEAM_CLOSE*/"campaignteam_close",__bind(this,this.selfCloseHandler));
			this.subscribeNotification(/*global.NotificationType.CAMPAINTEAM_DETAIL_DISPLAY*/"campaignteam_detail_display",__bind(this,this.campaignTeamDetailDisplayHandler));
