		__proto.close=function(){
			var _$this=this;
			if(this.campaignTeamSwitch && this.teamInfo !=null){
				if(this.teamInfo.isLeader){
					PromptBoxRunner.getInstance().openConfirm(LanguageRunner.getLanguageText("NINSHIDUIZHANG_JIESAN"),null,function(){
						_$this.closeFunc();
						_$this.timerGetList.stop();
						_$this.timerGetCampaignList.stop();
						_$this.onExist();
						_$this.clearTeamData(true);
						_$this.tabChangeAndSetEnable();
					},__bind(this,this.onCancel));
					}else {
					PromptBoxRunner.getInstance().openConfirm(LanguageRunner.getLanguageText("NINZAIDUIWUZHONG_JIESAN"),null,function(){
						_$this.closeFunc();
						_$this.timerGetList.stop();
						_$this.timerGetCampaignList.stop();
						_$this.onExist();
						_$this.clearTeamData(true);
						_$this.tabChangeAndSetEnable();
					},__bind(this,this.onCancel))
				}
			}
			else{
				this.closeFunc();
				this.timerGetList.stop();
				this.timerGetCampaignList.stop();
				this.onExist();
				this.clearTeamData(true);
				this.tabChangeAndSetEnable();
			}
			this.campaignTeamPanel.nf_concreteDetail.visible=true;
			this.campaignTeamPanel.nf_campaignDetail.visible=false;
			this.clearCampaignListDetail();
		}

