			var message=noti.body;
			this.inspireOverAmount=message.canInspireCount;
			this.inspireAmount=message.haveInspiredCount;
			this.crossServerWarMyInspirePanel.existInspireCount.text=LanguageRunner.getLanguageText("CROSSWAR_WAR_MYINSPIRE_2")+message.canInspireCount+"";
			this.crossServerWarMyInspirePanel.haveInspiredCount.text=LanguageRunner.getLanguageText("CROSSWAR_WAR_MYINSPIRE_3")+message.haveInspiredCount+"";
			Server.sendLocalConnection("message.isAutoInspire : "+message.isAutoInspire);
			if (message.isAutoInspire==1){
				this.crossServerWarMyInspirePanel.cbAutoInspire.selected=true;
			}
			else if (message.isAutoInspire==2 || message.isAutoInspire==3){
				this.crossServerWarMyInspirePanel.cbAutoInspire.selected=false;
			}
			this.crossServerWarMyInspirePanel.info5.text=LanguageRunner.getLanguageText("CROSSSERVERWARMYINSPIREPANEL_INFO5");
