			this.crossServerWarMyInspirePanel.attackBottom.text="+"+(int(cwp.crossInspireValueData[90001].Effect_num1)*this.inspireAmount);
			this.crossServerWarMyInspirePanel.harmBottom.text="+"+(int(cwp.crossInspireValueData[90003].Effect_num1)/ 1000 *this.inspireAmount)+"%";
			this.crossServerWarMyInspirePanel.soldiersBottom.text="+"+(int(cwp.crossInspireValueData[90002].Effect_num1)/ 1000 *this.inspireAmount)+"%";
			this.crossServerWarMyInspirePanel.harmJianBottom.text="+"+(int(cwp.crossInspireValueData[90004].Effect_num1)/ 1000 *this.inspireAmount)+"%";
