				var selfElement=ObjectPool.borrow(SelfTeamElement);
				var teamVO=this.teamInfoVO.members[i];
				selfElement.moveUpFunc=iflash.method.bind(this,this.moveUpHandler);
				selfElement.moveDownFunc=iflash.method.bind(this,this.moveDownHandler);
				selfElement.kickFunc=iflash.method.bind(this,this.kickHandler);
