		__class(CountryHarassWarProxy,'functions.countryHarassWar.model.CountryHarassWarProxy',false,_super);
		var __proto=CountryHarassWarProxy.prototype;
		__proto.revZhaoJiInfo=function(msg){
			if(msg.result==1){
				this.joinFightCityId=msg.zhaojiCity;
				this.joinFightId=msg.fightId;
				this.joinFightIndex=0;
				this.sendNotification(/*global.NotificationType.CHW_ENTER_FIGHT_SCENE*/"CHW_ENTER_FIGHT_SCENE",true,/*CLASS CONST:functions.countryHarassWar.model.CountryHarassWarProxy.JOIN_FIGHT*/0);
			}
			else{
				this.showErrorInfo(LanguageRunner.getLanguageText("GVG_ZHAO_JI_FAILURE"));
			}
		}

		__proto.revMyBattleScore=function(msg){
			if(this.checkIsHandlerMsg()){
				this.addMsgToArr(msg);
			}
		}

		__proto.revFightLatestIndex=function(msg){
			var type=0;
			if(msg.cityId==this.joinFightCityId && msg.fightId==this.joinFightId){
				type=0;
				this.joinFightTotalIndex=msg.latestIndex;
			}
			else if(msg.cityId==this.gvgLookFightCityId && msg.fightId==this.lookFightId){
				type=2;
				this.lookFightTotalIndex=msg.latestIndex;
			}
			this.sendNotification(/*global.NotificationType.CHW_GET_LATAST_FINGHT_INDEX*/"CHW_GET_LATAST_FINGHT_INDEX",msg,type);
		}

