		__proto.getCityName=function(cityId){
			var cityDic=ClientDataProxy.getClientDataProxy().gvgCityInfo;
			if(cityDic[cityId]==null){
				return "";
			}
			return LanguageRunner.getLanguageText(cityDic[cityId]["city_name"]);
		}

		__proto.getRewardTreasureString=function(isWiner,str){
			var arr=str.split(",");
			var treasureDic=ClientDataProxy.getClientDataProxy().gvgTreasure;
			var rewardStr="";
			for(var i=0;i < arr.length;i++){
				var info=arr[i];
				if(info==""){
					break ;
				};
				var itemId=info.split(":")[0];
				var treasureInfo=treasureDic[itemId];
				var itemName=LanguageRunner.getLanguageText(treasureInfo["name"]);
				var itemNum=info.split(":")[1];
				rewardStr+=itemName+"*"+itemNum+",";
			}
			return rewardStr;
		}

