		__proto.receiveGvGFight=function(msg){
			console.log("isExitGvg=="+this.isExitGvg);
			if(this.isExitGvg){
				return;
			}
			if(msg.cityId !=this.joinFightCityId && msg.cityId !=this.gvgLookFightCityId){
				return;
			}
			if(this._myJoinTeamResMsg !=null){
				if(msg.cityId==this._myJoinTeamResMsg.cityId && msg.fightId==this._myJoinTeamResMsg.fightId && msg.index==this._myJoinTeamResMsg.index){
					this._myJoinTeamResMsg=null;
				}
			}
			if(msg.cityId==this.gvgLookFightCityId && this.gvgIsLookFight){
				this.deleteRequstFightUrlMsg(msg.cityId,msg.index);
			}
			for(var i=0;i < this.requstFightUrlMsgList.length;i++){
				var requestMsg=this.requstFightUrlMsgList[i];
				if(msg.cityId==this.joinFightCityId){
					if(requestMsg.msg.fightId=="0" && requestMsg.msg.index==-1 && requestMsg.msg.cityId==msg.cityId){
						this.deleteRequstFightUrlMsg(msg.cityId,msg.index);
						break ;
					}
					else if(requestMsg.msg.fightId==msg.fightId && (requestMsg.msg.index==msg.index ||requestMsg.msg.index==-1)&& requestMsg.msg.cityId==msg.cityId){
						this.deleteRequstFightUrlMsg(msg.cityId,msg.index);
						break ;
					}
				}
			}
			this.isRevFightReport=true;
			this.setCurSelectFightCityId();
			this.sendNotification(/*global.NotificationType.CHW_GVG_FIGHT_MESSAGE*/"CHW_GVG_FIGHT_MESSAGE",msg);
		}

		__proto.deleteRequstFightUrlMsg=function(cityId,index){
			var arr=[];
			for(var i=0;i < this.requstFightUrlMsgList.length;i++){
				var requestMsg=this.requstFightUrlMsgList[i];
				if(requestMsg.msg.cityId==cityId && requestMsg.msg.index <=index){
					requestMsg.cancelDelay();
					arr.push(requestMsg);
				}
			}
			for(i=0;i < arr.length;i++){
				var msgIndex=this.requstFightUrlMsgList.indexOf(arr[i]);
				this.requstFightUrlMsgList.splice(msgIndex,1);
			}
		}

