		__proto.reveiveFightTeamInfo=function(msg){
			if(msg.cityId !=this.joinFightCityId && msg.cityId !=this.gvgLookFightCityId){
				return;
			}
			console.log("isRevFightReport==="+this.isRevFightReport+"setTeamCount==="+this.setTeamCount);
			if(this.isRevFightReport==true && this.setTeamCount < 2){
				this.sendNotification(/*global.NotificationType.CHW_REVEIVE_FINGHT_TEAM_INFO*/"CHW_REVEIVE_FINGHT_TEAM_INFO",msg);
				this.setTeamCount++;
				if(this.setTeamCount==2){
					this.isRevFightReport=false;
					this.setTeamCount=0;
					TweenLite.delayedCall(0.2,__bind(this,this.setCurFightTeamInfo));
				}
			}
			else if(this.isRevFightReport==true && this.checkIsJoinFight(msg.cityId,msg.index,msg.fightId)|| this.checkIsLookFight(msg.cityId,msg.index,msg.fightId)){
				this.sendNotification(/*global.NotificationType.CHW_REVEIVE_FINGHT_TEAM_INFO*/"CHW_REVEIVE_FINGHT_TEAM_INFO",msg);
			}
			else{
				this.addMsgToArr(msg);
			}
		}

