		__proto.setFightPlaySeepUP=function(curIndex,totoalIndex,type,rounds){
			return;
			var delayNum=totoalIndex-curIndex;
			var speed=1;
			if(type==0 || type==1){
				if(delayNum > 0){
					speed=1 /(1+delayNum *0.7)+1/(2+rounds);
					if(speed < /*functions.countryHarassWar.model.CHWBattleTimeConfig.maxSpeedUp*/0.25){
						speed=/*functions.countryHarassWar.model.CHWBattleTimeConfig.maxSpeedUp*/0.25;
					}
					CHWBattleTimeConfig.joinFightSpeed=speed;
				}
				else{
					CHWBattleTimeConfig.joinFightSpeed=1;
				}
			}
			else{
				if(delayNum > 0){
					speed=1 /(1+delayNum *0.7)+1/(2+rounds);
					if(speed < /*functions.countryHarassWar.model.CHWBattleTimeConfig.maxSpeedUp*/0.25){
						speed=/*functions.countryHarassWar.model.CHWBattleTimeConfig.maxSpeedUp*/0.25;
					}
					CHWBattleTimeConfig.lookFightSpeed=speed;
				}
				else{
					CHWBattleTimeConfig.lookFightSpeed=1;
				}
			}
		}

