			this.teamPanel.btnTeamCreate.toolTip=TipUtil.getTextTipVO(StringUtil1.format(LanguageRunner.getLanguageText("EVENT_POWER_LANGUAGE_20"),this.attackCDInMin));
			this.txtCDAttack.text=StringUtil1.format(LanguageRunner.getLanguageText("EVENT_POWER_LANGUAGE_20"),this.attackCDInMin);
