		__proto.func_bagClickHandler=function(event){
			var flagBagGraggable=event.target;
			if(this.flagBagCkickGrid==flagBagGraggable){
				return;
			}
			if(this.flagBagCkickGrid !=null){
				ColorUtil.removeColorRing(this.flagBagCkickGrid);
				this.flagBagCkickGrid.selectImage.visible=false;
			}
			this.flagBagCkickGrid=flagBagGraggable;
			this.bagCellSelectId=flagBagGraggable.bgIndex;
			if (this.bagCellSelectId !=0){
				this.flagPanel.sellFlag.enabled=false;
				this.flagPanel.sellFlag.toolTip=null;
				this.sendNotification(/*global.NotificationType.GET_FLAG_BIND_TYPE*/"get_flag_bind_type",this.flagBagCkickGrid.realId);
				}else {
				this.flagPanel.sellFlag.enabled=false;
				this.flagPanel.sellFlag.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("PLEASE_SELECT_THE_FLAG"));
				this.flagPanel.viewstackFlagBind.selectIndex(0);
				this.flagPanel.btnBinding.enabled=false;
				this.flagPanel.btnBinding.visible=true;
				this.flagPanel.btnRemoveBinding.enabled=false;
				this.flagPanel.btnRemoveBinding.visible=false;
				this.flagPanel.txtBindingStatus.text=LanguageRunner.getLanguageText("EQUIP_NO_BIND");
				this.flagPanel.txtBindingCD.complete=null;
			}
			LayaAPIFunc.addColorRing(this.flagBagCkickGrid);
			this.flagBagCkickGrid.selectImage.visible=true;
			this.flagBagCkickGrid.selectImage.width=this.flagBagCkickGrid.selectImage.height=56;
			this.flagBagCkickGrid.selectImage.x=this.flagBagCkickGrid.selectImage.y=-1;
		}

