			this.subscribeNotification(/*global.NotificationType.FLAG_BILL*/"flag_bill",__bind(this,this.onFlagBillHandler));
			this.subscribeNotification(/*global.NotificationType.FLAG_STONE_BILL*/"flag_stone_bill",__bind(this,this.onFlagStoneBillHandler));
			this.subscribeNotification(/*global.NotificationType.CHANGE_FLAG_BIND_STATUS_RESPONSE*/"change_flag_bind_status_response",__bind(this,this.onChangeFlagStatusResponse));
			this.subscribeNotification(/*global.NotificationType.SENIOR_PASSWORD_SET_KUAI_SU_HECHENGBTNSTATUS*/"SENIOR_PASSWORD_SET_KUAI_SU_HECHENGBTNSTATUS",__bind(this,this.setKuaiSuHeChengBtnStatus));
			this.subscribeNotification(/*global.NotificationType.SENIOR_PASSWORD_SETSMELTSTONESTATUS*/"SENIOR_PASSWORD_SETSMELTSTONESTATUS",__bind(this,this.setSmeltStoneStatus));
			this.subscribeNotification(/*global.NotificationType.SENIOR_PASSWORD_SENDFLAGSMELTAFTER*/"SENIOR_PASSWORD_SENDFLAGSMELTAFTER",__bind(this,this.sendFlagSmeltAfter));
