		__proto.onChangeFlagStatusResponse=function(note){
			var message=note.body;
			if(this.flagBagCkickGrid==null){
				return;
			}
			if (message.equipRealId !=this.flagBagCkickGrid.realId){
				return;
			}
			switch (int(message.bindType)){
				case /*functions.equip.model.EquipBindType.NO_BIND*/0:
					this.flagPanel.viewstackFlagBind.selectIndex(0);
					this.flagPanel.txtBindingStatus.text=LanguageRunner.getLanguageText("EQUIP_NO_BIND");
					this.flagPanel.btnBinding.enabled=true;
					this.flagPanel.btnBinding.visible=true;
					this.flagPanel.btnRemoveBinding.enabled=false;
					this.flagPanel.btnRemoveBinding.visible=false;
					this.flagPanel.sellFlag.enabled=true;
					this.flagPanel.txtBindingCD.complete=null;
					break ;
				case /*functions.equip.model.EquipBindType.BINDED*/1:
					this.flagPanel.viewstackFlagBind.selectIndex(0);
					this.flagPanel.txtBindingStatus.text=LanguageRunner.getLanguageText("EQUIP_BINDED");
					this.flagPanel.btnBinding.enabled=false;
					this.flagPanel.btnBinding.visible=false;
					this.flagPanel.btnRemoveBinding.enabled=true;
					this.flagPanel.btnRemoveBinding.visible=true;
					this.flagPanel.sellFlag.enabled=false;
					this.flagPanel.txtBindingCD.complete=null;
					break ;
				case /*functions.equip.model.EquipBindType.BIND_CD*/2:
					this.flagPanel.viewstackFlagBind.selectIndex(1);
					this.flagPanel.sellFlag.enabled=false;
					if (Number(message.bindTime)> 0){
						this.flagPanel.txtBindingCD.startCountDown(Number(message.bindTime));
						this.flagPanel.txtBindingCD.complete=iflash.method.bind(this,this.onBtnBindingCDComplete);
					}
					break ;
				}
		}

		__proto.initBindStatusView=function(){
			if(this.flagBagCkickGrid==null){
				this.flagPanel.viewstackFlagBind.selectIndex(0);
				this.flagPanel.txtBindingStatus.text=LanguageRunner.getLanguageText("EQUIP_NO_BIND");
				this.flagPanel.btnBinding.enabled=false;
				this.flagPanel.btnBinding.visible=true;
				this.flagPanel.btnRemoveBinding.enabled=false;
				this.flagPanel.btnRemoveBinding.visible=false;
				this.flagPanel.sellFlag.enabled=false;
			}
		}

