		__proto.addStuffButtonClick=function(targetNumLabel,targetButtonImg,srcButtonImg,button){
			var num1=this.numData[targetButtonImg.id];
			if(button.data){
				if(num1 <=0){
					if(targetButtonImg.id !=0){
						var itemDic=(this.getProxy(FlagProxy1))._itemDic;
						var itemInfo=itemDic[targetButtonImg.id];
						if (itemInfo !=null){
							if (itemInfo.type==3){
								var flagInfo=(this.getProxy(FlagProxy1))._flagDic[targetButtonImg.id];
								if (flagInfo["sale"]==1){
									this.sendNotification(/*global.NotificationType.FLAG_BUYSTUFF*/"flag_buystuff",{stuffId:targetButtonImg.id});
									}else {
									var pVO=new PromptTextVO();
									pVO.text=LanguageRunner.getLanguageText("LACK_STUFF_BUY_LOW_LV_STUFF");
									pVO.color=/*utils.ColorUtil.RGB_RED*/0xff0000;
									this.sendNotification(/*global.NotificationType.PUSH_PROMPT_TEXT_IN_NO_DELAY*/"pushPromptTextInNoDelay",pVO);
								}
								}else if (itemInfo.type==4){
								var stoneInfo=(this.getProxy(FlagProxy1))._stoneTypeDic[targetButtonImg.id];
								if (stoneInfo["sale"]==1){
									this.sendNotification(/*global.NotificationType.FLAG_BUYSTUFF*/"flag_buystuff",{stuffId:targetButtonImg.id});
									}else {
									var pVO=new PromptTextVO();
									pVO.text=LanguageRunner.getLanguageText("LACK_STUFF_BUY_LOW_LV_STUFF");
									pVO.color=/*utils.ColorUtil.RGB_RED*/0xff0000;
									this.sendNotification(/*global.NotificationType.PUSH_PROMPT_TEXT_IN_NO_DELAY*/"pushPromptTextInNoDelay",pVO);
								}
							}
						}
					}
					return false;
				}
				else{
					num1=num1-1;
					this.numData[targetButtonImg.id]=num1;
					srcButtonImg.fgImage.image=new String(targetButtonImg.fgImage.url);
					srcButtonImg.id=targetButtonImg.id;
					return true;
				}
			}
			else{
				num1=num1+1;
				this.numData[targetButtonImg.id]=num1;
				srcButtonImg.fgImage.image="";
				srcButtonImg.id=0;
				return true;
			}
		}

