		__proto.lockGiftRes=function(note){
			var msg=note.body;
			if(msg.result !=1){
				return;
			};
			var giftViewBean=null;
			for(var i=0;i < this.onlineGiftInfoVOList.length;i++){
				var gift=this.onlineGiftInfoVOList[i];
				giftViewBean=gift;
				if(gift.giftDBId==msg.giftDId){
					if(msg.expired !="0"){
						gift.locked=2;
						gift.expired=msg.expired;
					}
					else{
						gift.locked=1;
					}
					break ;
				}
			}
			this.onlineGiftInfoVOList=this.onlineGiftInfoVOList.sort(function(gift1,gift2){
				var endTime1=Number(gift1.expired);
				var endTime2=Number(gift2.expired);
				var currentTimestamp=ServerTimeUitl.getInstance().getServerTimestamp();
				endTime1=endTime1-currentTimestamp <=0?0:endTime1-currentTimestamp;
				endTime2=endTime2-currentTimestamp <=0?0:endTime2-currentTimestamp;
				if(gift1.locked < gift2.locked || (gift1.locked==gift2.locked && ((endTime1 < endTime2 && endTime1 > 0)|| (endTime1 > endTime2 && endTime2==0)))){
					return-1;
				}
				else if(gift1.locked > gift2.locked ||(gift1.locked==gift2.locked && ((endTime1 > endTime2 && endTime2 > 0)|| (endTime1 < endTime2 && endTime1==0)))){
					return 1;
				}
				else{
					return 0;
				}
			});
			if(giftViewBean==null){
				return;
			}
			for(var j=0;j < this.onlineGiftList.length;j++){
				var giftView=this.onlineGiftList[j];
				if(giftView.value.giftDBId==msg.giftDId){
					giftView.update(giftViewBean);
					if(this.giftPanel.giftCancelLockBtn.visible){
						giftView.updateBtn(true);
					}
					else{
						giftView.updateBtn(false);
					}
					break ;
				}
			}
		}

