		__proto.switchTab=function(index){
			this.getShenMiGiftInfoMessageGiftId="";
			this.getGiftInfoMessageGiftId="";
			this.giftPanel.tabnavigator0TabNavigator.selectIndex(index);
			this.currentTabIndex=index;
			this.switchRequest(index);
		}

		__proto.switchRequest=function(index){
			this.sendNotification(/*global.NotificationType.GUIDE_STEP_CONDITION*/"guideStepConditon",/*functions.guide.model.GuideConditionType.PanelOpenTab*/4,this.panelID,index);
			switch(index){
				case 0:
					this.giftPanel.giftCancelLockBtn.visible=false;
					this.giftPanel.giftLockBtn.visible=true;
					this.ClearGiftItem();
					var giftProxy=this.getProxy(GiftProxy);
					if(giftProxy.giftMsg){
						var msg=ObjectPool.borrow(GetGiftPageShowMessage);
						Server.send(msg);
						giftProxy.giftMsg=false;
					}
					this.giftPanel.GiftOnlineFlipPage.enabled=false;
					break ;
				case 1:
					this.switchTreasurePage(1);
					break ;
				case 2:
					this.giftPanel.smGiftCancelLockBtn.visible=false;
					this.giftPanel.smGiftLockBtn.visible=true;
					var msgShenMi=ObjectPool.borrow(GetMysteryGiftPageMessage);
					Server.send(msgShenMi);
					break ;
				case 3:
					this.sendNotification(/*global.NotificationType.INTERACTIVE_APPLY*/"interactive_apply");
					var mediator=this.context.view.getMediator(GiftApplyMediator);
					mediator.switchTabByIndex();
					break ;
				}
		}

