		__proto.onlineGiftItem=function(giftList,page){
			(page===void 0)&& (page=1);
			if(giftList.length==0){
				return;
			}
			this.onlineGiftList=[];
			var pageFirIndex=(page-1)*/*data.FlipPageType.PAGE_GIFT*/9;
			var pageLastIndex=page */*data.FlipPageType.PAGE_GIFT*/9;
			if(giftList !=null){
				var giftId="";
				for(var i=pageFirIndex;i < pageLastIndex;i++){
					if(giftList.length > i){
						if(giftList[i] !=null && (giftList[i].name=="" || giftList[i].name==null)){
							if(giftId.indexOf(giftList[i].giftId.toString())< 0){
								giftId+=giftList[i].giftId+",";
							}
						}
					}
				}
				if(giftId==""){
					for(var i=pageFirIndex;i < pageLastIndex;i++){
						if(giftList.length > i){
							var grid=new GiftShowFrame();
							this.giftPanel.GiftOnlineContainer.addChild(grid);
							grid.update(giftList[i]);
							grid.addEventListener("onGetbtnClick",__bind(this,this.onGetGiftClick));
							this.onlineGiftList.push(grid);
						}
					}
					LayoutUtil.layout(new ListIterator(this.onlineGiftList),new RectangleLayoutBehavior(3,197,90),0,8);
					if(this.giftPanel.giftCancelLockBtn.visible){
						this.updateGiftItemBtn(true);
					}
					else{
						this.updateGiftItemBtn(false);
					}
				}
				else if(this.getGiftInfoMessageGiftId=="" || this.getGiftInfoMessageGiftId !=giftId){
					var msg=ObjectPool.borrow(GetGiftInfoMessage);
					msg.giftIdList=giftId;
					Server.send(msg);
					this.getGiftInfoMessageGiftId=giftId;
				}
			}
		}

