	var HuangListFightRecordPanelMediator=(function(_super){
		function HuangListFightRecordPanelMediator(viewComponent){
			this.panel=null;
			HuangListFightRecordPanelMediator.__super.call(this,viewComponent);
			this.panel=viewComponent;
			this.panel.clickCallBack=iflash.method.bind(this,this.closePanel);
		}

		__class(HuangListFightRecordPanelMediator,'functions.huangList.view.HuangListFightRecordPanelMediator',false,_super);
		var __proto=HuangListFightRecordPanelMediator.prototype;
		__proto.configNotifications=function(){
			_super.prototype.configNotifications.call(this);
			this.subscribeNotification(/*global.NotificationType.HUANG_LIST_RECORD_LIST*/"HUANG_LIST_RECORD_LIST",__bind(this,this.getRecordList));
		}

		__proto.closePanel=function(selectRoleId){
			this.close();
			var proxy=this.getProxy(HuangListProxy);
			proxy.curSelectRoleId=selectRoleId;
		}

		__proto.getRecordList=function(note){
			var msg=note.body;
			var roleProxy=this.getProxy(RoleProxy);
			var roleId=roleProxy.roleVO.id;
			this.panel.clearList();
			var arr=[];
			var info;
			/*for each*/for(var $each_info in msg.recordList){
				info=msg.recordList[$each_info];
				var str="";
				if(info.attRoleId==roleId){
					if(info.resultWar==1){
						str=LanguageRunner.getLanguageText("HUANG_LIST_RECORD1",info.defServerName,info.defRoleId,info.defRoleName,info.extraGetMeritValue,info.getMeritValue);
						if(info.extraGetMeritValue==0 && info.getMeritValue > 0){
							str=LanguageRunner.getLanguageText("HUANG_LIST_RECORD5",info.defServerName,info.defRoleId,info.defRoleName,info.getMeritValue);
						}
						else if(info.getMeritValue==0 && info.extraGetMeritValue > 0){
							str=LanguageRunner.getLanguageText("HUANG_LIST_RECORD8",info.defServerName,info.defRoleId,info.defRoleName,info.extraGetMeritValue);
						}
						else if(info.getMeritValue==0 && info.extraGetMeritValue==0){
							str=LanguageRunner.getLanguageText("HUANG_LIST_RECORD7",info.defServerName,info.defRoleId,info.defRoleName);
						}
					}
					else{
						str=LanguageRunner.getLanguageText("HUANG_LIST_RECORD2",info.defServerName,info.defRoleId,info.defRoleName);
					}
				}
				else if(info.defRoleId==roleId){
					if(info.resultWar==1){
						str=LanguageRunner.getLanguageText("HUANG_LIST_RECORD4",info.attServerName,info.attRoleId,info.attRoleName,info.extraGetMeritValue,info.getMeritValue);
						if(info.extraGetMeritValue==0 && info.getMeritValue > 0){
							str=LanguageRunner.getLanguageText("HUANG_LIST_RECORD6",info.attServerName,info.defRoleId,info.attRoleName,info.getMeritValue);
						}
						else if(info.getMeritValue==0 && info.extraGetMeritValue > 0){
							str=LanguageRunner.getLanguageText("HUANG_LIST_RECORD10",info.attServerName,info.defRoleId,info.attRoleName,info.extraGetMeritValue);
						}
						else if(info.getMeritValue==0 && info.extraGetMeritValue==0){
							str=LanguageRunner.getLanguageText("HUANG_LIST_RECORD9",info.attServerName,info.defRoleId,info.attRoleName);
						}
					}
					else{
						str=LanguageRunner.getLanguageText("HUANG_LIST_RECORD3",info.attServerName,info.attRoleId,info.attRoleName);
					}
				}
				arr.push(str);
			}
			this.panel.showRecordList(arr);
		}

		return HuangListFightRecordPanelMediator;
	})(BasePanelMediator)


