		__proto.qihunSingleUpdateBack=function(note){
			var msg=note.body;
			var excNum=0;
			var item;
			/*for each*/for(var $each_item in this.elementList){
				item=this.elementList[$each_item];
				if(item.itemVO.storeId==msg.storeId){
					excNum=item.itemVO.reNum-msg.reNum;
					item.itemVO.reNum=msg.reNum;
					item.updateItem(item.itemVO);
					item.dispatchEvent(new MouseEvent(/*iflash.events.MouseEvent.CLICK*/"click"));
					break ;
				}
			}
			if(msg.isTrue){
				this.personContent=StringUtil1.format(LanguageRunner.getLanguageText("QIHUN_DUIHUANTIP"),this.personObj.price*excNum,excNum*this.personObj.cellNum,this.personObj.itemName);
				this.personArr.push(this.personContent);
				this.openMovie.visible=true;
				this.openMovie.play();
				if(!this.qihunStore.contains(this.openMovie)){
					this.qihunStore.addChild(this.openMovie);
				}
				if(!this.personTimer.running){
					this.personTimer.start();
				}
			}
		}

