		__proto.onUpdateDraftResponse=function(note){
			var roleProxy=this.getProxy(RoleProxy);
			if((int(SharedObjectManager.getInstance().getData(roleProxy.roleVO.id+"showSecretary"))==0)&& this.flag){
				if(ConfigConnect.SecretarySwitch && roleProxy.roleVO.level>29 && !Managers.guideManager.isGuide){
					var resetPasswordProxy=this.getProxy(ResetPasswordProxy);
					if(resetPasswordProxy&&!resetPasswordProxy.isShow){
						this.sendNotification(/*global.NotificationType.OPEN_PANEL*/"openPanel",/*functions.panel.model.PanelType.NEW_SECRETARY_SETTING*/82);
					}
				}
				this.flag=false;
			};
			var message=note.body;
			var cdQueueInfoVO=ObjectPool.borrow(CDQueueInfoVO);
			cdQueueInfoVO.cdID=message.cdId;
			cdQueueInfoVO.oddTimes=message.leavingTime;
			cdQueueInfoVO.cdType=/*functions.cd.model.CDType.CONSCRIPT*/1016;
			this.draftCaution.setQueueInfo(cdQueueInfoVO);
		}

		__proto.onUpdateSalaryResponse=function(note){
			var officialInfo=note.body;
			var salaryState=officialInfo.salaryStat;
			if(salaryState==1){
				this.salaryCaution.leftTimes=1;
				}else {
				this.salaryCaution.leftTimes=0;
			}
			this.drawList(this.affairArr);
		}

		__proto.onUpdateSoundResponse=function(note){
			if(Boolean(note.body)){
				return;
			}
			if (SoundManager.getInstance().flagMusicMute){
				this.secretaryFrame.musicCK.selected=false;
			}
			else{
				this.secretaryFrame.musicCK.selected=true;
			}
			if (SoundManager.getInstance().flageSoundEfectMute){
				this.secretaryFrame.checkMusicEffect.selected=false;
			}
			else{
				this.secretaryFrame.checkMusicEffect.selected=true;
			}
		}

		__proto.onAffairClick=function(event){
			this.curSecretaryItem=event.currentTarget;
			this.drawList(this.affairArr);
		}

		__proto.onBattleClick=function(event){
			this.curSecretaryItem=event.currentTarget;
			this.drawList(this.warArr);
		}

		__proto.onActiveClick=function(event){
			this.curSecretaryItem=event.currentTarget;
			this.drawList(this.activeArr);
		}

		__proto.drawList=function(functionsArr){
			var item;
			/*for each*/for(var $each_item in this.elementList){
				item=this.elementList[$each_item];
				ColorUtil.deHighLight(item);
			}
			if(this.curSecretaryItem){
				ColorUtil.highLight(this.curSecretaryItem);
				}else {
				this.curSecretaryItem=this.elementList [1];
				ColorUtil.highLight(this.curSecretaryItem);
			}
			this.secretaryFrame.secretaryList.verticalScrollPosition=0;
			DisplayUtil.removeAllChildren(this.secretaryFrame.secretaryContainer);
			var i=0;
			var yPadding=2;
			var yGap=3;
			while(i<functionsArr.length){
				if((functionsArr [i]).leftTimes!=0 || (functionsArr [i]).type==2){
					if((functionsArr [i]).isOpen==1){
						(functionsArr [i]).x=5;
						(functionsArr [i]).y=yPadding;
						DisplayUtil.addChild(functionsArr[i],this.secretaryFrame.secretaryContainer);
						yPadding+=(functionsArr [i]).height+yGap;
					}
				}
				i++;
			}
			this.secretaryFrame.secretaryList.update();
		}

		__proto.drawLayout=function(){}
		__proto.onCDQueueTimerComplete=function(qVO){
			switch(int(qVO.cdType)){
				case /*functions.cd.model.CDType.TAX*/1004:
					this.taxCaution.setCanUse();
					break ;
				case /*functions.cd.model.CDType.STRONG*/1010:
					this.strongerCaution.setCanUse();
					break ;
				case /*functions.cd.model.CDType.TECH*/1002:
					this.techCaution.setCanUse();
					break ;
				case /*functions.cd.model.CDType.CONSCRIPT*/1016:
					this.draftCaution.setCanUse();
					break ;
				case /*functions.cd.model.CDType.REPAIR*/1019:
					this.buildCaution.setCanUse();
					break ;
				case /*functions.cd.model.CDType.CITY_INVEST*/1012:
					this.investCaution.setCanUse();
					break ;
				case /*functions.cd.model.CDType.TAOBAO*/1011:
					this.taobaoCaution.setCanUse();
					break ;
				}
			SoundManager.getInstance().playSound("sounds/effect/tip.mp3",1,0,1);
		}

