		__proto.getItemInfoBack=function(note){
			var msg=note.body;
			var storeItem;
			var i=0;
			var templateId;
			var addNum=0;
			for(i=0;i<this.storeItems.length;i++){
				storeItem=this.storeItems[i];
				if(storeItem.itemVO.onlyId==msg.onlyId){
					storeItem.itemVO.reNum=msg.reNum;
					templateId=storeItem.itemVO.templateId;
					addNum=storeItem.itemVO.cellNum;
					break ;
				}
			}
			for(i=0;i<this.storeItems.length;i++){
				storeItem=this.storeItems[i];
				if(storeItem.itemVO.templateId==templateId){
					storeItem.itemVO.ownNum+=addNum;
					storeItem.updateItem(storeItem.itemVO);
					if(storeItem.itemVO.onlyId==msg.onlyId){
						storeItem.dispatchEvent(new MouseEvent(/*iflash.events.MouseEvent.CLICK*/"click"));
					}
				}
			}
		}

