		__proto.updateStartFightTime=function(note){
			var msg=note.body;
			if(this.teamElementList==null){
				return;
			}
			var info;
			/*for each*/for(var $each_info in msg.teamLastTimeInfo){
				info=msg.teamLastTimeInfo[$each_info];
				for(var i=0;i < this.teamElementList.length;i++){
					var element=this.teamElementList [i];
					if(element.value !=null && element.value.fightID==info.fightId && element.value.teamID==info.teamId){
						element.updateStartFightTime(info.lastTime);
						break ;
					}
				}
			}
		}

