		__proto.shakeFunction=function(dis,times,offset,speed){
			(times===void 0)&& (times=1);
			(offset===void 0)&& (offset=8);
			(speed===void 0)&& (speed=10);
			var point=new Point(dis.x,dis.y);
			var offsetXYArray=[0,0];
			var num=0;
			var u=iflash.utils.setInterval(
			function(){
				offsetXYArray[num%2]=(num++)%4<2 ?0:offset;
				dis.x=offsetXYArray[0]+point.x;
				dis.y=offsetXYArray[1]+point.y;
				if(num>(times*4+1)){
					iflash.utils.clearInterval(u);
					num=0;
				}
			},speed);
		}

