		__proto.showEndResult=function(vo){
			this.result.visible=true;
			var resultType=vo.result;
			var roleId=Contants.getGrobalObject("groupBattleReportViewer");
			if (roleId !=null&&roleId!=""){
				var info=vo.getArmyInfoByRoleID(roleId);
				if (info !=null){
					if (vo.result==0){
						resultType=0;
						}else if ((info.id < 100 && vo.result==1)|| (info.id >=100 && vo.result==2)){
						resultType=1;
						}else {
						resultType=2;
					}
					}else{
					resultType=this.multiEngine.result;
					if(resultType==-1)resultType=vo.result;
				}
				this.result.update(resultType,vo.drops,GroupBattleCopyReportURL.copyReportURL,roleId);
				}else{
				resultType=this.multiEngine.result;
				if(resultType==-1)resultType=vo.result;
				if (resultType !=-1){
					this.result.update(resultType,vo.drops,GroupBattleCopyReportURL.copyReportURL);
				}
			}
			if(resultType==1){
				CoreEventDispatcher.dispatchEvent(new CoreEvent(CoreEvent.CRIT_ACTIVITY_BATTLE_PLAY_END));
			}
			else{
				CoreEventDispatcher.dispatchEvent(new CoreEvent(CoreEvent.CRIT_ACTIVITY_BATTLE_HIDE,null,true));
			}
		}

