		__proto.updateMemberList=function(memList){
			DisplayUtil.removeAllChildrenToPool(this.preArmysContainer);
			var layoutBehavior=new GroupBattlePreArmyLayoutBehavior(50,50);
			var attackers=[];
			var defenders=[];
			for(var i=0;i < memList.length;i++){
				var entity=ObjectPool.borrow(GroupBattleArmyEntity);
				var value=memList[i];
				entity.updateMember(value);
				if(value.isAttacker){
					this.attackerDict[value.id]=entity;
					attackers.push(entity);
					this.preArmysContainer.addChild(entity);
					}else {
					this.defenderDict[value.id]=entity;
					defenders.push(entity);
					this.preArmysContainer.addChildAt(entity,0);
				}
			}
			layoutBehavior.angle=Math.PI / 5.2;
			LayoutUtil.layout(new ListIterator(attackers),layoutBehavior,90,230);
			layoutBehavior.angle=Math.PI *6.2 / 5.2;
			LayoutUtil.layout(new ListIterator(defenders),layoutBehavior,860,310);
		}

		__proto.updateBuffList=function(data){
			var value;
			/*for each*/for(var $each_value in data){
				value=data[$each_value];
				var entity=(value.isAttacker ? this.attackerDict[value.roleID] :this.defenderDict[value.roleID]);
				if(entity !=null)entity.updateBuff(value);
				if(value.roleID==this.roleVO.id)this.updateSelfBuff(value);
			}
		}

		__proto.updateBuff=function(buff){
			if (buff.roleID==this.roleVO.id){
				this.selfBuff.attBuff=buff.attBuff
				this.selfBuff.defBuff=buff.defBuff;
				this.selfBuff.specBuff_1=buff.specBuff_1;
				this.selfBuff.specBuff_2=buff.specBuff_2;
				this.selfBuff.specBuff_3=buff.specBuff_3;
				this.selfBuff.specBuff_4=buff.specBuff_4;
				this.selfBuff.cd=buff.cd;
				this.selfBuff.cdID=buff.cdID;
				this.updateSelfBuff(this.selfBuff);
			}
		}

		__proto.update=function(isShare,reportURL,report,roleId,resultType){
			(resultType===void 0)&& (resultType=-1);
			this.multiEngine.roleId=roleId;
			this.multiEngine.report=report;
			GroupBattleCopyReportURL.isShare=isShare;
			GroupBattleCopyReportURL.copyReportURL=reportURL;
			if (resultType !=-1){
				this.multiEngine.result=resultType;
			}
			this.battleVO=this.multiEngine.multiBattleVO;
			this.switchState(1);
		}

		__proto.startBattle=function(){
			this.imgBG.url=ConfigConnect.LangType+"/groupbattle/bg/"+this.battleVO.type+"/bg.jpg";
			this.multiEngine.updateView();
			this.updatePrepareArmys();
			this.switchState(2);
			this.start();
		}

