				this.countdownTime.startNumCountDown(this.cityInfo.protectTime);
				this.protectTimeImg.visible=true;
				this.protectTimeImg.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("GVG_PROTECT_TIME_STR",Math.ceil(this.cityInfo.protectTime / 1000)));
