			this.x=this.cityInfo.cityX-this.cityImg.width *0.5;
			this.y=this.cityInfo.cityY-this.cityImg.height *0.5;
			if(this.cityInfo.isDestroyed){
				this.showSmokeEffect();
			}
			else{
				this.stopSmokeEffect();
			}
			if(this.cityInfo.cityStatus==/*functions.gvg.model.GvgCityStatusType.WAR*/2){
				this.showIsInWarEffect();
			}
			else{
				this.stopIsInWarEffect();
			}
