			this.x=this.cityInfo.cityX-this.cityImg.width *0.5;
			this.y=this.cityInfo.cityY-this.cityImg.height *0.5;
			this.protectTimeImg.x=(this.cityImg.width-17)*0.5;
			this.protectTimeImg.y=-20;
			this.cityImg.visible=true;
			this.cityName.x=(this.cityImg.width-this.cityName.textWidth)*0.5;
			this.cityName.y=this.cityImg.height;
			this.cityName.visible=true;
			this.flag.x=-3;
			this.flag.y=this.cityImg.height *0.5-40;
