	var GvgIconPanel=(function(_super){
		function GvgIconPanel(){
			this.isopen=false;
			this.tipsList=[this.ZJ,this.AM,this.CH,this.KU,this.DA,
			this.FD,this.LE,this.FFD,this.GY,this.HQ,
			this.HX,this.HH,this.HUX,this.KA,this.KUN,
			this.HANG,this.TX,this.TU,this.WQ,this.XU];
			this.signList=["","#001","#002","#003","#004","#005",
			"#006","#007","#008","#009","#010",
			"#011","#012","#013","#014","#015",
			"#016","#017","#018","#019","#020"];
			GvgIconPanel.__super.call(this);
			this.container=new Sprite();
			this.tip=new TextField();
			this.ZJ=LanguageRunner.getLanguageText("EMOTIONSHOWZAIJIAN");
			this.AM=LanguageRunner.getLanguageText("EMOTIONSHOAOAMAN");
			this.CH=LanguageRunner.getLanguageText("EMOTIONSHOWCHI");
			this.KU=LanguageRunner.getLanguageText("EMOTIONSHOWKU");
			this.DA=LanguageRunner.getLanguageText("EMOTIONSHOWDAI");
			this.FD=LanguageRunner.getLanguageText("EMOTIONSHOWFADOU");
			this.LE=LanguageRunner.getLanguageText("EMOTIONSHOWLENG");
			this.FFD=LanguageRunner.getLanguageText("EMOTIONSHOWFENDOU");
			this.GY=LanguageRunner.getLanguageText("EMOTIONSHOWGOUYIN");
			this.HQ=LanguageRunner.getLanguageText("EMOTIONSHOWHAQIE");
			this.HX=LanguageRunner.getLanguageText("EMOTIONSHOWHAIXIU");
			this.HH=LanguageRunner.getLanguageText("EMOTIONSHOWHEHE");
			this.HUX=LanguageRunner.getLanguageText("EMOTIONSHOWHUAIXIAO");
			this.KA=LanguageRunner.getLanguageText("EMOTIONSHOWKEAI");
			this.KUN=LanguageRunner.getLanguageText("EMOTIONSHOWKUN");
			this.HANG=LanguageRunner.getLanguageText("EMOTIONSHOWHANG");
			this.TX=LanguageRunner.getLanguageText("EMOTIONSHOWTOUXIAO");
			this.TU=LanguageRunner.getLanguageText("EMOTIONSHOWTU");
			this.WQ=LanguageRunner.getLanguageText("EMOTIONSHOWWEIQU");
			this.XU=LanguageRunner.getLanguageText("EMOTIONSHOWXU");
			this.buildUI();
		}

		__class(GvgIconPanel,'functions.gvg.view.GvgIconPanel',false,_super);
		var __proto=GvgIconPanel.prototype;
		__proto.buildUI=function(){
			this.paintBack();
			ResourceRunner.getSprite(/*data.Resources.FIRST_FACE_NEWCHAT_EMOTION_SWF*/"emotion.swf",__bind(this,this.initialIcon));
			this.tip.border=true;
			this.tip.background=true;
			this.tip.backgroundColor=0xFFFFFF;
		}

		__proto.initialIcon=function(src){
			var mc=src;
			var resLoad=mc.parent;
			var num=21;
			var list=[];
			for(var i=1;i<num;i++){
				var className="F"+i;
				if(i <=9){
					className="F0"+i;
				};
				var ClassReference=resLoad.contentLoaderInfo.applicationDomain.getDefinition(className);
				var clasz=new ClassReference();
				RichTextField.addTransfer(this.signList[i],ClassReference);
				clasz.name=""+i;
				list.push(clasz);
				this.configEvent(clasz);
				clasz.x=((i-1)% 4)*32;
				clasz.y=int((i-1)/4)*22;
				this.addChild(clasz);
			}
		}

		__proto.configEvent=function(dis){
			dis.addEventListener(/*iflash.events.MouseEvent.MOUSE_OUT*/"mouseOut",__bind(this,this.removeTip));
			dis.addEventListener(/*iflash.events.MouseEvent.MOUSE_OVER*/"mouseOver",__bind(this,this.drawTip));
			dis.addEventListener(/*iflash.events.MouseEvent.CLICK*/"click",__bind(this,this.sendEmotionHanlder));
			dis.addEventListener(/*iflash.events.MouseEvent.MOUSE_DOWN*/"mouseDown",__bind(this,this.ignoreEvent));
			dis.addEventListener(/*iflash.events.MouseEvent.MOUSE_UP*/"mouseUp",__bind(this,this.ignoreEvent));
		}

		__proto.paintBack=function(){
			this.container.graphics.clear();
			this.container.graphics.beginFill(0,0.3);
			this.container.graphics.lineStyle(0.7,0);
			this.container.graphics.drawRect(0,0,128,122);
			this.container.graphics.endFill();
			this.addChild(this.container);
		}

		__proto.removeTip=function(evt){
			if(this.tip.parent!=null){
				this.removeChild(this.tip);
			}
		}

		__proto.sendEmotionHanlder=function(evt){
			var dis=evt.target;
			var idx=int(dis.name);
			var emotionMsg=this.signList[idx];
			this.dispatchEvent(new CoreEvent("emotionMsgSend",this,emotionMsg,true));
		}

		__proto.ignoreEvent=function(evt){
			evt.stopPropagation();
		}

		__proto.drawTip=function(evt){
			var dis=evt.target;
			var idx=int(dis.name);
			var name=this.tipsList[idx-1];
			this.tip.text=name;
			this.tip.width=this.tip.textWidth+4;
			this.tip.height=this.tip.textHeight+2;
			this.tip.x=StageRunner.stage.mouseX+10;
			this.tip.y=StageRunner.stage.mouseY-this.tip.height/2;
			this.tip.mouseEnabled=false;
			if(this.tip.parent==null){
				this.addChild(this.tip);
			}
		}

		return GvgIconPanel;
	})(Sprite)


