		__proto.showArmyMove=function(obj){
			var obj2=this.pathArr[0];
			var road1=this.getGrid(obj.x,obj.y);
			var road2=this.getGrid(obj2.x,obj2.y);
			var disx=road2.pointX-road1.pointX;
			var disy=road2.pointY-road1.pointY;
			if(disx > 0 && disy==0){
				this.personGrid.moving(7,road2.pointX,road2.pointY);
			}
			else if(disx > 0 && disy > 0){
				this.personGrid.moving(3,road2.pointX,road2.pointY);
			}
			else if(disx==0 && disy > 0){
				this.personGrid.moving(6,road2.pointX,road2.pointY);
			}
			else if(disx < 0 && disy > 0){
				this.personGrid.moving(1,road2.pointX,road2.pointY);
			}
			else if(disx < 0 && disy==0){
				this.personGrid.moving(8,road2.pointX,road2.pointY);
			}
			else if(disx < 0 && disy < 0){
				this.personGrid.moving(2,road2.pointX,road2.pointY);
			}
			else if(disx==0 && disy < 0){
				this.personGrid.moving(5,road2.pointX,road2.pointY);
			}
			else if(disx > 0 && disy < 0){
				this.personGrid.moving(4,road2.pointX,road2.pointY);
			}
		}

		__proto.findNextCityId=function(arr){
			var isFind=false;
			for(var i=0;i < this.nextPathArr.length;i++){
				var g=this.getGridByXY(this.nextPathArr[i]);
				if(int(g.type)==/*functions.gvg.model.GridType.CITY*/0 && g.cityId !=this.startCityId){
					this.timer.stop();
					this.nextCityId=g.cityId;
					this.nextCityGrid=g;
					this.pathArr=this.nextPathArr.slice(0,i+1);
					if(i+1 < this.nextPathArr.length){
						this.nextPathArr=this.nextPathArr.splice(i+1);
					}
					else{
						this.nextPathArr=[];
					}
					for(i=0;i < this.pathArr.length;i++){
						var s=this.getGridByXY(this.pathArr[i]);
					}
					this.sendPlayerMoveMsg(this.startCityId,this.nextCityId);
					this.personGrid.stop();
					isFind=true;
					break ;
				}
			}
			return isFind;
		}

		__proto.walkRoadHandle=function(evt){
			console.log("move------------");
			if(this.pathArr.length==0){
				if(this.nextPathArr.length > 0){
					this.pathArr=this.nextPathArr;
					this.nextPathArr=[];
				}
				else{
					this.timer.stop();
					this.personGrid.stop();
					this.pathArr=[];
					this.isWalk=false;
					if(!this.isEnterFight && this.armyMoveStopCallBack !=null){
						this.armyMoveStopCallBack();
					}
					return;
				}
			};
			var obj=this.pathArr.shift();
			this.personGrid.type=/*functions.gvg.model.GridType.ROAD*/2;
			var ix=int(obj.x/ /*functions.gvg.model.GvgConfig.girdWidth*/25);
			var iy=int(obj.y/ /*functions.gvg.model.GvgConfig.girdHeight*/25);
			var grid=this.gridDic[ix+"_"+iy];
			this.removeRoadImg(ix,iy);
			if(this.pathArr.length > 0){
				this.showArmyMove(obj);
			}
			obj=null;
			if(int(grid.type)==/*functions.gvg.model.GridType.CITY*/0 && grid.cityId !=this.startCityId && this.pathArr.length==0){
				if(grid.cityId==this.nextCityId){
					this.startCityId=grid.cityId;
					this.nextCityId=grid.cityId;
					if(this.updateArmyCurrentCity !=null){
						this.updateArmyCurrentCity(grid.cityId);
					}
					console.log("isEnterFight======"+this.isEnterFight)
					var s=ServerTimeUitl.getInstance().getServerTimestamp();
					var timeString=StringUtil1.formatTime2(s,"YY-MM-dd hh:mm:ss:lll");
					Server.sendLocalConnection("stop move time=="+timeString);
					if(GvgConfig.isLoseFocus){
						this.setTroopPosition(grid.cityId);
					}
					if(this.isEnterFight){
						this.removeAllRoadImg();
						this.timer.stop();
						this.isWalk=false;
						this.personGrid.stop();
						this.startEnterFightFunc();
						return;
					};
					var isFind=false;
					isFind=this.findNextCityId(this.nextPathArr);
				}
			}
		}

		__proto.startSeekRoad=function(cityId){
			if(!this.checkRoleIsCanMove()){
				this.showErrorInfo(LanguageRunner.getLanguageText("GVG_FINGTING_CAN_NOT_MOVE"));
				return;
			}
			this.cityInRoadArr=[];
			var grid;
			/*for each*/for(var $each_grid in this.gridDic){
				grid=this.gridDic[$each_grid];
				if(grid.cityId==cityId && grid.isMainCity){
					this.targetIX=grid.ix;
					this.targetIY=grid.iy;
					console.log("seek raod   targtIX="+this.targetIX+"targetIY="+this.targetIY);
					var arr=this.seekRoad();
					if(arr.length==0){
						if(this.pathArr !=null && this.pathArr.length > 0 && this.nextCityGrid.ix==this.targetIX && this.targetIY==this.nextCityGrid.iy){
							console.log("正在移动到目标城市");
						}
						else{
							this.showErrorInfo(LanguageRunner.getLanguageText("GVG_CAN_NOT_FIGHT_ROAD"));
							return;
						}
					};
					var delRoadArr=[];
					if(this.nextPathArr.length > 0){
						for(var m=0;m < this.nextPathArr.length;m++){
							var isNotWalkRoad=this.checkIsNotWalkRoad(this.nextPathArr[m],arr);
							if(isNotWalkRoad){
								delRoadArr.push(this.nextPathArr[m]);
							}
						}
						if(delRoadArr.length > 0){
							for(var n=0;n < delRoadArr.length;n++){
								var g=this.getGrid(delRoadArr[n].x,delRoadArr[n].y);
								this.removeRoadImg(g.ix,g.iy,false);
							}
						}
					}
					this.drawPathFunc(arr);
					if(!this.isWalk){
						this.pathArr=arr;
						this.nextPathArr=[];
						for(var i=0;i < this.pathArr.length;i++){
							var obj=this.pathArr[i];
							var $ix=int(obj.x/ /*functions.gvg.model.GvgConfig.girdWidth*/25);
							var $iy=int(obj.y/ /*functions.gvg.model.GvgConfig.girdHeight*/25);
							var g2=this.gridDic[$ix+"_"+$iy];
							if(g2==null){
								Server.sendLocalConnection("GvgGrid === null "+$ix+"_"+$iy);
							}
							if(g2 !=null && int(g2.type)==/*functions.gvg.model.GridType.CITY*/0 && this.startCityId !=g2.cityId){
								if(i+1 < this.pathArr.length){
									this.nextPathArr=arr.slice(i+1);
									arr=arr.splice(i+1);
								}
								this.nextCityId=g2.cityId;
								this.nextCityGrid=g2;
								this.sendPlayerMoveMsg(this.startCityId,this.nextCityId);
								break ;
							}
						}
					}
					else{
						this.nextPathArr=arr;
						this.walkRoad();
					}
					return;
				}
			}
		}

