	//class functions.heroMass.view.RewardsItem extends iflash.display.Sprite
	var RewardsItem=(function(_super){
		function RewardsItem(){
			this.$y=5;
			this.addY=4;
			this.separatorThin1=null;
			this.label=null;
			RewardsItem.__super.call(this);
		}

		__class(RewardsItem,'functions.heroMass.view.RewardsItem',false,_super);
		var __proto=RewardsItem.prototype;
		__proto.showRewards=function(rewardsTypeList,fightType,$heroName){
			this.$y=5;
			DisplayUtil.removeAllChildrenToPool(this);
			var i=0;
			var dropMaterial;
			this.$y=this.$y+this.addY;
			var $x=1;
			var addHeight=54;
			var heroName=ObjectPool.borrow(Label);
			heroName.hasGlow=true;
			heroName.text=fightType+$heroName+":";
			heroName.x=$x;
			heroName.y=this.$y;
			this.$y+=heroName.textHeight+this.addY;
			this.addChild(heroName);
			if(rewardsTypeList.materialList.length > 0){
				var materialLabel=ObjectPool.borrow(Label);
				materialLabel.hasGlow=true;
				materialLabel.x=$x;
				materialLabel.y=this.$y;
				this.$y=materialLabel.y+materialLabel.textHeight+this.addY+18;
				materialLabel.fontColor=0x00ff00;
				materialLabel.text=LanguageRunner.getLanguageText("MATERIAL_LABEL");
				this.addChild(materialLabel);
			}
			var rewardMaterial;
			/*for each*/for(var $each_rewardMaterial in rewardsTypeList.materialList){
				rewardMaterial=rewardsTypeList.materialList[$each_rewardMaterial];
				dropMaterial=ObjectPool.borrow(MaterialIcon)
				dropMaterial.setData(rewardMaterial);
				dropMaterial.materialImg.bgImage.width=54;
				dropMaterial.materialImg.bgImage.height=54;
				dropMaterial.materialImg.fgImage.width=52;
				dropMaterial.materialImg.fgImage.height=52;
				dropMaterial.x=$x+(i%2)*65;
				dropMaterial.y=this.$y;
				this.$y=dropMaterial.y+(i%2)*(60+this.addY);
				dropMaterial.showEffect();
				this.addChild(dropMaterial);
				i++;
				if(i==rewardsTypeList.materialList.length && i%2==1){
					this.$y=dropMaterial.y+60+this.addY;
				}
			}
			i=0;
			var goodsName;
			var goodsNum;
			var goods;
			/*for each*/for(var $each_goods in rewardsTypeList.otherGoodsList){
				goods=rewardsTypeList.otherGoodsList[$each_goods];
				goodsName=ObjectPool.borrow(Label);
				goodsName.hasGlow=true;
				goodsNum=ObjectPool.borrow(Label);
				goodsNum.hasGlow=true;
				goodsName.x=$x;
				goodsName.y=this.$y+(i / 2)*30;
				goodsName.text=goods.goodsName+":";
				goodsName.fontColor=/*utils.ColorUtil.RGB_GREEN*/0x00ff00;
				goodsNum.x=goodsName.x+goodsName.textWidth+10;
				goodsNum.y=goodsName.y;
				goodsNum.text=goods.goodsNum.toString();
				goodsNum.fontColor=/*utils.ColorUtil.RGB_GREEN*/0x00ff00;
				this.$y=goodsNum.y+goodsNum.textHeight+this.addY;
				this.addChild(goodsName);
				this.addChild(goodsNum);
				i++;
			}
			i=0;
			var specialRewards;
			var specialRewardsVO;
			/*for each*/for(var $each_specialRewardsVO in rewardsTypeList.specialRewardsList){
				specialRewardsVO=rewardsTypeList.specialRewardsList[$each_specialRewardsVO];
				specialRewards=ObjectPool.borrow(Label);
				specialRewards.hasGlow=true;
				specialRewards.x=$x;
				specialRewards.y=this.$y;
				specialRewards.fontColor=0x00ff00;
				specialRewards.$width=130;
				specialRewards.multiline=true;
				specialRewards.wordWrap=true;
				specialRewards.text=LanguageRunner.getLanguageText(specialRewardsVO.caseDes);
				this.$y=specialRewards.numLines *18+specialRewards.y+2;
				this.addChild(specialRewards);
				i++;
			}
			this.label=ObjectPool.borrow(Label);
			this.label.$height=10;
			this.label.text=this.$y.toString();
			this.label.y=this.$y;
			this.label.visible=false;
			this.$y+=5;
			this.addChild(this.label);
			this.separatorThin1=ObjectPool.borrow(SeparatorThin);
			this.separatorThin1.width=127;
			this.separatorThin1.height=2;
			this.separatorThin1.x=2;
			this.separatorThin1.y=this.$y;
			this.separatorThin1.visible=false;
			this.$y+=this.addY;
			this.addChild(this.separatorThin1);
		}

		__proto.showLine=function(isShow){
			this.separatorThin1.visible=isShow;
		}

		return RewardsItem;
	})(Sprite)


