		__proto.updatePanel=function(carriageInfoVO){
			var toolId=carriageInfoVO.toolId;
			if(carriageInfoVO.isShow==1){
				this.viptipTxt1.visible=true;
				this.viptipTxt2.visible=true;
				}else {
				this.viptipTxt1.visible=false;
				this.viptipTxt2.visible=false;
			}
			this.refreshtipTxt.text=StringUtil1.format(LanguageRunner.getLanguageText("PROVENDER_REFRESH_GOLD"),carriageInfoVO.refreshCost,LanguageRunner.getLanguageText("GOLD"));
			this.transportTxt.text=LanguageRunner.getLanguageText("PROVENDER_TRANSPORT_TIME")+carriageInfoVO.cdtime.toString()+LanguageRunner.getLanguageText("PROVENDER_MINUTE");
			this.awardTxt.text=LanguageRunner.getLanguageText("PROVENDER_TRANSPORT_AWARD")+carriageInfoVO.awardSilver.toString()+LanguageRunner.getLanguageText("SILVER")+";"+carriageInfoVO.awardExploit.toString()+LanguageRunner.getLanguageText("MILITARY_EXPLOIT");
			this.w_bitmap_fade.visible=true;
			this.green_bitmap_fade.visible=true;
			this.b_bitmap_fade.visible=true;
			this.r_bitmap_fade.visible=true;
			this.g_bitmap_fade.visible=true;
			this.g_Txt.visible=false;
			this.green_Txt.visible=false;
			this.w_Txt.visible=false;
			this.b_Txt.visible=false;
			this.r_Txt.visible=false;
			switch(toolId){
				case 1:
					this.w_bitmap_fade.visible=false;
					this.w_Txt.visible=true;
					break ;
				case 2:
					this.green_bitmap_fade.visible=false;
					this.green_Txt.visible=true;
					break ;
				case 3:
					this.b_bitmap_fade.visible=false;
					this.b_Txt.visible=true;
					break ;
				case 4:
					this.r_bitmap_fade.visible=false;
					this.r_Txt.visible=true;
					break ;
				case 5:
					this.g_bitmap_fade.visible=false;
					this.g_Txt.visible=true;
					break ;
				}
		}

