				imageStronghold.mouseEffectBehavior=SkinRunner.buttonMouseEffectBehavior;
				imageStronghold.click=iflash.method.bind(this,this.strongholdClickFunction);
				imageStronghold.name=String(sh.id);
				imageStronghold.x=currentLinePoint.x+96 *sh.gridX;
				imageStronghold.y=currentLinePoint.y+37 *sh.gridX;
