		__proto.showSkillInfo=function(girl){
			this.skillNameLabel.text=girl.girlName;
			this.girlLevel.x=this.skillNameLabel.textWidth+30;
			this.girlDes.text=girl.girlDes;
			this.effectIcon.fgImage.image=girl.effectIcon;
			this.effectIcon.fgImage.x=3;
			this.effectIcon.fgImage.y=3;
			this.skillEffect.text="";
			if(girl.girlStatus !=/*functions.concubine.model.ConcubineGrilOpenStatus.OPEN*/4){
				ColorUtil.fadeColor(this.effectIcon)
			}
			else{
				ColorUtil.deFadeColor(this.effectIcon);
			};
			var remainTime=girl.getRemainEffectTime()-1;
			if(remainTime > 0){
				var day=remainTime/1000/3600/24;
				if(day > 1){
					day=Math.ceil(day);
				}
				this.skillRemainTime.before=LanguageRunner.getLanguageText("CONCUBINE_EFFECT_TIME");
				this.skillRemainTime.fontColor=/*utils.ColorUtil.RGB_GREEN*/0x00ff00;
				this.skillRemainTime.after="";
				if(day < 1){
					this.skillRemainTime.startCountDown(remainTime);
				}
				else{
					this.skillRemainTime.defaultTimeFormat="";
					this.skillRemainTime.text=LanguageRunner.getLanguageText("CONCUBINE_EFFECT_TIME")+day.toFixed(0)+LanguageRunner.getLanguageText("CONCUBINE_EFFECT_TIME_DAY");
					this.skillRemainTime.stopCountDown();
				}
			}
			else{
				this.skillRemainTime.before="";
				this.skillRemainTime.after="";
				this.skillRemainTime.clear();
			}
			for(var i=0;i < girl.effectTypeArr.length;i++){
				var info=girl.effectTypeArr[i];
				this.skillEffect.text+=info;
				if(i+1 !=girl.effectTypeArr.length){
					this.skillEffect.text+="\n";
				}
			}
			this.skillRemainTime.x=this.skillEffect.x;
			this.skillRemainTime.y=this.skillEffect.y+this.skillEffect.textHeight+4;
		}

