					renderVO.serverid=info.serverId;
					renderVO.junJie=info.armyGradeId;
					if(i==0){
						info.state=1;
					}
					else if(i==1){
						info.state=4;
					}
					else{
						info.state=3;
					}
					renderVO.state=info.state;
					renderVO.force=info.force;
