		__proto.pushForward=function(isAttacker,locationNum,completeFunc,time){
			var _$this=this;
			(time===void 0)&& (time=0.2);
			var forward;
			var forwardLocation=0;
			var backward;
			var backwardLocation=0;
			var xy;
			if(isAttacker){
				forward=this.attackTroopContainer;
				forwardLocation=this._attackerLocation;
				backward=this.defenderTroopContainer;
				backwardLocation=this._defenderLocation;
				}else {
				forward=this.defenderTroopContainer;
				forwardLocation=this._defenderLocation;
				backward=this.attackTroopContainer;
				backwardLocation=this._attackerLocation;
			};
			var oldX=forward.x;
			var oldY=forward.y;
			forwardLocation+=locationNum;
			xy=this._locateBehavior.getLocation(isAttacker,forwardLocation);
			TweenLite.killTweensOf(forward);
			TweenLite.to(forward,time,{x:xy.x,y:xy.y,onComplete:function (){
					if(forwardLocation+backwardLocation <=/*functions.countryHarassWar.model.CHWTroopLocateBehavior.MAX_DISTANCE_SUM*/20){
						if(completeFunc !=null)completeFunc();
						return;
					}
					backwardLocation-=locationNum;
					if(backwardLocation <=0)backwardLocation=3;
					forwardLocation=/*functions.countryHarassWar.model.CHWTroopLocateBehavior.MAX_DISTANCE_SUM*/20-backwardLocation;
					xy=_$this._locateBehavior.getLocation(!isAttacker,backwardLocation);
					TweenLite.killTweensOf(backward);
					TweenLite.to(backward,time,{x:xy.x,y:xy.y});
					xy=_$this._locateBehavior.getLocation(isAttacker,forwardLocation);
					TweenLite.killTweensOf(forward);
					TweenLite.to(forward,time *2,{x:xy.x,y:xy.y,onComplete:function (){
							_$this._attackerLocation=isAttacker ? forwardLocation :backwardLocation;
							_$this._defenderLocation=isAttacker ? backwardLocation :forwardLocation;
							if(completeFunc !=null)completeFunc();
					}});
			}});
		}

