		__proto.showBasicInfo=function(msg){
			if(msg.maxStage==100506 && msg.currStage==msg.maxStage){
				msg.maxStage=100511;
				msg.currStage=msg.maxStage;
			}
			this.haveKeyNum.text=msg.myKeys.toString();
			var obj=ClientDataProxy.getClientDataProxy().marsFloorDic[msg.currStage];
			if(obj==null){
				obj=ClientDataProxy.getClientDataProxy().marsFloorDic[msg.currStage-1];
			};
			var obj2=ClientDataProxy.getClientDataProxy().marsFloorDic[msg.maxStage];
			if(obj2==null){
				obj2=ClientDataProxy.getClientDataProxy().marsFloorDic[msg.maxStage-1];
			}
			this.maxFloorNum.text=LanguageRunner.getLanguageText(obj2.floor_name);
			this.curFloorNum.text=LanguageRunner.getLanguageText(obj.floor_name);
			this.setHeroCanAttack(int(msg.currStage.toString().substr(-1,1)));
			var maxTimes=ClientDataProxy.getClientDataProxy().marsGlobalDic[1]["glove_return_max"];
			var remainTimes=maxTimes-msg.resetTimes;
			if(msg.resetTimes==0){
				this.freeRestLabel.visible=true;
				this.remainTimeLabel.visible=this.remainTimesNum.visible=false;
			}
			else{
				this.freeRestLabel.visible=false;
				this.remainTimeLabel.visible=this.remainTimesNum.visible=true;
			}
			if(msg.resetTimes >=1){
				remainTimes=maxTimes-(msg.resetTimes-1);
			}
			if(remainTimes < 0){
				remainTimes=0;
			}
			this.remainTimesNum.text=remainTimes.toString();
		}

		__proto.updateremainTimesNum=function(value){
			this.remainTimesNum.text=value.toString();
		}

		__proto.showRoleVO=function(roleVO){
			if(this.goldNum==null){
				return;
			}
			this.goldNum.text=roleVO.gold;
			this.txtSilver.text=roleVO.silver;
			this.txtMilitaryExploit.text=roleVO.exploit;
		}

		__proto.updateMyKeyNum=function(key){
			if(this.haveKeyNum !=null){
				this.haveKeyNum.text=key.toString();
			}
		}

		__proto.setHeroCanAttack=function(index){
			for(var i=0;i < 5;i++){
				var heroBtn=this.heroArr[i];
				heroBtn.fadeImg.image.scaleX=heroBtn.fadeImg.image.scaleY=1;
				if(i+1==index){
					heroBtn.mouseEnabled=true;
					heroBtn.enabled=true;
				}
				else{
					heroBtn.mouseEnabled=false;
					heroBtn.enabled=false;
				}
			}
		}

