			var tokenFlag=0;
			if (roleVO.attack > 0)
				tokenFlag |=/*functions.role.view.RoleInfoFrameMediator.ATTACK_TOKEN*/1;
			if (roleVO.conquer > 0)
				tokenFlag |=/*functions.role.view.RoleInfoFrameMediator.CONQUER_TOKEN*/2;
			if (roleVO.warToken > 0)
				tokenFlag |=/*functions.role.view.RoleInfoFrameMediator.WAR_TOKEN*/4;
			if (roleVO.farmLand > 0)
				tokenFlag |=/*functions.role.view.RoleInfoFrameMediator.FARMLAND_TOKEN*/8;
			if (roleVO.silverOre > 0)
				tokenFlag |=/*functions.role.view.RoleInfoFrameMediator.SILVERORE_TOKEN*/16;
			if (roleVO.countryType==1){
				this.countryImg.image=ConfigConnect.LangType+"/"+/*data.Resources.FIRST_FACE_ROLEINFOFRAME_WEI_ROLE_PNG*/"first/face/roleInfoFrame/wei_role.png";
			}
			else if (roleVO.countryType==2){
				this.countryImg.image=ConfigConnect.LangType+"/"+/*data.Resources.FIRST_FACE_ROLEINFOFRAME_SHU_ROLE_PNG*/"first/face/roleInfoFrame/shu_role.png";
			}
