			this.imgTokenConquer.visible=((tokenFlag & /*functions.role.view.RoleInfoFrameMediator.CONQUER_TOKEN*/2)> 0);
			this.imgTokenWar.visible=((tokenFlag & /*functions.role.view.RoleInfoFrameMediator.WAR_TOKEN*/4)> 0);
			this.imgTokenFarmland.visible=((tokenFlag & /*functions.role.view.RoleInfoFrameMediator.FARMLAND_TOKEN*/8)> 0);
