	//class functions.gvg.model.GvgTroop extends functions.gvg.model.GvgGrid
	var GvgTroop=(function(_super){
		function GvgTroop($ix,$iy){
			this.force=1;
			this.campDirection=1;
			this.timer=null;
			this.count=1;
			this.targetX=0;
			this.targetY=0;
			this.gvgArmy=null;
			this.disX=NaN;
			this.disY=NaN;
			GvgTroop.__super.call(this,$ix,$iy);
			var url="gvg/troop/"+this.force+"/"+this.campDirection+"/1.png";
			this.gvgArmy=new GvgArmy(0,url);
			this.gvgArmy.x=-45;
			this.gvgArmy.y=-50;
			this.addChild(this.gvgArmy);
			this.timer=new Timer(GvgConfig.GVG_ARMY_MOVE_TIME_DELAY);
			this.timer.addEventListener(/*iflash.events.TimerEvent.TIMER*/"timer",__bind(this,this.timerHandler));
			this.mouseChildren=false;
			this.mouseEnabled=false;
		}

		__class(GvgTroop,'functions.gvg.model.GvgTroop',false,_super);
		var __proto=GvgTroop.prototype;
		__proto.setTimeDelay=function(timeNumber){
			this.timer.delay=timeNumber
		}

		__proto.addArmy=function($force,$campDirection){
			this.campDirection=$campDirection;
			this.force=$force;
		}

		__proto.startMoveing=function(){
			this.timer.start();
		}

		__proto.timerHandler=function(evt){
			this.gvgArmy.state=(this.gvgArmy.state==1 ? 2 :1);
			this.gvgArmy.updateSoldierBm("gvg/troop/"+this.force+"/"+this.campDirection+"/"+this.gvgArmy.state+".png");
			var tempX=this.x+this.disX *this.count;
			var tempY=this.y+this.disY *this.count;
			if(this.disX > 0){
				if(tempX > this.targetX){
					tempX=this.targetX;
				}
			}
			else{
				if(tempX <=this.targetX){
					tempX=this.targetX;
				}
			}
			if(this.disY > 0){
				if(tempY > this.targetY){
					tempY=this.targetY;
				}
			}
			else{
				if(tempY <=this.targetY){
					tempY=this.targetY;
				}
			}
			this.x=tempX;
			this.y=tempY;
			if(this.x==this.targetX && this.y==this.targetY){
				this.ix=int(this.x / /*functions.gvg.model.GvgConfig.girdWidth*/25);
				this.iy=int(this.y / /*functions.gvg.model.GvgConfig.girdHeight*/25);
				this.timer.stop();
			}
			else{
				this.count++;
			}
		}

		__proto.moving=function($campDirection,$x,$y){
			this.timer.stop();
			this.timer.start();
			this.count=1;
			this.campDirection=$campDirection;
			this.targetX=$x;
			this.targetY=$y;
			var splitTime=/*functions.gvg.model.GvgConfig.GVG_ONT_GIRD_SPLICE_NUM*/5
			if(Math.abs(($x-this.x))< splitTime){
				this.disX=0;
				this.x=this.targetX;
			}
			else{
				this.disX=($x-this.x)/ splitTime;
			}
			if(Math.abs(($y-this.y))< splitTime){
				this.disY=0;
				this.y=this.targetY;
			}
			else{
				this.disY=($y-this.y)/splitTime;
			}
		}

		__proto.stop=function(){
			this.timer.stop();
			this.count=1;
			this.gvgArmy.state=1;
			this.gvgArmy.updateSoldierBm("gvg/troop/"+this.force+"/"+this.campDirection+"/1.png");
		}

		__proto.setXY=function(valueX,valueY){
			this.timer.stop();
			this.x=valueX;
			this.y=valueY;
			this.ix=int(this.x / /*functions.gvg.model.GvgConfig.girdWidth*/25);
			this.iy=int(this.y / /*functions.gvg.model.GvgConfig.girdHeight*/25);
		}

		__proto.setColor=function(){
			this.mouseEnabled=false;
			this.mouseChildren=false;
		}

		__getset(0,__proto,'ix',function(){
			return this._ix;
			},function(value){
			this._ix=value;
		});

		__getset(0,__proto,'iy',function(){
			return this._iy;
			},function(value){
			this._iy=value;
		});

		return GvgTroop;
	})(GvgGrid)


