			this._effect4Cd.url=/*data.Resources.ANIMATION_CAMPAIGNCD_PNG*/"animation/campaignCDEffect.png";
			this._effect4Cd.cellWidth=37;
			this._effect4Cd.cellHeight=37;
			this._effect4Cd.delay=100;
			this.attackBGArr=[];
			this.actionBGArr=[];
			this.timer=new EnterFrameTimer(100);
