		__proto.updateAfterLoad=function(){
			var obj;
			/*for each*/for(var $each_obj in this.tempWorldMapDict){
				obj=this.tempWorldMapDict[$each_obj];
				this.worldMapDict[obj.realID]=obj;
			}
			DisplayUtil.removeAllChildren(this.cityLayer);
			this.forceWEILayer.graphics.clear();
			this.forceSHULayer.graphics.clear();
			this.forceWULayer.graphics.clear();
			this.forceNONELayer.graphics.clear();
			ObjectUtil.clearList(this.citys);
			ObjectUtil.clearList(this.cells);
			var whole=85;
			var half=85 / 2;
			var halfRoot3=Math.sqrt(3)*85 / 2;
			var _color=0x000000;
			for (var i=0;i < 16;i++){
				for (var j=0;j < 18;j++){
					var cell=new WorldCellView();
					var key=(j+1)*100+(i+1);
					var value=this.tempWorldMapDict[key];
					var force=0;
					if (value !=null){
						force=value.force;
						if (value.type !=/*functions.world.model.WorldMapType.ROUTE*/5 && value.type !=/*functions.world.model.WorldMapType.BARRIER*/6 && value.type !=/*functions.world.model.WorldMapType.CAPITAL*/8){
							var city=new Image2(value.id);
							if (value.type==/*functions.world.model.WorldMapType.SILVERORE*/4 || value.id==1009){
								city.mouseEffectBehavior=SkinRunner.noneMouseEffectBehavior;
								city.click=null;
								city.buttonMode=false;
								if(value.id==1009){
									city.click=iflash.method.bind(this,this.cityClickHandler);
									city.buttonMode=true;
									city.filters=[WorldView.GLOW_COLOR_YELLOW];
								}
								}else {
								city.click=iflash.method.bind(this,this.cityClickHandler);
								city.buttonMode=true;
							}
							city.data=value;
							city.image="world/"+value.image+".png";
							city.x=value.imageX;
							city.y=value.imageY;
							this.cityLayer.addChild(city);
							this.citys.push(city);
							var txtCityName=new CoreTextField(/*iflash.text.TextFieldAutoSize.CENTER*/"center");
							txtCityName.isShowGlow=true;
							txtCityName.mouseEnabled=false;
							switch(value.type){
								case /*functions.world.model.WorldMapType.CITY*/1:
								case /*functions.world.model.WorldMapType.CAPITAL*/8:
									txtCityName.x=value.imageX+104*0.46;
									txtCityName.y=value.imageY+77*0.31;
									break ;
								case /*functions.world.model.WorldMapType.ACROPOLIS*/7:
									txtCityName.x=value.imageX+190*0.46;
									txtCityName.y=value.imageY+122*0.31;
									break ;
								case /*functions.world.model.WorldMapType.FORTREE*/2:
									txtCityName.x=value.imageX+142*0.5;
									txtCityName.y=value.imageY+83*0.34;
									break ;
								case /*functions.world.model.WorldMapType.FARMLAND*/3:
									txtCityName.x=value.imageX+133*0.46;
									txtCityName.y=value.imageY+102*0.4;
									break ;
								default :
									break ;
								}
							txtCityName.text=value.name;
							this.cityLayer.addChild(txtCityName);
							if (value.flagX !=0 && value.flagY !=0 && value.id !=1009 && value.image !="100300"){
								var flag=new NationFlag();
								if ((value instanceof functions.world.model.WorldMapFarmVO )){
									flag.init(value.force,(value).flag);
									}else {
									flag.init(value.force);
								}
								flag.x=value.imageX+value.flagX;
								flag.y=value.imageY+value.flagY;
								this.cityLayer.addChild(flag);
							}
						}
					}
					cell.whole=whole;
					cell.half=half;
					cell.halfRoot3=halfRoot3;
					cell.force=force;
					this.cells.push(cell);
				}
			};
			var cellNumH=18;
			var cellSideLength=85;
			var cellDistance=2;
			var root3=Math.sqrt(3);
			var targetPoint=new Point();
			for (var c=0;c < this.cells.length;c++){
				var target=this.cells[c];
				var indexH=c % cellNumH;
				var indexV=int(c / cellNumH);
				targetPoint.x=indexH *(1.5 *cellSideLength+cellDistance / Math.cos(Math.PI / 6));
				targetPoint.y=(indexV+(1-indexH % 2)/ 2)*root3 *(cellSideLength+cellDistance);
				targetPoint.x+=500;
				targetPoint.y+=300;
				var targetBgLayer;
				var targetLayer;
				var targetLineLayer;
				var targetLineColor=0;
				switch (target.force){
					case 1:
						targetBgLayer=this.forceWEIBgLayer;
						targetLayer=this.forceWEILayer;
						targetLineLayer=this.forceWEILineLayer;
						targetLineColor=0x22A7D2;
						break ;
					case 2:
						targetBgLayer=this.forceSHUBgLayer;
						targetLayer=this.forceSHULayer;
						targetLineLayer=this.forceSHULineLayer;
						targetLineColor=0xff0000;
						break ;
					case 4:
						targetBgLayer=this.forceWUBgLayer;
						targetLayer=this.forceWULayer;
						targetLineLayer=this.forceWULineLayer;
						targetLineColor=0x33DC4B;
						break ;
					default :
						continue ;
						break ;
					};
				var startX=targetLayer.x+targetPoint.x;
				var startY=targetLayer.y+targetPoint.y;
				targetBgLayer.graphics.beginFill(0x000000,0.00);
				targetBgLayer.graphics.moveTo(startX+(-half),startY+(-halfRoot3));
				targetBgLayer.graphics.lineTo(startX+half+3,startY+(-halfRoot3));
				targetBgLayer.graphics.lineTo(startX+whole+2,startY+0);
				targetBgLayer.graphics.lineTo(startX+half+3,startY+halfRoot3+3);
				targetBgLayer.graphics.lineTo(startX+(-half),startY+halfRoot3+3);
				targetBgLayer.graphics.lineTo(startX+(-whole),startY+0+2);
				targetBgLayer.graphics.lineTo(startX+(-half),startY+(-halfRoot3));
				targetBgLayer.graphics.endFill();
				targetLayer.graphics.lineStyle(4,targetLineColor,0.1);
				targetLayer.graphics.beginFill(targetLineColor,0.1);
				targetLayer.graphics.moveTo(startX+(-half),startY+(-halfRoot3));
				targetLayer.graphics.lineTo(startX+half+3,startY+(-halfRoot3));
				targetLayer.graphics.lineTo(startX+whole+2,startY+0);
				targetLayer.graphics.lineTo(startX+half+3,startY+halfRoot3+3);
				targetLayer.graphics.lineTo(startX+(-half),startY+halfRoot3+3);
				targetLayer.graphics.lineTo(startX+(-whole),startY+0+2);
				targetLayer.graphics.lineTo(startX+(-half),startY+(-halfRoot3));
				targetLayer.graphics.endFill();
				targetLineLayer.graphics.lineStyle(1,targetLineColor,1);
				targetLineLayer.graphics.beginFill(0x000000,0.0);
				targetLineLayer.graphics.moveTo(startX+(-half),startY+(-halfRoot3));
				targetLineLayer.graphics.lineTo(startX+half+3,startY+(-halfRoot3));
				targetLineLayer.graphics.lineTo(startX+whole+2,startY+0+2);
				targetLineLayer.graphics.lineTo(startX+half+3,startY+halfRoot3+3);
				targetLineLayer.graphics.lineTo(startX+(-half),startY+halfRoot3+3);
				targetLineLayer.graphics.lineTo(startX+(-whole),startY+0+2);
				targetLineLayer.graphics.lineTo(startX+(-half),startY+(-halfRoot3));
				targetLineLayer.graphics.endFill();
			}
		}

