					this.gridZhuque.y=clVO.zhuqueY;
					if (this.matchUnion(countryTVO.zhuque,countryTVO.armyInfos)!=null){
						var armyinfo2=this.matchUnion(countryTVO.zhuque,countryTVO.armyInfos);
						unionvo.id=armyinfo2.armyId;
						unionvo.name=armyinfo2.armyName;
						unionvo.iconLevel=armyinfo2.shorNameLevel;
						unionvo.iconImg="union/"+"junhui"+armyinfo2.shorNameLevel.toString()+".jpg";
						unionvo.iconName=armyinfo2.shortName;
						this.gridZhuque.update(unionvo);
						this.gridZhuque.toolTip=TipUtil.getTextTipVO(LanguageRunner.getLanguageText("ZHUQUE_UNION")+":"+unionvo.iconName);
					}
