					if(this.txtGuXun6.visible){
						var addY=equipVO.guxuns[6].split("<br/>").length;
						this.separatorThin2.y=this.txtGuXun6.y+20*addY;
						this.txtGuXun7.y+=20 *(addY-1);
					}
					else{
						this.separatorThin2.y=this.txtGuXun5.y+20;
					}
					if(this.txtGuXun7.visible){
						this.separatorThin2.y=this.txtGuXun7.y+20;
					}
					this.setPositionBottom();
