			DisplayUtil.removeAllChildren(this.attackForceContainer);
			DisplayUtil.removeAllChildren(this.defForceContainer);
			this.zhaojiRoleNameText.text=info.zhaojiRoleName;
			var currentTimestamp=ServerTimeUitl.getInstance().getServerTimestamp();
			var timeNum=Number(info.endTime)-currentTimestamp;
			if(timeNum > 0){
				this.time.startCountDown(timeNum);
				this.joinWarButton.enabled=true;
			}
			else{
				this.joinWarButton.enabled=false;
			}
